export default [{"id":3531,"title":"طوفان عظيم من ناحية بحر الهند .","date":["العام الهجري :901","العام الميلادي :1495"],"text":"حصل طوفان عظيم من ناحية بحر الهند غرق منه في بندر الديو عشرة مراكب، وفي الباحة أربعة مراكب، وتلف فيها من الأموال ما لا ينحصر، وتغيرت أربعة مراكب، وانكسرت أدقالهم، ورموا من حملهم أكثر من النصف."},{"id":3532,"title":"العثمانيون يسيطرون على البوسنة ودخول أمير البغدان في حمايتهم .","date":["العام الهجري :901","العام الميلادي :1495"],"text":"بعد أن كانت العلاقات بين العثمانيين والبولنديين قد توطدت سنة 895 إلا أنها لم تلبث كثيرًا حتى بدأ الخلاف بينهما؛ بسبب الحماية على البغدان؛ فكل من الطرفين يدعي الحماية عليها، ولكن أمير البغدان اعترف بالحماية العثمانية، وحارب إلى جانب العثمانيين ضد البولنديين، واستطاعوا أن يصدوا البولنديين ويستولوا على البوسنة؛ مما أكسب الدولة العثمانية قوة إلى قوتها، فبدأ خصومها يتقربون إليها بعقد الحلف معها للإفادة منها في قتال خصومها، وخاصة الإمارات الإيطالية."},{"id":3533,"title":"وفاة السلطان الأشرف قايتباي وسلطنة ابنه الناصر محمد .","date":["العام الهجري :901","الشهر القمري : ذي القعدة","العام الميلادي :1496"],"text":"هو السلطان الأشرف قايتباي المحمودي، ويُذكر أن أصله شركسي الجنس، جُلب من بلاده إلى الديار المصرية في حدود سنة 839، فاشتراه الملك الأشرف برسباي، ولم يُجرِ عليه عتقًا، وجعله بطبقة الطازية من أطباق قلعة الجبل إلى أن مَلَكه الملك الظاهر جقمق، وأعتقه. كانت مدة حكم الأشرف قايتباي حافلة بالحروب، وسيرتُه من أطول السير، وقد تعرضت البلاد في أيامه لأخطار خارجية، أشدها محاولة العثمانيين احتلال حلب وما حولها، فأنفق أموالًا عظيمة على الجيوش لم يُسمَع بمثلها في الإنفاق، وشُغِل السلطان الأشرف قايتباي بالعثمانيين، حتى إن صاحب الأندلس استغاث به لإعانته على دفع الفرنج عن غرناطة، فاكتفى الأشرف بالالتجاء إلى تهديد فرنج الأسبان بواسطة القسيسين الذين في القدس، سلمًا دون قتال، حتى ضاعت غرناطة وذهبت الأندلس. كان الأشرف قايتباي متقشفًا مع عِظَم إنفاقه على الجيوش وكثير المطالعة، وله اشتغال بالعلم، وفيه نزعة صوفية، كما كان شجاعًا عارفًا بأنواع الفروسية، مَهيبًا عاقلًا حكيمًا، إذا غضب لم يلبث أن تزول حِدَّتُه. ترك كثيرًا من آثار العمران في مصر وأبرزها قلعة قايتباي بالإسكندرية والحجاز والشام والقدس، ولا يزال بعضها قائمًا إلى الآن. قبل أن يُتوفى الأشرف قايتباي تنازل بالسلطنة لولده محمد الذي تلقب بالناصر، وتوفي الأشرف في اليوم التالي، وكان عمر الناصر محمد يومها أربعة عشر عامًا، أما مدة سلطنة الأشرف قايتباي فكانت تسعة وعشرين سنة وأربعة أشهر."},{"id":3534,"title":"خلع السلطان الناصر محمد وتسلطن الأشرف قانصوه .","date":["العام الهجري :902","الشهر القمري : جمادى الأولى","العام الميلادي :1497"],"text":"بعد أن استطاع قانصوه من إقناع قايتباي بتولية ابنه محمد السلطنة؛ ليكون هو الوصي والأتابك للعساكر، أخذ يخطط ليتسلطن هو، فتخلص من الأمراء المنافسين له، ثم دعا الخليفة العباسي والقضاة الأربعة وأقنعهم بضرورة تغيير السلطان لخلاعته والفوضى التي سارت في البلاد، فتم خلعه وتولية قانصوه السلطنة، وتلقب بالملك الأشرف."},{"id":3535,"title":"خلع السلطان الأشرف قانصوه وإعادة الناصر محمد .","date":["العام الهجري :902","الشهر القمري : جمادى الآخرة","العام الميلادي :1497"],"text":"بعد أن استطاع قانصوه أن يخلع السلطان محمد بن قايتباي، وأراد أن يتسلطن ولم يبق له إلا الركوب بشعار السلطنة والصعود إلى القلعة للجلوس على العرش، إلا أنه اصطدم بمعارضة المماليك السلطانية الذين رفضوا الاعتراف بخطوته التي فعلها، فمنعوه من دخول القلعة بعد قتال أمام أسوارها استمر ثلاثة أيام، حتى انهزم قانصوه وجُرح وهرب مع أتباعه إلى فلسطين، فقام الخليفة والقضاة بتجديد البيعة للسلطان محمد بن قايتباي."},{"id":3536,"title":"وفاة الإمام العلامة شمس الدين السخاوي .","date":["العام الهجري :902","الشهر القمري : شعبان","العام الميلادي :1497"],"text":"هو الإمام العلامة شمس الدين أبو الخير محمد بن عبد الرحمن بن محمد السخاوي القاهري أصله من سخا من قرى مصر، ولد بالقاهرة في ربيع الأول سنة 831 بحارة مجاورة لمدرسة شيخ الإسلام البلقيني محل أبيه وجده، ثم تحول منه حين دخل في الرابعة مع أبويه لمِلْك اشتراه أبوه مجاور لسكن شيخه ابن حجر، وأدخله أبوه المكتب بالقرب من الميدان عند المؤدب الشرف عيسى بن أحمد المقسي الناسخ، فأقام عنده يسيرًا جدًّا، ثم نقله لزوج أخته الفقيه الصالح البدر حسين بن أحمد الأزهري فقرأ عنده القرآن وصلى بالناس التراويح في رمضان، ثم توجه به أبوه لفقيهه المجاور لسكنه الشيخ المفيد النفاع القدوة المؤدب الشمس محمد بن أحمد النحريري الضرير, ثم لازم شيخه إمام الأئمة الشهاب ابن حجر العسقلاني حيث كان يسمع منه مع والده ليلًا الكثير من الحديث، فكان أول ما وقف عليه من ذلك في سنة ثمان وثلاثين، وأوقع الله في قلبه محبته فلازم مجلسه وعادت عليه بركته في هذا الشأن فأقبل عليه بكليته إقبالًا يزيد على الوصف؛ بحيث تقلل مما عداه, وداوم الملازمة لشيخه ابن حجر حتى حمل عنه علمًا جمًّا اختص به كثيرًا بحيث كان من أكثر الآخذين عنه، وأعانه على ذلك قُرب منزله منه، فكان لا يفوته مما يقرأ عليه إلا النادر، إما لكونه حمله أو لأن غيره أهم منه وينفرد عن سائر الجماعة بأشياء. ولما علم شيخه ابن حجر شدة حرصه على ذلك كان يرسل خلفه أحيانًا بعض خدمه لمنزله يأمره بالمجيء للقراءة, وكان شيخه يأذن له في الإقراء والإفادة والتصنيف، وصلى به إمامًا التراويح في بعض ليالي رمضان, وتدرب به في طريق القوم ومعرفة العالي والنازل والكشف عن التراجم والمتون وسائر الاصطلاح, وأخذ عنه علم الحديث وبرع فيه، ولم ينفك عن ملازمته ولا عدل عنه بملازمة غيره من علماء الفنون؛ خوفًا على فقده، ولا ارتحل إلى الأماكن النائية، بل ولا حجَّ إلا بعد وفاة شيخه ابن حجر, ومع ذلك حمل السخاوي عن شيوخ مصر والواردين إليها كثيرًا من دواوين الحديث وأجزائه بقراءته وقراءة غيره في الأوقات التي لا تعارض أوقات شيخه، سيما حين اشتغال شيخه بالقضاء وتوابعه، حتى صار السخاوي أكثر أهل العصر مسموعًا وأكثرهم رواية، ولما عاد السخاوي سنة تسع وتسعين للقاهرة من الحج للمرة السادسة والمجاورة في المدينة انجمع عن الناس وامتنع من الإملاء لمزاحمة من لا يحسن فيها وعدم التمييز من جُل الناس أو كلهم, وراسل إلى من لامه على ترك الإملاء بما نصه: \"إنه ترك ذلك عند العلم بإغفال الناس لهذا الشأن؛ بحيث استوى عندهم ما يشتمل على مقدمات التصحيح وغيره من جمع الطرق التي يتبين بها انتفاء الشذوذ والعلة أو وجودهما، مع ما يورد بالسند مجردًا عن ذلك، وكذا ما يكون متصلًا بالسماع مع غيره, وكذا العالي والنازل والتقيد بكتاب ونحوه مع ما لا تقيد فيه إلى غيرها، مما ينافي القصد بالإملاء وينادي الذاكر له العامل به على الخالي منه بالجهل\". كما أنه التزم ترك الإفتاء مع الإلحاح عليه فيه حين تزاحم الصغار على ذلك واستوى الماء والخشبةَ، سيما وإنما يعمل بالأغراض، بل صار يكتُب على الاستدعاءات وفي عرض الأبناء من هو في عدادِ من يلتمس له ذلك حين التقيد بالمراتب والأعمال بالنيات، وقد سبقه للاعتذار بنحو ذلك شيخ شيوخه الزين العراقي وكفى به قدوة، بل وأفحش من إغفالهم النظر في هذا وأشد في الجهالة إيراد بعض الأحاديث الباطلة على وجه الاستدلال وإبرازها حتى في التصانيف والأجوبة، كل ذلك مع ملازمة الناس له في منزله للقراءة دراية ورواية في تصانيفه وغيرها، بحيث خُتم عليه ما يفوق الوصف من ذلك، وأخذ عنه من الخلائق من لا يُحصى\" وقد حدث خلاف بين السخاوي ومعاصره جلال الدين السيوطي، وهو من خلاف الأقران الذي لا يُقبَل فيه نقد أحدهما في الآخر مع جلالة قدر كل منهما في علمه وعمله في خدمة العلم وأهله. وللسخاوي مصنفات كثيرة جدًّا منها ترجمة لشيخه ابن حجر في كتاب سماه الجوهر والدرر في ترجمة شيخ الإسلام ابن حجر، والقول البديع في الصلاة على الحبيب الشفيع، والمقاصد الحسنة في الأحاديث المشتهرة على الألسنة، وفتح المغيث بشرح ألفية الحديث للعراقي، ووجيز الكلام في الذيل على دول الإسلام، والضوء اللامع في أخبار أهل القرن التاسع، واستجلاب ارتقاء الغرف بحب أقرباء الرسول وذوي الشرف، وغيرها من الكتب والسؤالات المدونة له. توفي بالمدينة عصر يوم الأحد 28 من شعبان سنة 902 (1497م) وهو في الحادية والسبعين من عمره، ودُفِن بالبقيع بجوار الإمام مالك."},{"id":3537,"title":"السلطانِ عامر بن عبد الوهاب يعزر رئيسَ الإسماعيلية بمدينة تعز .","date":["العام الهجري :902","الشهر القمري : ذي القعدة","العام الميلادي :1497"],"text":"أمر السلطانُ عامر بن عبد الوهاب بتقييد رئيس الإسماعيليةِ سليمان بن حسن بمدينة تعز، وأودعه دار الأدبِ، وكان يتحدث بما لا يعنيه من المغيبات المستقبلات، وكان عالمَ الإسماعيلية، فأمر السلطانُ عامر بإحضار كتبِه وإتلافها، فأُتلِفت، والحمد لله."},{"id":3538,"title":"وفاة الخليفة المتوكل وتولي ابنه يعقوب .","date":["العام الهجري :903","الشهر القمري : محرم","العام الميلادي :1497"],"text":"هو الخليفة المتوكل على الله عبد العزيز بن يعقوب بن محمد المتوكل، وكان قد بقي في الخلافة تسع عشرة سنة وأيامًا، وتولى بعده ابنه يعقوب وتلقب بالمستمسك بالله أبو الصبر."},{"id":3539,"title":"إعلان التنصير القسري لأهل الأندلس المسلمين .","date":["العام الهجري :904","العام الميلادي :1498"],"text":"كان تسليم غرناطة للملك فرديناند ملك أراغون والملكة إيزابيلا ملكة قشتالة بناء على معاهدة، لكن فرديناند وزوجته لم يَفيَا بهذه العهود، بل أصدرت إيزابيلا قانونًا يقضي بإجبار المسلمين على التنصر وتحريم إقامة شعائرهم الدينية، وتأمر كذلك بإحراق الكتب الإسلامية في غرناطة, وبعد أن نقض فرديناند شروط تسليم غرناطة شرطًا شرطًا بدا بدعوة المسلمين إلى التنصر وأكرههم عليه فدخلوا في دينه كرهًا وصارت الأندلس كلها نصرانية، ولم يبق من يقول فيها لا إله إلا الله محمد رسول الله صلى الله عليه وسلم جهارًا إلا من يقولها في نفسه وفي قلبه أو خفيةً من الناس!! وجعلت النواقيس بدل الأذان في مساجدِها والصور والصلبان بعد ذكر الله تعالى وتلاوة القرآن، فكم فيها من عينٍ باكية! وكم فيها من قلب حزين! وكم فيها من الضعفاء والمعدومين لم يقدروا على الهجرة واللحوق بإخوانهم المسلمين! قلوبهم تشتعل نارًا ودموعهم تسيل سيلًا غزيرًا مدرارًا، وينظرون أولادهم وبناتهم يعبدون الصلبان ويسجدون للأوثان ويأكلون الخنزير والميتات ويشربون الخمر التي هي أم الخبائث والمنكرات فلا يقدرون على منعهم ولا على نهيهم ولا على زجرهم! ومن فعل ذلك عوقب أشد العقاب، فيا لها من فاجعة ما أمرَّها ومصيبةٍ ما أعظمَها وأضرَّها وطامَّةٍ ما أكبَرَها! عسى الله أن يجعل لهم من أمرهم فرجًا ومخرجًا، إنه على كل شيء قدير.  وقد كان بعض أهل الأندلس قد امتنعوا من التنصر وأرادوا أن يدافعوا عن أنفسهم كأهل قرى ونجر والبشرة وأندراش وبلفيق، فجمع الملك فرديناند عليهم جموعه وأحاط بهم من كل مكان حتى أخذهم عنوة بعد قتال شديد فأخذ أموالهم وقتل رجالهم وسبى نساءهم وصبيانهم ونصَّرهم واستعبدهم إلا أن أناسًا في غربي الأندلس امتنعوا من التنصر وانحازوا إلى جبل منيع وعر فاجتمعوا فيه بعيالهم وأموالهم، وتحصنوا فيه فجمع عليهم الملك فرديناند جموعه وطمع في الوصول إليهم كما فعل بغيرهم، فلما دنا منهم وأراد قتالهم خيب الله سعيه ورده على عَقِبه ونصرهم عليه بعد أكثر من ثلاثة وعشرين معركة، فقتلوا من جنده خلقًا كثيرًا من رجال وفرسان! فلما رأى أنه لا يقدر عليهم طلب منهم أن يعطيهم الأمان ويجوزهم لعدوة الغرب مؤمَّنين فأنعموا له بذلك إلا أنه لم يسَرِّح لهم شيئًا من متاعهم غير الثياب التي كانت عليهم وجوَّزهم لعدوة الغرب كما شرطوا عليه، ولم يطمع أحد بعد ذلك أن يقوم بدعوة الإسلام، وعمَّ الكفرُ جميع القرى والبلدان وانطفأ من الأندلس نور الإسلام والإيمان، فعلى هذا فليبك الباكون، ولينتحب المنتحبون، كما انتحب شاعر الأندلس أبو البقاء الرندي (ت684) في قصيدته المشهورة التي رثا فيه الأندلس بعد سقوط قرطبة سنة 633 ومدن كبرى كإشبيلية وبلنسية وغيرها بيد الفرنج، والتي مطلعها: (لكل شيء إذا ما تم نقصانُ * فلا يغرَّ بطيبِ العيشِ إنسانُ)، فإنا لله وإنا إليه راجعون! كان ذلك في الكتاب مسطورًا، وكان أمر الله قدَرًا مقدورًا، لا مردَّ لأمره ولا معقِّبَ لحكمِه، وهو القاهر فوق عباده وهو الحكيم الخبير، ولا حول ولا قوة إلا بالله العلي العظيم!!"},{"id":3540,"title":"مقتل السلطان الناصر محمد وتسلطن الظاهر قانصوه الأشرفي .","date":["العام الهجري :904","الشهر القمري : ربيع الأول","العام الميلادي :1498"],"text":"أساء السلطان الناصر محمد السيرة حتى أفحش في السوء، فقتل الجواري وارتكب الفواحش وأساء التدبير، حتى تمالأ الأمراء على خلعه وقتله، ثم في اليوم الخامس عشر ربيع الأول من هذه السنة خرج من قصره فهجم عليه جماعة من المماليك فقتلوه بسيوفهم وعُمُره يومَها سبعة عشر عامًا، وتولى السلطنة بعده قنصوه الأشرفي الذي اتفق الأمراء على توليته السلطنة بعد قتل الناصر محمد، فبويع بالسلطنة وتلقب بالملك الظاهر أبي سعيد قانصوه الأشرفي، فكانت مدة سلطنة الناصر محمد قرابة السنتين بما تخللها من خلعِه ثم إعادته!"},{"id":3541,"title":"بايزيد الثاني يضم مدينة ليبانتو اليونانية ويواجه تحالفًا صليبيًّا .","date":["العام الهجري :905","العام الميلادي :1499"],"text":"استطاع بايزيد أن يحرز نصرًا بحريًّا على البنادقة في خليج ليبانتو ببلاد اليونان, واستولى على مدينة ليبانتو، وباستيلاء العثمانيين على مواقع البنادقة في اليونان، أقام البابا إسكندر السادس- بناء على طلب البنادقة- حلفًا ضد العثمانيين مكونًا من فرنسا وإسبانيا، وتعرض العثمانيون لهجوم الأساطيل الثلاثة: الفرنسي والإسباني والبابوي، واستطاعت الدولة العثمانية أن تعقد صلحًا مع البنادقة."},{"id":3542,"title":"خلع السلطان الظاهر قانصوه الأشرفي وتسلطن الأشرف جانبلاط .","date":["العام الهجري :905","الشهر القمري : ذي الحجة","العام الميلادي :1500"],"text":"قام الأمراء الذين ولَّوا الأشرف قانصوه السلطنة بخلعِه في هذه السنة، وكان قد هرب منهم ولكنهم قبضوا عليه فأُرسل إلى سجن الإسكندرية، ثم قُتل فيه خنقًا، فكانت مدة سلطنته سنة وثمانية أشهر، فبايعوا بعده جانبلاط الذي كان أتابك العساكر، فتلقب بالسلطان الأشرف أبي النصر جانبلاط."},{"id":3543,"title":"وفاة المعلم أحمد بن ماجد النجدي  .","date":["العام الهجري :906","العام الميلادي :1500"],"text":"هو المعلم أسد البحر شهاب الدين أحمد بن ماجد بن محمد السَّعْدي النجدي، من نجد عُمان، ويقال له السائح ماجد، وهو من علماءِ فنِّ الملاحة وتاريخه عند العربِ، ومِن كبارِ ربابنةِ العرب في البحر الأحمر والخليج العربي والمحيط الهندي وخليج البنغال وبحر الصين. ولِدَ ابنُ ماجد عام 821هـ بنجد عُمان في عائلة تهتمُّ بركوب البحر، فكان أبوه وجَدُّه ملاحَينِ مشهورين، ولابن ماجد الفضلُ في إرساء قواعد الملاحة للعالم، وقد بقيت آراؤه وأفكاره في مجال الملاحة سائدةً في كلٍّ من البحر الأحمر والخليج العربي وبحر الصين. وهو أوَّلُ من كتب في المرشدات البحرية الحديثة، وصنَّف (الفوائد في أصول علم البحر والقواعد)، وأرجوزةً سمَّاها (حاوية الاختصار في أصول علم البحار) و(الأرجوزة السبعية) و(القصيدة المسماة بالهدية) و(أرجوزة بر العرب في خليج فارس)، و(المراسي على ساحل الهند الغربية) ورسائلَ أخرى. أما ما أُشيع من أنَّ ابن ماجد أرشد قائِدَ الأسطول البرتغالي فاسكو دي غاما إلى طريقِ الهند: فهو باطِلٌ وغير صحيحٍ، قال أحمد علاونة: \"هو قول باطل مدارُه على النهروالي في كتابه (البرق اليماني في الفتح العثماني) وقد ذكر هذه الأسطورةَ بعد ثمانين سنة من حدوثِها، ولم يذكر أيُّ مؤرِّخٍ بعد النهروالي هذه الأسطورة، ثم جاء المستشرق فران عام 1922 ونفخ فيها من روحِه وتابعه عليها كثيرون منهم الزِّركْلي\" وقد أورد العلاونة بعض الأدلة على بطلان إرشاد ابن ماجد لفاسكو دي غاما منها: أ- أن الروايةَ ذكَرت أنَّ ابن ماجد أرشد دي غاما وهو سكران، وهذا غير معقول أن يطمئنَّ قائد عسكري لفاقد الوعي ليدلَّه على طريق محفوف بالمخاطر. ب- لم تكن لابن ماجد خبرةٌ في الساحل الإفريقي. ج- لم يرد ذكر هذه الحادثة في أي من أعمال ابن ماجد النثرية والشعرية. د- كان ابن ماجد يعرِفُ حَقَّ المعرفة نوايا البرتغاليين وما يضمرونه من شَرٍّ للمسلمين. ه- لا يوجد مؤرِّخٌ برتغالي ممَّن عاصروا دي غاما وعُنُوا بتاريخ رحلاته أو ممَّن جاؤوا على آثارهم ذكروا أحمد بن ماجد. و- عاصر وصول البرتغاليين إلى المحيط الهندي عددٌ من المؤرخين العرب، ومنهم من عاصر ابن ماجد، ولم يذكُرْ أيٌّ منهم صلةَ ابن ماجد بالبرتغاليين."},{"id":3544,"title":"خلع السلطان الأشرف جانبلاط وتسلطن طومان باي .","date":["العام الهجري :906","الشهر القمري : جمادى الآخرة","العام الميلادي :1501"],"text":"قام الأمير قوصروه نائب دمشق بالانشقاق والخروج عن طاعة السلطان الأشرف جانبلاط وأعلن نفسه سلطانًا فيها، لكن السلطان جانبلاط قام بتجهيز جيش بقيادة طومان باي ومعه الأمير قانصوه الغوري فسارا إلى الشام، ولما وصل طومان باي اتفق مع الأمير قوصروه على الخروج عن طاعة الأشرف جانبلاط، واتفقا على الغدر بالسلطان جانبلاط واتَّفقا على أن يسيرا معًا إلى مصر لقتال السلطان جانبلاط، فزحفا معًا وأعلنا خلع السلطان جانبلاط وتعيين السلطان طومان باي وتلقُّبه بالعادل, فقُبِضَ على جانبلاط وأُرسل بالحديد إلى سجن الإسكندرية، ثم أُمر بخنقه في سجنه, فقُتِل بعد أن كانت مدة سلطنته ستة أشهر وعدة أيام، ويذكر أن أصل طومان باي من الشراكسة اشتراه الأمير يشبك وأهداه للملك الأشرف قايتباي الذي استخدمه ورقَّاه وأعتقه. عين الملك العادل طومان باي الأمير قوصروه أتابكًا للعسكر، ولم يدم الأمر كثيرًا حتى غدر طومان باي بقوصروه وأمر بقتله هو أيضًا، فنفر الجند منه وبدؤوا بالتآمر عليه."},{"id":3545,"title":"وقوع وباء ومرض عظيم بمدينة زبيد باليمن .","date":["العام الهجري :906","الشهر القمري : رجب","العام الميلادي :1501"],"text":"حصل بمدينة زَبيد مرض عظيم ومات بسببه خلائق لا يُحصَون، وكثر الوباء واستمر الدعاء لذلك في الصلاة والخطب، ودام ذلك إلى شهر ذي القعدة، واشتد في آخر شعبان ورمضان فبلغ الموتى بزَبيد في كل يوم فوق ستين نفسًا، وكان غالبه في النساء والأطفال، وانتقل إلى بوادي زبيد وحيس وموزع وغيرها."},{"id":3546,"title":"مقتل السلطان طومان باي وتسلطن الأشرف قانصوه الغوري .","date":["العام الهجري :906","الشهر القمري : شوال","العام الميلادي :1501"],"text":"هو السلطان العادل طومان باي بعد أن تسلطن العادل طومان باي قام بعزل أنصار الأشرف جانبلاط وولَّى أنصاره هو، وقتل بعض الأمراء وقبض على آخرين وسجنهم، فأثار هذا حفيظة بعض الأمراء عليه، حتى الذين كانوا نصروه بالأمس على جانبلاط، فاتَّفَق الأمراء بقيادة قانصوه الغوري وقاموا بخلعِه فهرب العادل طومان باي، ولكنه قُبِض عليه ثم قُتِلَ بعد أن كانت مدة سلطنته ثلاثة أشهر وعشرة أيام، وكان قانصوه الغوري أولًا قد هاب السلطنة، لكن اتَّفق الأمراء على سلطنته، فبويع بحضور الخليفة المستمسك بالله والقضاة الأربعة، وتلقب بالملك الأشرف قانصوه بن عبد الله الأشرفي الغوري."},{"id":3547,"title":"محاولة البرتغال الاستيلاء على ساحل البريجة  .","date":["العام الهجري :907","العام الميلادي :1501"],"text":"بعث ملك البرتغال منويل من دار ملكه أشبونة قوةً بحرية للاستيلاء على بعض ثغور المغرب، فألجأهم هيجان البحر وموجه إلى ساحل البريجة فيما بين آزمور وتيط، وكانت البريجة بناء متخذًا هنالك للحراسة ونحوها، وكان يسمى برج الشيخ، فنزلت طائفةٌ منهم إلى البر فتطوفوا بالبريجة وما حولها، وأعجبهم المكان فعزموا على المقام به وشرعوا في إدارة السور على قطعة من الأرض، فنذر بهم أهل تلك البلاد من المسلمين وتسابقوا إليهم على الصعب والذَّلول، ففر النصارى إلى البريجة وتحصنوا بها، وأفسد المسلمون كل ما كانوا عملوه في تلك الأيام وأحجروهم بحصنهم، ووضعوا عليهم الرَّصَد إلى أن فتَرَ عزمهم وأيِسوا من نجاح سعيهم، فعاد جُلُّهم أو كلهم إلى أشبونة. وقد خططوا للعودة إلى هذا الموضع لاحقًا."},{"id":3548,"title":"قيام الدولة الصفوية في بلاد فارس .","date":["العام الهجري :907","العام الميلادي :1501"],"text":"قامت الدولة الصفوية الشيعية في تبريز من بلاد فارس بزعامة إسماعيل الأول بن حيدر بن إبراهيم بن جنيد الصفوي، كان جده إبراهيم شيخ الطريقة الصفوية فنُسب إليها، ويذكر أن مؤسس الطريقة أصلًا هو الشيخ صفي الدين إسحاق، وكان حسن الطويل التتاري زعيم القبيل الأبيض جده لأمه, فلما توفي الطويل سنة 883, شاعت الفوضى في بلاد فارس حتى استطاع إسماعيل الصفوي الاستيلاء عليها بعد معركة مشهورة جرت سنة 907, فاستطاع أن يقضي على الدول الصغيرة التي أنشأها تيمورلنك وأحفاده، وبعد هذا بدأ بتأسيس الدولة الصفوية في تبريز التي كانت عاصمة القبيل الأبيض بزعامة آخر ملوكها مراد بن يعقوب بن أوزن حسن الطويل، فجعلها عاصمةً له بعد أن احتَلَّها وضم إيران وأذربيجان والأناضول الشرقية، وجعل المذهب الجعفري مذهبًا للدولة الصفوية وتلقَّب بالشاه، قال قطب الدين الحنفي في الأعلام: \"إنه قتل زيادة على ألف ألف نفس، قال بحيث لا يُعهد في الجاهلية ولا في الإسلام ولا في الأمم السابقة من قبلُ في قتل النفوس ما قتله شاه إسماعيل، وقتل عدة من أعاظم العلماء، بحيث لم يبق من أهل العلم أحد من بلاد العجم، وأحرق جميع كتبهم ومصاحفهم، وكان شديد الرفض بخلاف آبائه، وافتتح ممالك العجم جميعها، وكان يقتل من ظفر به وما نهبه من الأموال قسَّمه بين أصحابه ولا يأخذ منه شيئًا، ومن جملة ما ملك: تبريز وأذربيجان، وبغداد وعراق العجم وعراق العرب، وخراسان، وكاد أن يدعي الربوبية! وكان يسجد له عسكرُه ويأتمرون بأمره\"."},{"id":3549,"title":"فرض إسماعيل الصفوي التشيع على المسلمين السنة في إيران .","date":["العام الهجري :907","العام الميلادي :1501"],"text":"بعد أن أعلن إسماعيل الصفوي قيامَ الدولة الصفويَّة وعاصمتها تبريز، كان أول عملٍ قام به هو إعلانَ أنَّ مذهبَ دولته هو مذهب الإماميَّة الاثني عشرية، وأنه سيعمِّمُه في جميع بلاد إيران، وعندما نُصِحَ أنَّ مذهب أهل إيران هو مذهب الشافعي لم يستجبْ لنصحِهم وهدَّد من لم يستجب لأمره بالتشيعِ، فإنَّ مصيره القتل, فأمر الخطباء في المساجد بسبِّ الخلفاء الراشدين الثلاثة، مع المبالغةِ في تقديسِ الأئمة الاثني عشر, ثم صَكَّ عملة للبلاد كتب عليها: \"لا إله إلا الله، محمد رسول الله، علي ولي الله\"، ثم كتب اسمه, وقد عانى أهلُ السنة في إيران معاناةً هائلة وأُجبروا على اعتناق المذهب الإمامي بعد أن قتَلَ الشاه إسماعيل في بضع سنين زيادةً على ألف ألف نفسٍ بحيث لا يُعهَد في الجاهلية ولا في الإسلام ولا في الأُمم السابقة من قَبلُ في قتل النفوسِ ما قتله شاه إسماعيل! وقتل عِدَّةً من أعاظم العلماء بحيث لم يبقَ من أهل العلم أحدٌ في بلاد العجم، وأحرق جميعَ كتبهم ومصاحفهم، وكان شديد الرفض بخلاف آبائه، ولم يكتفِ الشاه إسماعيل بنشر المذهب الشيعي في إيران، بل حرص على نشره خارج إيران، فوصلت دعوته للتشيع إلى الأقاليم التابعة للدولة العثمانية، فكان من الطبيعي أن يتصدى لتلك الدعوة السلطانُ سليم الأول سلطان الدولة العثمانية السُّنِّية."},{"id":3550,"title":"ترحيل ثلاثمائة ألف مسلم من الأندلس إلى شمال أفريقيا والشام .","date":["العام الهجري :907","العام الميلادي :1501"],"text":"أصدرت الملكة إيزابيلا مرسومًا يقضي بتخيير المسلمين في الأندلس بين أن يتنصَّروا أو يرحلوا عن الأندلس، فرحل ما يقارب الثلاثمائة ألف مسلم من الأندلس من غرناطة إلى المغرب العربي، ومنها انتشروا في أفريقيا وبعضهم إلى الشام، بعد أن أمرت الملكة إيزابيلا بتحويل مساجدهم إلى كنائس."},{"id":3551,"title":"فتنة الجازاني والاعتداء على سكان مكة  .","date":["العام الهجري :908","العام الميلادي :1502"],"text":"قام في ينبع الأمير دراج- جد الأشراف ذوي هجار القاطنين بينبع النخل- بدور نبيل في حفظ مدينة رسول الله صلى الله عليه وسلم من عبث أميرِها حسن بن الزبير الذي تهجم على مخزون الحجرة الشريفة، ودخل المدينة في ربيع الأول سنة 901 وسيطر على الأوضاع بالمدينة، واطمأن الناس بوصوله إليها. إلا أن هذا الأمير دراج توفي سنة 902، وتنازع أبناؤه على إمرة ينبع، فبرز منافس قوي من الأشراف لأبناء دراج على الإمارة فتح بابًا لصراع سياسي وعسكري فترة من الزمن، هو يحيى بن سبع، وبالرغم من توليه الإمارة في جمادى الآخرة سنة 903 إلا أن ذلك لم يصدر من السلطان المملوكي إنما من أمير مكة، فحمل هذا الأمير الينبعي على المماليك، ودخل معهم في صراع مسلح مستعينًا بقبائل ينبع وما جاورها في قطع طريق قوافل أمراء حج المماليك. ودخل في حلبة هذا الصراع سنة 908 أمير مكي خارج على إخوته هو أحمد بن محمد بن بركات المعروف بالجازاني، وعاشت الحجاز فترة من الصراع الحامي حتى هُزِم ابن سبع سنة 912, وتواصلت الصراعات في مكة وما حولها بسبب الجازاني وابن سبع في هذا العام وما بعده، ونالت جُدَّة منها نصيبًا، فما إن يخرج أمير من مكة حتى يهاجم جُدَّة ليسيطر على تجارتها ويجبي مكوسها ويموِّل عسكره ورجاله استمرارًا للصراع المسلح, وقُتل الجازاني سنة 909 في شهر رجب وهو يطوف بالبيت العتيقِ."},{"id":3552,"title":"وقوع حريق عظيم بمدينة عدن باليمن .","date":["العام الهجري :908","الشهر القمري : جمادى الآخرة","العام الميلادي :1502"],"text":"احترق من مدينة عدن جانبٌ عظيم، من نصف الليل إلى قرب الفجر، وتلفت فيه بيوت كثيرة من بيوت التجار، وجانبٌ من السوق الكبير، وجانب من حافة اليهود، وحافة الحبوش بأسرها وأحدقت النار بالمدرسة السفيانية، وتلفت فيها أموال جليلة. ويقال: إنه بلغ عدد البيوت المحترقة تسعمائة بيت, وذهب في هذا الحريق من الأموال والأنفس ما لا يعلمه إلَّا الله تعالى."},{"id":3553,"title":"وفاة العلامة ابن المبرد الحنبلي .","date":["العام الهجري :909","الشهر القمري : محرم","العام الميلادي :1503"],"text":"هو الشيخ الإمام العلامة المحدِّث المسنِد جمال الدين يوسف بن حسن بن أحمد الصالحي المعروف بابن المبرد، ويعرف أيضًا بابن عبد الهادي الدمشقي الصالحي الحنبلي المتقِن المتفنِّن، من فقهاء الحنابلة ومن أهل دمشق، ولد سنة 840 بالصالحية في دمشق، له مشاركة في عدة علوم، وله تصانيف كثيرة نحو الأربعمائة أكثرها بخطه، منها: مغني ذوي الأفهام في فقه الحنابلة, والإغراب في أحكام الكلاب, والجوهر المنضد في طبقات متأخري أصحاب أحمد, والشجرة النبوية في نسب خير البرية صلى الله ‏عليه وسلم, والقواعد الكلية والضوابط الفقهية, وسير الحاث إلى علم الطلاق الثلاث, وغيرها من المصنفات."},{"id":3554,"title":"عقد الدولة العثمانية صلحًا مع بعض الدول الأوربية. .","date":["العام الهجري :909","الشهر القمري : صفر","العام الميلادي :1503"],"text":"عقدت الدولة العثمانية صلحًا مع كلٍّ من المجر، وفرنسا، وإنجلترا، وإسبانيا، والبرتغال، وبولونيا، ونابولي، ورودس، وأوجد هذا الصلح هدوءًا على الجبهة العثمانية الأوربية، استمر 20 عامًا، وقد خاضت خلالها الدولة العثمانية حروبًا ضارية في الشرق الإسلامي."},{"id":3555,"title":"اجتياح الإسبان والبرتغال سواحل المسلمين في شمال أفريقيا والخليج .","date":["العام الهجري :910","العام الميلادي :1504"],"text":"أخذ الإسبان والبرتغال يجتاحون أطراف العالم الإسلامي ويؤسِّسون مراكزَ عسكرية ومخافرَ أمامية في بلاد المغرب شمال إفريقيا والخليج العربي؛ للضغط على سلطنة المماليك سياسيًّا وإرباكها في حماية الثغور وخطوط التجارة التقليدية في البحر المتوسط. فنجحت إسبانيا من جانبها في احتلال ميناء المرسى الكبير في الجزائر سنة 910 (1505م) ثم وهران سنة 913 (1508م) ثم بجاية سنة 1510م. ونجحت البرتغال من جانبها في الاستيلاء على جزيرة سوقطرة سنة 911 (1506م) ثم مضيق هرمز سنة 907 (1509م) والبدء في التخطيط للتسلل إلى موانئ الخليج."},{"id":3556,"title":"هلاك إيزابيلا ملكة قشتالة ودورها في سقوط مملكة غرناطة .","date":["العام الهجري :910","العام الميلادي :1504"],"text":"هي الملكة إيزابيلا بنت خوان الثاني ملكة قشتالة، الكاثوليكية المتعصِّبة، قبلت الزواج بالشاب فرديناند ملك أراغوان الذي كان يصغرُها بسنة، وكان عمرها حين تزوجها تسع عشرة سنة؛ وذلك من أجل اتحاد المملكتين ضد المسلمين وطردهم من الأندلس، وقد اشتهرت في التاريخ بتعاونها مع زوجها فرديناند في القضاء على مملكة غرناطة سنة 897 آخر دولة للمسلمين في الأندلس, حيث تسلَّماها من أبي عبد الله الصغير محمد بن علي آخر حكام بني نصر بن الأحمر، ثم عملا على اضطهاد المسلمين وإجبارهم على ترك دينهم والتنصر، وأسسا محاكم التفتيش لهذا الغرض, كما تم إجلاء مئات الألوف من المسلمين إلى شمال أفريقيا في عهديهما!"},{"id":3557,"title":"اضطهاد الفرنج للمسلمين في الأندلس ومحاولة تنصيرهم .","date":["العام الهجري :910","العام الميلادي :1504"],"text":"لما أُخمدت ثورات المسلمين في الأندلس بالقوة وألغي الإسلام رسميًّا في مملكة غرناطة، تعرض المسلمون لحملة شرسة لتنصيرهم بالقوة, وكان الأندلسيون على صلة وثيقة بإخوانهم في المغرب، الذين كانوا يقفون معهم في محنتهم يحاولون تثبيتهم على دينهم، ومن ذلك فتوى مفتي وهران: أحمد بن بوجمعة المغراوي، وهو أندلسي من بلدة المغرو بمقاطعة قلعة رباح، حيث أرسل لهم فتوى في غرة رجب سنة 910 (18/ 11 / 1504 م) هذا نصها: \" الحمد لله والصلاة والسلام على محمد وآله وصحبه وسلم تسليمًا، إخواننا القابضين على دينهم كالقابض على الجمر، من أجزل الله ثوابَهم فيما لقُوا في ذاته، وصبروا النفوسَ والأولاد في مرضاته، الغرباء القرباء إن شاء الله، من مجاورة نبيه في الفردوس الأعلى من جناته، وارثو سبيل السلف الصالح في تحمل المشاق، وإن بلغت النفوس إلى التراقِ. نسأل الله أن يلطف بنا، وأن يعيننا وإياكم على مراعاة حقه بحسن إيمان وصدق، وأن يجعل لنا ولكم من الأمور فرجًا ومن كل ضيق مخرجًا. بعد السلام عليكم من كتابه إليكم، من عُبيد الله أصغر عبيده، وأحوجِهم إلى عفوه ومزيده، عبيد الله أحمد بن بوجمعة المغراوي ثم الوهراني، كان الله للجميع بلطفه وستره، سائلًا من إخلاصكم وغربتكم حسن الدعاء بحسن الخاتمة والنجاة من أهوال هذه الدار، والحشر مع الذين أنعم الله عليهم من الأبرار، مؤكِّدًا عليكم في ملازمة دين الإسلام، آمرين به من بلغ من أولادكم إن لم تخافوا دخول شرٍّ عليكم من إعلام عدوكم بطويَّتكم. فطوبى للغرباء الذين يَصلحون إذا فسد الناس، وإنَّ ذاكِرَ الله بين الغافلين كالحيِّ بين الموتى. فاعلموا أن الأصنام خشب منجور، وحجر جلمود لا يضر ولا ينفع، وأن المُلكَ مُلك الله، ما اتخذ الله من ولد وما كان معه من إله. فاعبدوه، واصطبروا لعبادته. فالصلاةَ ولو بالإيماء، والزكاةَ ولو كأنها هديةٌ لفقيركم أو رياء؛ لأن الله لا ينظر إلى صوركم ولكن إلى قلوبكم. والغُسلَ من الجنابة ولو عومًا في البحور. وإن مُنِعتم فالصلاةَ قضاءً بالليل لحقِّ النهار، وتسقط في الحُكم طهارةُ الماء، وعليكم بالتيمم ولو مسحًا بالأيدي للحيطانِ، فإن لم يمكن فالمشهورُ سقوط الصلاة وقضاؤها لعدم الماء والصعيد، إلَّا أن يمكنكم الإشارة إليه بالأيدي والوجه إلى تراب طاهر أو حجر أو شجر مما يتيمَّم به، فاقصدوا بالإيماء، نقله ابن ناجي في شرح الرسالة لقوله عليه السلام: \"فآتوا منه ما استطعتم\" وإن أكرهوكم في وقت صلاة إلى السجود للأصنام، أو حضور صلاتهم، فأحرِموا بالنيَّة وانووا صلاتَكم المشروعة، وأشيروا لِما يشيرون إليه من صنمٍ ومقصودكم الله. وإن كان لغير القبلة تسقط في حقِّكم كصلاة الخوف عند الالتحام. وإن أجبروكم على شرب الخمر، فاشربوه لا بنيَّة استعماله. وإن كلَّفوا عليكم خنزيرًا، فكلوه ناكرين إيَّاه بقلوبكم ومعتقدينَ تحريمَه. وكذا إن أكرهوكم على محرَّم. وإن زوَّجوكم بناتِهم فجائز لكونهم أهل الكتاب. وإن أكرهوكم على إنكاحِ بناتكم منهم، فاعتَقِدوا تحريمه لولا الإكراهُ، وأنكم ناكرون لذلك بقلوبكم، ولو وجدتم قوة لغيرتموه. وكذا إن أكرهوكم على رِبًا أو حرام، فافعلوا منكِرينَ بقلوبكم، ثم ليس عليكم إلا رؤوس أموالكم، وتتصدَّقون بالباقي إن تبتم لله تعالى، وإن أكرهوكم على كلمة الكفر، فإن أمكنكم التورية والإلغاز فافعلوا. وإلا فكونوا مطمئني القلوب بالإيمان إن نطقتم بها ناكرين لذلك. وإن قالوا اشتموا محمدًا، فإنهم يقولون له مَمَّد، فاشتموا ممَّدًا، ناوين أنه الشيطان، أو ممَّد اليهود فكثير بهم اسمه. وإن قالوا عيسى ابن الله، فقولوها إن أكرهوكم، وانووا إسقاط مضاف أي عبد الله مريم معبود بحق. وإن قالوا قولوا المسيح ابن الله فقولوها إكراهًا، وانووا بالإضافة للمِلْك، كبَيتِ الله لا يلزم أن يسكُنَه أو يحُلَّ به. فإن قالوا قولوا مريم زوجة له فانووا بالضمير ابن عمها الذي تزوجها في بني إسرائيل ثم فارقها قبل البناء، قاله السهيلي في تفسير المبهم من الرجال في القرآن، أو زوَّجها الله منه بقضائه وقدره. وإن قالوا عيسى توفي بالصلب، فانووا من التوفية والكمال والتشريفِ من هذه، وأمانته وصلبه وإنشاء ذِكرِه، وإظهار الثناء عليه بين الناس، وأنه استوفاه الله برفعه إلى العلو وما يعسر عليكم فابعثوا فيه إلينا نرشدكم إن شاء الله على حسب ما تكتبونَ به. وأنا أسأل الله أن يبدل الكَرَّةَ للإسلام؛ حتى تعبدوا الله ظاهرًا بحولِ الله من غير محنة ولا وَجلةٍ، بل بصدمةِ الترك الكرامِ. ونحن نشهد لكم بين يدي الله أنكم صدقتم الله ورَضِيتم به. ولا بد من جوابكم. والسلام عليكم جميعًا. بتاريخ غرة رجب سنة 910، عرف الله خيره. يصل إلى الغرباء إن شاء الله تعالى\" قال الأستاذ محمد عنان: \"عثرت على هذه الوثيقة خلال بحوثي في مكتبة الفاتيكان الرسولية برومة. وهى تقع ضمن مجموعة خطية من المخطوطات البورجوانية (Borgiani), وقد ورد وصف هذا المخطوط في فهرس مكتبة الفاتيكان (فهرس دللافيدا) بأنه المقدمة القرطبية. وفي صفحة عنوانه بأنه كتاب نزهة المستمعين. وتشغل هذه الوثيقة في المخطوط المشار إليه أربع صفحات (136 - 139) ومن جهة أخرى فقد عثرت بنص هذه الوثيقة مثبتًا في إحدى مخطوطات الألخميادو المحفوظة بمكتبة أكاديمية التاريخ بمدريد (مجموعة سافدرا)\""},{"id":3558,"title":"هزيمة محمد البهال صاحب صعدة على يد السلطان عامر .","date":["العام الهجري :910","العام الميلادي :1504"],"text":"حدثت وقعةٌ مشهورة بين السلطانِ عامر بن عبد الوهاب والأمير محمد بن الحسين البهَّال صاحب صعدة على باب صنعا، وانهزم فيها البهال وعساكره هزيمةً عظيمة ما سُمِع بمثلها قط، وأُسِرَ فيها إمام الزيدية محمد بن علي الوشلي إمام أهل البدعة ورئيسهم، وقُتل منهم جمعٌ لا يحصى، ونهبهم الناسُ، وكانوا يأتون بهم وبخيلِهم واحدًا واثنين وأخذ السلطان عامر مدينة صنعا."},{"id":3559,"title":"وفاة السلطان محمد الشيخ الوطاسي .","date":["العام الهجري :910","العام الميلادي :1504"],"text":"هو السلطان أبو عبد الله محمد الشيخ بن أبي زكريا يحيى بن زيان الوطاسي، المعروف بمحمد الشيخ الوطاسي سلطان المغرب, وبنو وطاس فرقة من بني مرين غير أنهم ليسوا من بني عبد الحق، وكان بنو الوزير من بني وطاس يتطلَّعون إلى الرياسة ويسعَون في الخروج على بني عبد الحق، وقد تكرر ذلك منهم ثم أذعنوا إلى الطاعة، وراضوا أنفسهم على الخدمة فاستعملهم بنو عبد الحق في وجوه الولايات والأعمال واستظهروا بهم على أمور دولتهم فحسن أثرُهم لديها وتعدد الوزراء منهم, فلمَّا ولي والد محمد الشيخ أبي زكريا يحيى بن زيان الوزارة للسلطان عبد الحق، ثم تولى بعده ابنه يحيى فقتله السلطان عبد الحق لما رأى منافسته له في الحكم، فر أخوه أبو عبد الله محمد الشيخ إلى الصحراء وبقي متنقلًا في البلاد. كان أبو عبد الله شجاعًا مِقدامًا, فجمع حوله وهو في الصحراء الأتباع ودخل بهم أصيلا وتمكَّن من حكمها, فلما أحس من نفسه القدرة في الاستيلاء على كرسي فاس جمع جنده وزحف بهم على فاس، فتمكن من دخولها وتنحية الشريف الإدريسي وأخذ البيعة لنفسِه, ثم تفرغ لتدويخ القبائلِ التي بأحواز فاس وغيرها فدخلوا في طاعته واغتبطوا به, وكان له دور عظيم في جهاد الفرنج في المغرب وسواحلها، وبعد وفاة محمد الشيخ تولى بعده ابنه محمد المعروف بالبرتغالي. وهذا السلطان أبو عبد الله محمد الشيخ الوطاسي يختلف عن السلطان أبي عبد الله محمد الشيخ المهدي السعدي المتوفي سنة 964 (1557م) ومؤسس الدولة السعدية بالمغرب، وهو الذي قضى على دولة الوطاسي."},{"id":3560,"title":"استيلاء الإسبان على بجاية .","date":["العام الهجري :910","العام الميلادي :1504"],"text":"لما ظهر جنس الإصبنيول ملوك الجلالقة في طليلطلة في صدر المائة العاشرة بعد ما تم لهم ملك الأندلس وعظمت شوكتهم، طَمِحوا للتغلُّب على ثغور المغربين الأدنى والأوسط فاستولوا على بجاية."},{"id":3561,"title":"استيلاء البرتغال على ثغر آسفي .","date":["العام الهجري :910","العام الميلادي :1504"],"text":"كان البرتغال قد تشوَّفوا للاستيلاء على أَسَفي (بلدة على شاطئ البحر المحيط بأقصى المغرب) وكان أهلها فيهم شجاعة أكثر من غيرهم من أهل الثغور، فزحف إليها البرتغال وجرى بينهم وبين أهلها قتال شديد هلك فيه عدد كبير من البرتغال، وعظُم عليهم أن تمتَنِعَ منهم بلدة صغيرة ليس لها حامية سوى أهلها، ثم طاولوها بالحصار حتى قل القوت عند أهل أسفي وأشرفوا على الهلاك، فحينئذ شارطوا البرتغال وأسلموها إليهم على الأمان فاستولوا عليها وحصنوها غاية التحصين؛ لتوقُّعهم كرَّة المسلمين عليهم، فكان الأمر كذلك، حيث رجعت للمسلمين بعد أربعين سنة!"},{"id":3562,"title":"وفاة الإمام جلال الدين السيوطي .","date":["العام الهجري :911","الشهر القمري : جمادى الأولى","العام الميلادي :1505"],"text":"هو الشيخ الإمام الكبير العلَّامة جلال الدين أبو الفضل عبد الرحمن بن أبي بكر بن محمد السيوطي الخضيري القاهري الشافعي، صاحب التصانيف والمؤلفات الحافلة الجامعة التي تزيد على خمسمائة مصنف، وقد تداولها الناس واشتهرت, وعم النفعُ بها، وُلد في مستهل رجب سنة 849 في مصر بأسيوط وإليها نسبته، وأمُّه أَمَةٌ تركية، وكان أبوه قاضي أسيوط، ثم نشأ في القاهرة يتيمًا بعد وفاة والده، فاشتغل بالعلم فحفظ القرآن والعمدة والمنهاج الفرعي وبعض الأصلي وألفية النحو, ثم رحل إلى كثير من البلاد، فبرع في عدة فنون وشارك في كل العلوم تقريبًا، فله في كل فن مؤلفات مقبولة قد سارت في الأقطار مسير النهار، حتى اعتبر من أكثر العلماء تأليفًا، وأجاز له أكابر علماء عصره مَن سايَرَ وفاق الأقرانَ واشتهر ذكره وبعُد صيتُه, وقد وقع خلاف بينه وبين معاصره الإمام السخاوي رحمهما الله. قال الإمام الشوكاني عن السيوطي: \"لكنه لم يسلَمْ من حاسدٍ لفضله، وجاحد لمناقبِه؛ فإن السخاوي في الضوء اللامع- وهو من أقرانه- ترجم له ترجمة مُظلِمة غالبها ثلبٌ فظيع وسبٌّ شنيع، وانتقاصٌ وغمط لمناقبه تصريحًا وتلويحًا، ولا جرم؛ فذلك دأبه في جميع الفضلاء من أقرانه، وقد تنافس هو وصاحب الترجمة منافسة أوجبت تأليف صاحب الترجمة لرسالة سمَّاها: الكاوي لدماغ السخاوي، فليعرف المطَّلع على ترجمة هذا الفاضل في الضوء اللامع أنها صدرت من خصمٍ له غير مقبول عليه\" والحق أن السيوطي صاحب فنون وإمام في كثير منها، وهو أحفظ للمتون من السخاوي وأبصر باستنباط الأحكام الشرعية، وله الباع الطويل في اللغة العربية والتفسير بالمأثور وجمع المتون، والاطلاع على كثير من المؤلفات التي لم يطلع عليها علماء عصره، وقد وقع في بعض مؤلفاته الحديثية بعض التسامح والتناقض, أما السخاوي فهو في علم الحديث وعلوم الإسناد وما يتعلق بالرجال والعلل والتاريخ إمام لا يشاركه فيها أحد, ويعتبر صاحب فن واحد؛ ولذا يرجَّح قولُه في الحديث وعلومه على السيوطي، ومؤلفاته في ذلك مرجع المحققين، وهو وارث شيخه ابن حجر. ومن تصانيف السيوطي: الجامعين في الحديث، والدر المنثور في التفسير بالمأثور، وحسن المحاضرة في أخبار مصر والقاهرة، وتاريخ الخلفاء، واللآلئ المصنوعة في الأحاديث الموضوعة، والجامع الصغير وزيادته في الحديث، وأسباب النقول، وشرح على مسلم، وعلى الموطأ، وعلى النسائي، وألفية في المصطلح، وفي اللغة ألفية في النحو، والأشباه والنظائر، وفي علوم القرآن أسباب النزول، والإتقان في علوم القرآن، وغيرها كثير يصعب حصره. توفي السيوطي بعد أذان الفجر يوم الجمعة التاسع عشر جمادى الأولى."},{"id":3563,"title":"وفاة الفقيه أبي الحسن علي التجيبي الزقاق .","date":["العام الهجري :912","العام الميلادي :1506"],"text":"هو الإمام العلامة الشيخ الفقيه أبو الحسن علي بن قاسم التجيبي المعروف بالزقاق من كبار فقهاء عصره بالمغرب، تتلمذ على يد أشهر علماء المغرب والأندلس، واستقَرَّ به المقام بفاس، فصار فقيه فاس وخطيبها وقاضيها ومدرسها، وصاحب المنظومة اللامية في علم القضاء وغيرها بعنوان المنهج المنتخب إلى قواعد المذهب، وهي من أنفس ما وُضعت نظمًا في قواعد الفقه المالكي, وقد حَظِيت هذه المنظومة باهتمام المالكية؛ حيث تولى عدد من العلماء شرحها وتكميلها."},{"id":3564,"title":"سقوط ساحل عمان ومسقط وصحار في يد البرتغاليين .","date":["العام الهجري :913","العام الميلادي :1507"],"text":"بعد أن استطاع البرتغاليون إغلاق البحر الأحمر بوجه التجارة العربية أرادوا السيطرة على الخليج العربي، وكان أول همهم جزيرة هرمز لمركزها الهام، فبدأت الحملة على الخليج العربي فهاجموا السفن العربية، فأحرقوا في رأس الحد قوارب الصيد، ثم توجهوا إلى قلهات، ومنها إلى قريات التي أبدت مقاومة بطولية، لكن البرتغاليون قتلوهم دون رحمة، فلم يتركوا طفلًا ولا امرأة ولا رجلًا إلا قتلوه، ثم هاجموا مسقط، ذات الموقع المهم فضربوها بالمدافع وأحرقوا أبنيتها ومساجدها وجميع السفن التي كانت راسية على الميناء، مع ما رافق هذا من قتل وانتهاك للحرمات وأُطلق العِنان للجنود البرتغاليين ليسيحوا في مسقط فسادًا، فلم يتركوا أحدًا إلا قتلوه كعادتهم لا طفلًا ولا امرأة، ثم دمروا المدينة بأكملها وأحرقوها، ثم انطلقوا إلى طول الساحل العماني حتى وصلوا إلى خورفكان التي حصل لها ما حصل لسابقتها، ثم إلى رأس مسندم ثم وصلوا هرمز."},{"id":3565,"title":"احتلال البرتغال للمالديف المسلمة .","date":["العام الهجري :913","العام الميلادي :1507"],"text":"وصل البرتغاليون إلى جزر المالديف في محاولتهم لتطويق العالم الإسلامي، وكانت أولًا قد وصلها التجار المسلمون منذ سنة 85 وبدأ واضحًا فيها الإسلام سنة 545، وقد تمكنت القوات البرتغالية هذا العام من احتلال جزر المالديف وفرض سيطرتها على السكان، وحاولت التأثير عليهم عقَديًّا بتنصيرهم، لكنها كانت تفشل فشلًا ذريعًا مع ارتكابها لأبشع الجرائم لإرهاب السكان، وبقي البرتغاليون فيها قرابة القرن من الزمن حتى مطلع القرن الحادي عشر الهجري، حيث وصل الهولنديون الذين عقدوا معاهدة مع سلطان المالديف وُضِعت بموجِبها تحت حماية الهولنديين، وحاول الهولنديون كإخوانهم البرتغال أن يؤثِّروا على السكان، لكنهم فشلوا مثل سابقيهم، وكانت الجزر آنذاك تُدار من قبل حكومة سيلان الهولندية."},{"id":3566,"title":"سقوط جزيرتي هرمز وقشم في يد البرتغاليين .","date":["العام الهجري :913","العام الميلادي :1507"],"text":"كانت هرمز قد بسطت سيطرتها وسلطانها السياسي على أجزاء كبيرة من الخليج، وكانت ذات مركز تجاري هام؛ لذا قام البرتغاليون بغزوها، وكان ملك هرمز يومها صبيًّا صغيرًا هو سيف الدين ووصيه الشيخ عطار، فوصل البرتغاليون إلى الساحل هذا العام، وبدؤوا بالهجوم المدفعي، فطلب الملك المفاوضات التي كانت رهيبة إلى درجة أن بوكيرك قائد البرتغاليين طعن الشيخ عطار وقتله أثناء تلك المفاوضات، فأسفرت المفاوضات عن صلح بشروط قاسية تُصبِح فيها هرمز تحت السيادة البرتغالية وتدفع أيضًا جزية سنوية ويسمح للبرتغاليين بإقامة منشآت عسكرية ولا يحق للأهالي ممارسة أي نشاط بحري إلا بتصريح من البرتغاليين، وبذلك فرض البرتغاليون سيطرتهم على الخليج العربي."},{"id":3567,"title":"إحراق آلاف الكتب والمخطوطات الإسلامية في غرناطة .","date":["العام الهجري :913","العام الميلادي :1507"],"text":"صدرت بعض المراسيم الإسبانية النصرانية تقضي بتحويل المساجد إلى كنائس، وبإحراق جميع الكتب الإسلامية بغرناطة، ثم عُمم على بقية المناطق، وبمنع استعمال اللغة العربية، ومصادرة الأسلحة من المسلمين. وكان في سنة 908 (1502م) صدر مرسوم ملكي يقضي بأن يُمنح المسلمون شهرين فقط لا غير لاعتناق النصرانية أو الطرد النهائي، فشهدت ساحات غرناطة في حينها إحراق آلاف الكتب العربية والتنصير الإجباري للمسلمين من نزلاء حي البيازين المقابل لقصر الحمراء."},{"id":3568,"title":"تنازل الخليفة العباسي المستمسك يعقوب عن الخلافة لابنه .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"بعد أن شعر الخليفة العباسي المستمسك بالله يعقوب بن المتوكل عبد العزيز بالتعب في هذا العام تنازل بالخلافةِ لابنه محمد الذي أصبح هو الخليفةَ بتنازل أبيه، وتلقب بالمتوكل على الله محمد بن يعقوب، وقد بقيَ والده المستمسك إلى أن دخل العثمانيون مصر فنُقِلَ ابنه الخليفةُ المتوكل إلى القسطنطينية، وأما المستمسك فلم يُنقَل لكبر سنه، وبقي بمصر حتى توفي في سنة 927."},{"id":3569,"title":"محاولة البرتغال الاستيلاء على ثغر آزمور .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"بعث طاغية البرتغال إلى ثغر آزمور شكوادره ألفين من العسكر وأربعمائة خيالة، فدافعهم زيار الوطاسي ابن عم السلطان محمد البرتغالي، ونشبت مراكب البرتغال في الساحل وتكسر جلُّها وعاث فيها المسلمون ورجع الباقي مفلولًا."},{"id":3570,"title":"حصار السلطان أبي عبد الله البرتغالي لآصيلا. .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"لما أفضى الأمر إلى السلطان محمد بن محمد الشيخ الوطاسي المعروف بالبرتغالي أراد أن يأخذ بثأره من البرتغال الذين أسروه لسبع سنين فزحف إلى آصيلا وحاصرها وطال قتاله عليها ثم اقتحمها المسلمون عليهم اقتحامًا واقتتلوا في وسط الأزقة والأسواق يومين، ثم جاء المدد إلى البرتغال من طنجة وجبل طارق فقَوِيت نفوسهم وخرج المسلمون عنهم، لكن ما خرجوا حتى هدموها وأحرقوها ولم يتركوا لهم بها إلا الخربات، ثم جدَّ البرتغال في إصلاحها وأقاموا بها برهة من الدهر إلى أن رجعت للمسلمين."},{"id":3571,"title":"إسبانيا تحتل مدينة وهران بالجزائر شمال أفريقيا وتذبح أهلها .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"كانت إسبانيا بقيادة الكاردينال شيسيروس بدأت بمحاولة احتلت مدينة وهران المرسى الكبير من سنة 910 (1504م) حيث شنَّت عدة هجمات على المدينة انتهت بسقوطها هذا العام, فأعمل الإسبان السيف في سكان المدينة، كما قاموا بتحويل جوامعها إلى كنائس. كانت مدينة وهران تمثِّل بالنسبة للإسبان نقطة ارتكاز للاستيلاء على باقي البلاد. إلا أن النتائج جاءت مخيِّبة. ولم يأت احتلال المدينة الذي دام طويلًا بأي نتائج للإسبان. فقد كانت مقاطعة أهل البلاد لهم وقطع الموارد عنهم أجبرتهم على طلب المؤونة من إسبانيا، وكان الإسبان يتوقعون سهولة الحصول عليها بعد نهب المناطق المجاورة, وعلى الرغم من استمرار سياسة الإسبان في اضطهاد أهل وهران؛ فما منهم إلا أسير أو قتيل، إلا أن الله أعادها للإسلام على يد الأتراك في حدود سنة 1120"},{"id":3572,"title":"إنشاء البرتغال مدينة الجديدة بساحل البريجة .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"على الرغم من فشل محاولات البرتغال من بناء مدينة لهم في ثغور المغرب على ساحل البريجة سنة 907 بسبب مقاومة المسلمين لهم, إلا أنهم خططوا للعودة إلى هذا الموضع فانتهوا إليه هذا العام وتحيَّنوا غفلة أهل البلاد وشرعوا في بناء حصن مربع على كل ربعٍ منه برج وثيق، ودأبوا في العمل ليلًا ونهارًا، فلم تمض مدة يسيرة حتى فرغوا منه وامتنعوا على المسلمين به، ثم شرع البرتغال بعد الفراغ من هذا الحصن في إدارة سور المدينة على أوثق وجه وأحكمِه, ثم أداروا خارج السور خندقًا فسيحًا وجعلوا عمقَه أربعة عشر شبرًا بحيث بلغوا به الماء، وإذا فاض البحر ملأ ما بين جوانبه واتخذوا للمدينة ثلاثة أبواب أحدها للبحر، واثنان للبر، وجعلوا أمامهما قنطرتين بالعمل الهندسي بحيث تُرفعان وتُوضعان وقت الحاجة إلى ذلك, فصارت المدينة بهذا كلِّه في غاية المناعة، وجعلوا داخل المدينة خمس حارات وسمَّوا كل حارة باسم كبير من قدمائهم على عادتهم في ذلك. واتخذوا بها أربع كنائس واتخذوا المخازن والأهراء للاختزان وسائر المرافق, وأوطنوها بأهلِهم وعيالهم، وكان فيها جماعة من أشرافهم وذوي بيوتاتهم من أهل أشبونه وغيرها، وكانوا يعدون فيها أربعة آلاف نفس ما بين المقاتِلة والعيال والذرية، وكانوا يأملون الاستيلاءَ منها على مراكش."},{"id":3573,"title":"محاولة استعادة المسلمين مدينة أسفي من نصارى البرتغال .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"بعد أن فشلت محاولة المسلمين منع سقوط أسفي بيد البرتغاليين خرجوا منها سنة 910 بشرط الأمان ثم زحفوا إليها بعد ثلاث سنين من أخذها ووقع بينهم وبين البرتغال حرب شديدة كانت صفوف المسلمين تترادف فيها كأمواج البحر، وقتل قواد عسكر البرتغال وكبارهم ثم قَدِمت عليهم شكوادره من مادرة بالعسكر والزاد، فقويت نفوس البرتغال، وارتحل المسلمون عنها بعد أن أشرفوا على الفتح، وتبعهم البرتغال لينتهزوا فيهم الفرصة، فكرَّ المسلمون عليهم واستَلَبوهم، وهذا أول حصار كان على أسفي, ثم بعد سنين قلائل زحف المسلمون إليها أيضًا ومعهم عدد من المدافع وقاتلوا قتالًا صعبًا وزحفوا إلى السور فهدموا منه ثلمة كبيرة، واشتدَّ القتال عليها بما خرج عن العادة، ثم رحل المسلمون من غير فتح وأعرضوا عنها مدة لم يحدِّثوا أنفسهم بالقتال، وعمرت أسفي بالنصارى وانتقل إليها التجار وبنوا بها الدور وكانوا يسقون منها الحب ويحملونه في السفن إلى بلادهم، ولعل ذلك لهدنة كانت لهم مع المسلمين"},{"id":3574,"title":"وقعة غوا بين المماليك وبين البرتغاليين .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"قام البرتغال بعدة حملات بحرية كان منها التي توجهت إلى جزيرة سقطرى على مدخل البحر الأحمر، وأنشؤوا فيها قلعة وفرضوا الحصار على البحر الأحمر, ومنها السفن الهندية التجارية التي يريدوا أن يصلوا بها إلى عدن ثم جدة ومنها إلى مكة والمدينة؛ بهدف تدميرها واعتراض السفن التجارية العربية، فما كان من الملك عامر الثاني ملك اليمن وكذلك الملك خليل مظفر شاه إلا الاستنجدا بالسلطان المملوكي قانصوه الغوري، وطلبا منه العون ضد البرتغاليين، فجهز السلطان أسطولًا استعان في إنشائه بالعثمانيين وبدولة البنادقة بحكم المصالح المشتركة، وتولى قيادة هذا الأسطول حسين الكردي، فتوجه إلى ملبار بساحل الهند وأرسى سفنه في مرفأ ديو، ثم قام حسين الكردي بالبحث عن السفن البرتغالية فالتقى بها على مدينة غوا على ساحل الملبار، وكان قائدهم فرانسيسكو، وهو ابن حاكم الهند البرتغالي لوانزو دالميدا، فانقض عليه الأمير حسن الكردي وجرت بينهما معركة هائلة عرفت بوقعة غوا انتصر فيها الأسطول الإسلامي بقيادة حسين الكردي انتصارًا كبيرًا, وقُتل فيها قائد البرتغال فرانسيسكو، ثم عاد الأمير حسين إلى مرفأ ديو الذي جعله ملك الهند خليل تحت تصرفه، وأقام فيه يريد أن ينتهي موسم الأمطار ليعود إلى مصر."},{"id":3575,"title":"وفاة الونشريسي .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"هو أبو العباس أحمد بن يحيى بن محمد الونشريسي، ولد بمدينة ونشريس التي تقع بناحية بجاية بين باجة وقسنطينة وإليها نُسب، ونشأ وتفقه بتلمسان على كبار فقهائها، ثم هرب إلى فاس بعد فتنة جرت له مع أمير تلمسان، برع في الفقه المالكي، وله كتب منها المعيار المعرب والجامع المغرب عن فتاوي علماء أفريقية والأندلس والمغرب، وهو أشهرها، وله المنهج الفائق والمنهل الرائق والمعنى اللائق بآداب الموثق وأحكام الوثائق، وله كتب الفروق في المذهب المالكي، وغيرها من المصنفات، توفي بتلمسان عن عمر يناهز الثمانين."},{"id":3576,"title":"جهاد قادة الدولة العثمانية لطرد الإسبان من مدينة ثغر الجزائر  .","date":["العام الهجري :914","العام الميلادي :1508"],"text":"استولى الملك الأذفونش ملك الجلالقة بطليطلة على وهران، وفعل بأهلها الأفاعيل، ثم سما لتملُّك الجزائر وشَرِه لالتهامها وضايَقَ المسلمين في ثغورهم، وضعف بنو زيان عن مقاومته, فما كان من الشيخ الفقيه الصالح أبي العباس أحمد ابن القاضي الزواوي ممن له الشهرة والوجاهة الكبيرة في بسائط المغرب الأوسط وجباله إلا السعي للاستنجاد بالدولة العثمانية التي قد زخر عبابُهم وملكت أكثَرَ المسكونة خلال هذه الفترة، وظهر من قوَّاد عساكرهم البحرية قائدان عظيمان وهما خير الدين بربروسا وأخوه عروج باشا، وكانا قد تابعا الغزو على بلاد الكفر برًّا وبحرًا وأوقعا بأهل دول أوربا وقائع شهيرة، وصار لهم ذكر في أقطار البلاد، وتمكن ناموسهم من قلوب العباد، فكاتبهما الفقيه أبو العباس وعرَّفهما بما المسلمون فيه من مضايقة العدو الكافر، وقال: إن بلادنا بقيت لك أو لأخيك أو للذئب؛ فأقبَلَا نحوه مسرعَينِ حتى تمكن عروج من تحرير مدينة ثغر الجزائر سنة 922 (1516م) بعد ما كاد العدو يملكه فخلَّصه منهم."},{"id":3577,"title":"صراع العثمانيين مع الصفويين وسقوط بغداد بأيدي الصفويين  .","date":["العام الهجري :914","الشهر القمري : جمادى الآخرة","العام الميلادي :1508"],"text":"بقيت العلاقة بين الدولتين العثمانية والصفوية متوترةً وغير صافية، بل بقيت بينهم الحروب والمناوشات والتحرُّشات، وكلٌّ يريد بسط سيطرته على ما يستطيعُ من المناطق وخاصةً أن الصفويين يريدون بسط النفوذ الشيعي على العراق وآسيا الصغرى، وهذا لم يرُقْ للدولة العثمانية التي كانت تمثِّلُ الدولة الحامية للسنة، ثم لَمَّا تمكن الشاه إسماعيل الصفوي من توحيد بلاد إيران قام بمهاجمة العراق, بدعوى أنَّ مقابر أئمة الشيعة موجودة فيه، والمقامات والمزارات المعروفة لديهم، فاستطاع أن يسيطرَ على العراق بجيشِه وتصبح تحت النفوذ الصفوي، ولم يكتف الشاه إسماعيل بذلك بل أضاف إلى ذلك أن أثار الفتن عن طريق أتباعه ومواليه في الدولة العثمانية على الدولة فثار الشيعة في آخر خلافة بايزيد الثاني إلا أن السلطان سليم الأول استطاع أن يخمدها، وتطورت الأمور إلى أن حدثت معركة جالديران921."},{"id":3578,"title":"ظهور الدولة السعدية .","date":["العام الهجري :915","العام الميلادي :1509"],"text":"كان سبب ظهور الدولة السعدية أن السلطان محمد البرتغالي بن محمد الشيخ الوطاسي قد انشغل بجهاد النصارى المعتدين وترديد الغزوِ إليهم والإجلاب عليهم، حتى شُغِل بذلك عن البلاد المراكشية وسواحلها؛ مما أدى إلى ظهور دولة السعديين عندما قام أبو عبد الله محمد الشيخ السعدي المعروف بالمهدي ببلاد السوس؛ حيث أقبل عليه الخلط وأظهروا الخدمة والنصيحة، وغلب محمد الشيخ المهدي هذا على فاس، وأخرج أبا حسون الوطاسي آخر حكام دولة الوطاسيين."},{"id":3579,"title":"موقعة ديو البحرية بين المماليك والبرتغاليين .","date":["العام الهجري :915","العام الميلادي :1509"],"text":"بعد أن تمكن أسطول المماليك من هزيمة البرتغاليين في وقعة غوا سنة 914 كان الأمير حسين الكردي قائد المماليك قد عاد إلى ديو منتظرًا موسم الأمطار حتى ينتهي ويعود إلى بلاده، ولكن البرتغال في هذه السنة قاموا بقيادة الحاكم البرتغالي لورانزو دالميدا حاكم الهند والذي قتل ابنه في وقعة غوا العام الماضي، فاجأ الأسطول المملوكي الراسي في ديو جنوب بومباي فجرت معركة انهزم فيها الأسطول المملوكي بعد أن تكبد الكثير من الخسائر، فاضطرَّ الأمير حسن الكردي إلى العودة إلى جدة بمن بقي معه، وكان هذا الانتصار البرتغالي له أكبر الأثر في رسوِ قدَمِهم على سواحل الهند واستيلائهم على مدينة ظفار، علمًا أن الأسطول البرتغالي بقي يلاحق الأسطول المملوكي إلى جدة."},{"id":3580,"title":"استنجاد المماليك بالعثمانيين ضد البرتغاليين .","date":["العام الهجري :915","العام الميلادي :1509"],"text":"لما تمكن البرتغاليون من طرد المماليك من مرفأ ديو الهندي وانسحبوا إلى جُدة، تبعهم البرتغاليون, فقام السلطان المملوكي قانصوه الغوري بالاستنجاد بالعثمانيين ضد البرتغاليين الذين قاموا بمحاصرة الأسطول المملوكي في جُدة، فقام العثمانيون بتزويد المماليك بسفن حربية مزودة بمدافع البارود بقيادة سليمان الريس، واستطاع هذا الأسطول العثماني أن يطرد الأسطول البرتغالي المحاصر للأسطول المملوكي بجدة، واستولى على بعض سفن البرتغال وأسَرَ بحَّارتَها."},{"id":3581,"title":"البرتغاليون يسيطرون على الخليج العربي .","date":["العام الهجري :915","العام الميلادي :1509"],"text":"لما تمكَّن البرتغاليون من إغلاق البحر الأحمر في وجه السفن التجارية العربية زحفوا على الساحل إلى الخليج العربي ودمَّروا مسقط وغيرها من الموانئ الهامة، حتى وصلوا إلى هرمز وبسطوا سيطرتهم عليها، وأقاموا الثكنات العسكرية، وفرضوا سيادتهم على الخليج العربي كاملًا حتى إن أي سفينة لا تستطيع الإبحار إلا بتصريح منهم، وبذلك استطاعوا حصر النشاط التجاري في الخليج العربي وقَبْلَه في الساحل الهندي، فأصبحت تجارة العالم كله بأيديهم."},{"id":3582,"title":"غارة فرسان جزيرة رودوس البرتغاليين على السفن المملوكية .","date":["العام الهجري :916","العام الميلادي :1510"],"text":"قام فرسان جزيرة رودوس بقيادة أمير البحر البرتغالي بالاستيلاء على ثماني عشرة سفينة من سفن المماليك، كانت تحمِلُ الأخشاب التي تنقلُها لبناء أسطول ثان كان يعتزم السلطان الغوري بناءه بعد أن فقد الأسطول الأول في معركة ديو، وقد سحبت إلى جزيرة رودوس بعد إحراق بعضها."},{"id":3583,"title":"بدء هجمات البرتغال على موزمبيق والصومال ومدغشقر .","date":["العام الهجري :916","العام الميلادي :1510"],"text":"في نهاية القرن التاسع الهجري اكتُشف طريق رأس الرجاء الصالح، وتابع البحَّار فاسكو دي جاما الرحلات البرتغالية عبر المحيط الهندي، وشهد شرقي أفريقيا صراعًا دمويًّا شنَّه البرتغاليون ضِدَّ الإمارات والمدن الإسلامية على طول سواحل شرقي أفريقيا، ودمَّروا مدينة كلوة ومساجدها الثلاثمائة، ودمَّروا مدن لامو وباتي. واستمَرَّ الصراع بين المسلمين والبرتغاليين قرابة قرنين تدور رحاه في سواحل شرقي أفريقيا, واستطاع العمانيون وقف التقدُّم البرتغالي، بل أنهوا نفوذ البرتغال في معظم سواحل شرقي أفريقيا، وأسس أحمد بن سعيد سلطنة عمانية ضَمَّت معظم شرقي أفريقيا إلا أن البرتغاليين تمسَّكوا بموزمبيق ودام احتلالهم من القرن العاشر الهجري حتى الاستقلال في سنة 1395 (1973م)، ونشطت البعثات التنصيرية في ظل الاحتلال البرتغالي، وقاوم المسلمون نشاطَ هذه البعثات، وكان همُّ البرتغاليين منصَرِفًا إلى الحصول على ذهب موزمبيق مقابل الأقمشة والخرز، والرقيق مقابل الأسلحة الحديثة. ورغم تحدي البرتغاليين إلا أن الإسلام وصل إلى نياسالاند (ملاوي) وبحيرة تنجانقا في داخل أفريقيا، غير أن الدعوة الإسلامية اصطدمت بعقبات كثيرة."},{"id":3584,"title":"احتلال الإسبان طرابلس الغرب وحكم فرسان القديس يوحنا .","date":["العام الهجري :916","الشهر القمري : جمادى الأولى","العام الميلادي :1510"],"text":"من أقوى الأسباب التي هيأت للإسبان احتلال طرابلس الغرب ضعفُ الحامية فيها، وانصراف الناس إلى تنمية المال، وإلى مُتَع الحياة عن الاهتمام بتقوية الجيش وتحصين القلاع، ومن المناسبات التي انتهزها الإسبان للتعجيل باحتلال طرابلس، أنه في هذه سنة وقع خلاف بين أحمد الحفصي وبين والده الناصر، فذهب إلى الإسبان يستنجد بهم على أبيه، فاستعد الإسبان لغزو طرابلس، فجهزوا 120 قطعة بحرية، وانضم إليها سفن أخرى من مالطة، وشُحنت بخمسة عشر ألف جندي من الإسبان، وثلاثة آلاف من الإيطاليين والمالطيين. وفي 8 من ربيع الآخر أقلع الأسطول من فافينيانا، ومرَّ بجزيرة قوزو بمالطة فتزود منها بالماء، وانضمَّ إلى الجيش خبير مالطي اسمه جوليانو بيلا، له معرفة بطرابلس. وقد أعدت هذه الحملة بإشراف نائب ملك صقلية، وبإعانة الجيوش الصقلية والإيطالية. وقد تسربت أخبار هذه الحملة إلى طرابلس قبل تحركها بنحو شهر، فأخذ الناس في الهجرة منها إلى غريان، وتاجورة، ومسلاتة، وأخذوا معهم كل ما كان مهمًّا من أموالهم، وما أمكنهم من أثقال متاعهم، ولم يبقَ بالمدينة إلا المحاربون، وبعض السكان الذين لم يقدروا على الفرار، وانحازوا إلى قصر الحكومة والجامع الكبير، وصعد المحاربون فوق الأسوار وعلى القلاع.  نزلت جيوش الإسبان في القوارب وكانت بقيادة بييترو نافارو، وفي الصباح، بدأ الهجوم وأطلقت السفن مدافعها على الأسوار وقصر الحكومة. ونزل الجيش المكلف بمنع المسلمين من الاتصال بالمدينة إلى البر بجهة سيدي الشعاب لمنع الاتصال بالمدينة. واندفع الجيش الإسباني نحو المدينة تحميه مدافع الأسطول، فاحتل البرج القائم على باب العرب وبعض الأسوار، وتمكن الإسبان من فتح باب النسور، واتصل الجيش الخارجي بالجيش الداخلي واستبسل الطرابلسيون في الدفاع، وجاء في رسالة القائد نافارو أنه لم يخلُ موضِعُ قَدَمٍ في المدينة من قتيلٍ، ويقَدَّر عدد القتلى بخمسة آلاف، والأسرى بأكثر من ستة آلاف، وتغلَّب الإسبان على مقاومة المسلمين العنيفة، واحتُلَّ قصر الحكومة عَنوةً، وقد حَمِيَ وطيس المعركة حينما تمكَّن حامل العلم الإسباني من نصبِه على برج القصر. وأبدى من التجؤوا إلى الجامع الكبير مقاومة شديدة، فقُتِل منهم نحو ألفي طرابلسي بين رجال ونساء وأطفال. وقتل من الإسبان ثلاثمائة رجل، وكان من بين الموتى كولونيل كبير في الجيش، وأميرال الأسطول، وقبل أن تغرب شمس يوم 18 من ربيع الآخر من هذه السنة، سقطت مدينة طرابلس في يد الإسبان، بعد أن أريقت دماء الطرابلسيين في كل بقعةٍ منها، ولكثرة القتلى فقد أُلقيت جثثُهم في صهاريج الجوامع وفي البحر، وأُحرق بعضها بالنار. وأقام نائب البابا احتفالات الفرح بسقوط هذه المدينة العربية الإسلامية في أيدي النصارى. وأرسل القسيس أمريكو دامبواس رئيس منظمة فرسان القديس يوحنا إلى فرديناند ملك إسبانيا تهنئة، ويرجوه أن يتابع فتوحاته في إفريقية. وعلى الجانب الآخر فقد استاء المسلمون لهذا الاحتلال، وقابله الطرابلسيون المقيمون في الإسكندرية إذ ذاك بإحراق فندق للإسبان في المدينة. انتهز الطرابلسيون المعسكِرون خارج السور غياب القائد الإسباني نافارو وأسطوله، وانقضُّوا على المدينة وتسلَّقوا سورها، ولكنهم لم يوفَّقوا فرجعوا أدراجَهم, وهو ما دفع محمد بن حسن الحفصي إلى إعانة طرابلس، فجمع جيشًا كبيرًا بقيادة محمد أبي الحداد قائد توزر، وكان من أكبر قواده، ووصل طرابلس ونزل خارج السور، وانضم إلى هذا الجيش المحاربون الطرابلسيون، وهاجموا المدينة في ذي الحجة من هذه السنة, ولكنهم لم يظفروا منها بطائل. وظل يحكم طرابلس فرسان القديس يوحنا حتى سنة 936 (1530م) عندما منحها شارل الخامس إمبراطور الإمبراطورية الرومانية لهم، الذين صاروا يعرفون في ذلك الوقت بفرسان مالطا."},{"id":3585,"title":"مقتل السلطان محمود شاه الأبادي صاحب كجرات .","date":["العام الهجري :916","الشهر القمري : رمضان","العام الميلادي :1511"],"text":"هو السلطان العادل المجاهد أبو الفتح محمود شاه بن محمد أحمد بن محمد بن مظفر ناصر الدين أبو الفتح بن غياث الدين الدلي الأصل، الأحمد أبادي. كان مولده سنة 848 بآباد. أسلم جَدُّ جَدِّه مظفر على يد محمد شاه صاحب دلي، وكان عاملًا له على فتن من كجرات- وفتن: بلدة من بلاد كجرات- من بلاد الهند، فلما وقعت الفتن في مملكة دلي وتقسمت البلاد، فكان الذي خصَّ مظفر حكمه كجرات، ثم وثب عليه ابنه محمد، ولكن لم يلبث أن استفحل أمر الأب مظفر، بحيث قَتَل ولده محمدًا، ثم بعد سنين انتصر أحمدُ لأبيه وقتَل جدَّه مظفرًا واستقر في كجرات، وخَلَّفه غياث الدين بن محمد، ثم قطب الدين، ثم أخوه داود، فلم يلبث سوى أيام وخُلِعَ واستقر أخوهم محمود شاه وذلك في سنة ثلاث وستين، حين كان ابن خمس عشرة سنة واستقر حكمُه وأخذ من الكفار قلعة الشابانير فابتناها مدينة وسمَّاها أحمد آباد، ومن جملة ممالكه كناية, وعَمَر بمكة رباطًا مجاورَ باب الدربية، عرف بالكنباتية، وقرَّر به جماعة ودروسًا وغير ذلك، وكان يرسِلُ لهم مع أهل الحرمين عِدَّة صدقات، ثم قطعها لَمَّا بلغه استيلاء النظَّار عليها، واستمر على ولايته إلى أن توفِّي يوم الأحد ثاني رمضان بأحمد أباد, ودفن بها."},{"id":3586,"title":"وقعة غوا الثانية بين المماليك والبرتغاليين .","date":["العام الهجري :917","العام الميلادي :1511"],"text":"استنجد سلطان كجرات بالسلطان المملوكي قانصوه الغوري لطرد البرتغاليين الذين كثروا في بحر الهند، وأخذوا يصطادون السفن ويعتدون على المسافرين، ويقطعون الطريق عليهم وينهبون ويقتلون، فجهَّز السلطان الغوري أسطولًا وولى عليه الأمير حسين الكردي ومعه الأمير سليمان الريس العثماني، ثم التقى الأسطولان العثماني والمصري مع الأسطول البرتغالي بقيادة البوكيرك في معركة بحرية جرت أمام غوا على ساحل الملبار، ولم يحقق الأسطولان أي نصر بل اضطرَّا للانسحاب والعودة إلى جُدة مع ما بقي معهم من السفن، فاحتل البوكيرك غوا وجعلها عاصمةً له وقاعدة لأسطوله ومركزًا لتجارة البرتغال."},{"id":3587,"title":"وفاة الأمير أبي الحسن بن راشد .","date":["العام الهجري :917","العام الميلادي :1511"],"text":"هو الأمير أبو الحسن علي بن موسى بن راشد بن علي بن سعيد بن عبد الوهاب مختطُّ مدينة شفشاون في العدوة الأخرى؛ حيث بنى قصبتها وشيَّدها وأوطنها بأهله وعشيرته، ونزل الناس بها فبَنَوا وصارت في عداد المدن، وكان من أهل الجهاد والمرابَطة خاصة على العدو ببلاد غمارة والهبط."},{"id":3588,"title":"الاستعمار البرتغالي للملايو .","date":["العام الهجري :917","العام الميلادي :1511"],"text":"انطلق المستعمِرون الصليبيون البرتغاليون من قاعدتهم غوا على سواحل الهند الغربية، ووصلوا مالاقا في الملايو سنة 915 فقاموا بهجوم عليها، ولكنهم فشلوا ثم بعد عامين أعادوا الكَرَّة فسقطت ملاقا- الميناء التجاري الهام للمسلمين- بيد الاستعمار البرتغالي، وكان فرحًا كبيرًا للنصارى حتى أقاموا في روما قُدَّاس شكر حتى عدُّوا هذا النصر طريقًا لاحتلال القدس، وكان أول ما قاموا به بعد أن سقطت ملاقا بيدهم أن بنَوا حصنًا حجريًّا من أحجار مقابر المسلمين، ثم بدؤوا بإعدام الأهالي على دفعات متتالية، غير أعمال القرصنة."},{"id":3589,"title":"نزاع أبناء السلطان العثماني بايزيد الثاني مع أبيهم .","date":["العام الهجري :917","العام الميلادي :1511"],"text":"كان السلطان بايزيد الثاني قد عين أولاده الثلاثة الذين بقُوا على قيد الحياة على الولايات، فكان كركود واليًا على شرقي الأناضول، وأحمد على أماسيا، وسليم على طرابزون، كما عيَّن حفيده سليمان بن سليم على مدينة كافا في شبه جزيرة القرم، وكان سليم محاربًا طموحًا فاراد أن يكون واليًا على بعض المقاطعات في أوربا ليمارس الجهادَ، ويؤيِّدُه في ذلك الانكشارية والعسكريون عامة، ولكن السلطان رفض من ابنه ذلك، كما رفض الولد ولاية طرابزون وانتقل إلى ابنه في كافا، ثم جمع جيشًا وسار إلى أوربا وحاول السلطان تهديدَ ولده الذي أصرَّ على القتال ونتيجة حبه للسِّلم تراجع عن قرارِه وعَيَّنه على بعض المقاطعات الأوربية، فطَمِعَ سليم وسار إلى أدرنة وأعلن نفسه سلطانًا عليها فحاربه أبوه وهزمه وفَرَّ إلى القرم، ثم تدخلت الانكشارية فعفا عنه السلطان، وأعاده إلى أوربا، أما كركود وهو الكبير فقد رأى أخاه سليم يفرض رأيه؛ لذا اتجه إلى مقاطعة صاروخان واستلمها دون أمر أبيه فحاربه أبوه وهزمه أيضًا قبيل وفاته بقليل."},{"id":3590,"title":"دخول الإفرنج عدن .","date":["العام الهجري :917","الشهر القمري : ذي الحجة","العام الميلادي :1512"],"text":"دخل الإفرنج عدن وقُتِلَ كبيرهم المسمى عين البقر على يد الأمير مرجان بن عبد الله الظَّافري, ومرجان هذا هو الذي عمر قبة العيدروس بعدن ودفن معه فيها."},{"id":3591,"title":"تحرير مدينة بجاية من يد الإسبان .","date":["العام الهجري :918","العام الميلادي :1512"],"text":"اهتمت الدولة العثمانية بشمال أفريقيا خاصة بعد دخول الجزائر تحت نفوذها في عهد السلطان سليم الأول، وظهر في ساحة الجهاد في شمال أفريقيا قائدان تركيان عظيمان هما الأخوان عروج باشا، وخير الدين بربروسا باشا, ويظهر دور الأخوين المجاهدين بمحاولة تحرير بجاية من الحكم الإسباني سنة 918 (1512م)، وقد نَقلا لهذا الغرض قاعدة عملياتها ضد القوات الإسبانية في ميناء جيجل شرقي الجزائر بعد أن تمكَّنا من دخولها وقتل حماتها الجنوبيين سنة (1514م) لكي تكون محطة تقوية لتحرير بجاية من جهة، ولمحاولة مساعدة مسلمي الأندلس من جهة أخرى، ويبدو أن الأخوين قد واجها تحالفًا قويًّا نتج عنه العديد من المعارك النظامية، وهو أمر لم يتعاداه لكن أُجبرا عليه بفعل الاستقرار في حكم الجزائر، وزاد من حرج الموقف قتلُ عروج في إحدى المعارك سنة 924 (1518م) مما اضطر خير الدين للبحث عن تحالف يعينه على الاستقرار والمقاومة سواء لدورها البارز في ساحة البحر المتوسط، أو لأن القوى المحلية في الشمال الأفريقي كانت متعاطفة معها."},{"id":3592,"title":"وفاة السّلطان بايزيد الثاني  .","date":["العام الهجري :918","العام الميلادي :1512"],"text":"هو السلطان بايزيد الثاني بن محمد الفاتح بن مراد الثاني, وهو ثامن سلاطين بني عثمان، ولد سنة 856 وهو أكبر أولاد أبيه، تولى السلطنة بعد أبيه محمد الفاتح في الثامن عشر ربيع الأول سنة 886 وعمره إذ ذاك ثلاثون سنة، بعد أن نازعه أخوه جم على السلطنة فانتصر عليه, ويعتبر بايزيد الثاني من عظماء السَّلاطين، افتتح الفتوحات، كقلعة ملوان، وقلعة كوكلك، وقلعة آق كرمان سنة 888 وقلعة متون، وغير ذلك من القلاع والحصون, وفي أيامه ابتدأ أمر شاه إسماعيل الصفوي في بلاد العجم سنة 895. وقع في عهده حروب بين دولته والمماليك وتم إبرام صلح بعدها، وصلت الفتوحات في عهده إلى البندقية التي انتصر عليها، فاستنجدت بملك فرنسا والبابا، فقامت حروب صليبية بين الطرفين. كما ظهرت في عهده دولة روسيا سنة 886. أُجبِرَ بايزيد من قبل الانكشارية في آخر حياته على التنازل عن الحكم لابنه سليم الأول سنة 918 وهي نفس السنة التي توفِّيَ فيها. توفي بايزيد الثاني وهو ذاهِبٌ إلى ديمتوقة فنُقِلَ نعشُه إلى إسلامبول؛ حيث دفن بجوار جامعه الشريف، بعد أن دامت سلطنته إحدى وثلاثين سنة إلا أيامًا. وعمره اثنتان وستون سنة."},{"id":3593,"title":"استيلاء إسماعيل شاه الصفوي على بلاد العجم والعراق .","date":["العام الهجري :918","العام الميلادي :1512"],"text":"تزايد ظهورُ شأن إسماعيل شاه بن حيدر الصفوي، فاستولى على سائر ملوك العجم، وملك خراسان، وأذربيجان، وتبريز، وبغداد، وعراق العجم، وقهر ملوكَهم، وقتل عساكِرَهم، بحيث قتل مئاتِ الألوف، وأظهر مذهبَ الإلحاد والرَّفض، وغيَّر اعتقاد أهل العجم, وكان عسكرُه يسجدون له ويأتمرون بأمرِه، وكاد يدَّعي الرُّبوبية! وقتَل العلماء، وأحرق كتُبَهم ومصاحِفَهم، ونبش قبور المشايخ من أهل السُّنَّة وأخرج عظامَهم وأحرقَها، وكان إذا قتل أميرًا أباح زوجته وأمواله لشخصٍ آخر، فلما بلغ السلطان سليم الأول سلطان الدولة العثمانية ذلك تحَّركت همَّته لقتاله، وعدَّ ذلك من أفضل الجهادِ، فالتقى معه سنة 920 بقرب تبريز، فكانت وقعة عظيمة انهزم فيها إسماعيل شاه وجيشه هزيمةً نكراء."},{"id":3594,"title":"استيلاء البرتغال على ثغر آزمور .","date":["العام الهجري :918","العام الميلادي :1512"],"text":"بعد فشل محاولة البرتغال احتلال ثغر آزمور سنة 914 بعث في هذا العام الطاغية منويل شكوادره فيها عشرين ألفًا من العسكر وألفين وسبعمائة خيالة، فانتهوا إلى آزمور وحاصروها بحرًا وزحفوا إليها من مدينة الجديدة برًّا، ووقعت حرب شديدة بينهم وبين أهل آزمور وأهل البادية، ثم انهزم المسلمون وخرجوا من باب تركه لهم البرتغال قصدًا ليفروا منها."},{"id":3595,"title":"خلع السلطان العثماني بايزيد الثاني نفسه وتولية ابنه سليم الأول .","date":["العام الهجري :918","الشهر القمري : صفر","العام الميلادي :1512"],"text":"بعد أن وزَّعَ السلطان بايزيد الثاني الولايات على أولاده حاول سليم أن يعلِنَ نفسه سلطانًا فحاربه أبوه، ثم عفا عنه، ثم في 18 صفر من هذه السنة ترك السلطان بايزيد حكمَ الدولة لابنه سليم الأول، وذلك بدعم من الجيش الانكشاري الذي سار به إلى استانبول، وكان الانكشارية ينظرون إليه على أنه الأمل المرتجى في بعثِ النشاطِ الحربيِّ للدولة العثمانية بصورة أوسع، ودفْع حركة الفتوحات إلى الأمام؛ ولذلك بادر الجيش إلى معارضة والده وتولية ابنه سليم مكانَه، فوافق واستقال من السلطنة معلنًا ابنه سليمًا الأول سلطانًا على الدولة العثمانية."},{"id":3596,"title":"انتشار الوباء وكثرة الموتى بمدينة زبيد .","date":["العام الهجري :918","الشهر القمري : جمادى الآخرة","العام الميلادي :1512"],"text":"كثر الموت بمدينة زَبيد وعمَّ الوباء وبلغ الموتى فيها كلَّ يوم إلى قريب من مائة نفس، ومات بسببه من الأعيان وغيرهم خلائق لا يحصَون."},{"id":3597,"title":"السلطان العثماني سليم الأول يتتبع إخوته ويقتلهم .","date":["العام الهجري :919","العام الميلادي :1513"],"text":"بعد أن تسلطن سليم الأول وعلا عرشَ الدولة العثمانية توجَّه للتخلص من إخوته الذين ينازعونَه السلطة أو لا يرضونَ به سلطانًا؛ الأمير \"كوركود\"، و الأمير \"أحمد\"، فالأول قام بتجميع جيش وأعلن العصيان ضد الدولة، أما الثاني فلم يكتفِ بإعلان العصيان بل اتَّفق مع أعدى أعداء الدولة العثمانية، وهي الدولة الصَّفوية ضد أخيه, فتعقَّب أخاه أحمد إلى أنقرة وقبض عليه بعد جَهدٍ وقتَلَه، ثم سار إلى ولاية صاروخان وتتَبَّع أخاه الآخر كركود ففرَّ منه وبعد البحث الشديد عنه تمكَّن منه وقتَلَه."},{"id":3598,"title":"تعيين سليمان بن سليم حاكم لاستانبول .","date":["العام الهجري :919","العام الميلادي :1513"],"text":"عيَّن السلطان سليم الأول ابنَه سليمان حاكمًا على إستانبول؛ ليتفرغ لأموره، فانتقل إلى أدرنة، فعقد معاهدات مع البندقية والمجر وموسكو ومماليك مصر."},{"id":3599,"title":"وفاة الشيخ أبي عبد الله محمد بن غازي المكناسي .","date":["العام الهجري :919","الشهر القمري : جمادى الأولى","العام الميلادي :1513"],"text":"هو الشيخ المحدث المقرئ الفقيه أبو عبد الله محمد بن محمد بن علي بن غازي، العثماني المكناسي ثم الفاسي المالكي، عالم المغرب وراويته الحيسوبي الفَرَضي صاحب الحواشي على الصحيح, والمعروف بابن غازي المكناسي. ولد سنة 841 بمكناس. برع في عدة فنون، لكنه اشتهر بالفقه، وكان بديع الخط متقِن الضبط. لم يكتفِ بالتعليم والتأليف، بل شارك في جهاد الإفرنج لحماية ثغور المغرب، حتى إنه توفي وهو في غزوة ضد النصارى بآصيلا؛ حيث مرض في هذه الغزوة، فأمر السلطان بحمله إلى منزله من فاس، فلما وصل إلى قرب عقبة المساجين اشتد به الحال وأمر أصحابَه أن يريحوا به هنالك، فبينما هو كذلك إذ مر به الشيخ أبو عبد الله الغزواني في سلسلته فسأل الموكلين به أن يعَرِّجوا به على الشيخ ابن غازي كي يعوده ويؤدي حقَّه، فلما وقف عليه طلب ابن غازي منه الدعاءَ، فدعا له بخير وانصرف. فلما غاب عنه قال ابن غازي لأصحابه: احفظوا وصيتي؛ فإني راحل عنكم إلى الله تعالى بلا شكٍّ، ثم حملوه إلى منزله فكان آخِر العهد به."},{"id":3600,"title":"هزيمة الدولة الصفوية في معركة (جالديران) على يد العثمانيين .","date":["العام الهجري :920","الشهر القمري : رجب","العام الميلادي :1514"],"text":"بعد أن نشأت الدولة الصفوية لم تكتفِ بفرض مذهبِها الشيعي على الناس بالقوةِ والقهر، بل بدأت تتحرَّش بالدولة العثمانية عن طريق إثارة الموالين لها من أصحابِ العمائم الحمر المعروفين بـ (قزلباش) ذوي التدين الشيعي، وأيضًا إثارتهم البرتغاليين وإرسال الرسائل لهم وحثهم على حرب العثمانيين، كما أنَّ احتضان الدولة لمراد بن أحمد الهارب من عمه السلطان سليم، كلُّ هذه الأمور اجتمعت لإثارة الحرب بين الدولتين العثمانية والصفوية، فتوجَّه السلطان العثماني سليم الأول بجيشٍ عظيم من أدرنة إلى الصفويين، وكان قد أحصى الشيعةَ الذين يقيمون في شرقي الدولة؛ لأنهم سيكونون أنصارًا للصفويين، وأمر بقتلهم جميعًا، ثم تقدَّم نحو تبريز عاصمة الصفويين الذين أرادوا الخديعة بالتراجُعِ حتى إذا أُنهك الجيش العثماني انقضُّوا عليه، وبقي السلطان العثماني في تقدُّمِه حتى سهل جالديران جنوب قارص شرقي الأناضول، وكانت فيه معركةٌ شرسة في شهر رجب من هذا العام عُرِفت بمعركة جالديران، انتصر فيها العثمانيون وفَرَّ من الميدان إسماعيل شاه الصفوي، ثم دخل السلطان العثماني تبريز في شهر رمضان واستولى على الخزائن ونقلها إلى إستانبول وتتبَّع إسماعيل لكنَّه لم يستطع القبض عليه، وأقبل فصلُ الشتاء فاشتد الأمرُ على الجنود وبدأ تذمُّرُهم، فترك السلطان المنطقة وسار نحو أماسيا حتى انتهى فصل الشتاء فرجع إلى أذربيجان، ففتح بعض القلاع ودخل إمارةَ ذي القادر، ثم رجع إلى إستانبول بعد أن ترك الجيش العثماني الذي دخل أورفة والرقَّة وماردين والموصل."},{"id":3601,"title":"انضمام الإمارة السلجوقية إلى الدولة العثمانية .","date":["العام الهجري :921","العام الميلادي :1515"],"text":"بعد أن استطاع السلطان العثماني سليم الأول أن ينتصرَ على الصفويين في معركة جالديران، ترك جيشًا كان مهمتُه الاستيلاء على الرقَّة وأورفة وماردين والموصل، وقبل هذا قام السلطان بعد أن انتهى من استراحته حتى انتهى الشتاء بالرجوع إلى أذربيجان ففتح فيها بعض القلاع ودخل إمارة ذي القدر السلجوقية، وأميرُها علاء الدولة، التي كانت تعتبر تحت سيطرة المماليك، وهذه الإمارة تضم مدن أبلستين ومرعش وعينتاب، فأصبحت ضمن أراضي الدولة العثمانية، وقد عين عليها السلطانُ سليم ابنَ شاه سوار، وهذا الأمر أثار حفيظة السلطان المملوكي قانصوه الغوري الذي جهَّز جيشًا وتوجَّه به إلى الشام لقتال العثمانيين الذين توجهوا هم أيضًا إلى الشام."},{"id":3602,"title":"التحالف بين الدولة الصفوية والبرتغاليين .","date":["العام الهجري :921","العام الميلادي :1515"],"text":"ما إن هُزمَ إسماعيل شاه الصفوي في موقعة جالديران العام الماضي أمام السلطان العثماني سليم الأول حتى كان أكثرَ استعدادًا وتقبلًا من قبلُ للتحالف مع البرتغاليين، وبدأ في الاستعداد للارتباط بالبرتغال عقِبَ استيلاء البوكرك على هرمز، عندها وصل سفيرٌ من لدى إسماعيل شاه وتمَّ الدخول في اتفاقية محدودة بين البرتغاليين والصفويين نصَّت على ما يلي: أن يقدِّم البرتغال أسطولَه ليساعدَ الفُرسَ في غزو البحرين والقطيف، كما يقدِّم البرتغال المساعدة لإسماعيل شاه لقمع الثورة في مكران وبلوجستان، وأن يكوِّن الشعبان البرتغالي والفارسي اتحادًا ضد العثمانيين، إلَّا أن وفاة البوكرك التي أتت بعد ذلك قد أعاقت ذلك التحالف، ولقد أظهر البرتغاليون تودُّدًا لإسماعيل شاه قبل معركة جالديران، وكانوا يهدفون من وراء تودُّدهم للصفويين أن تتاح لهم فرصة تحقيق أهدافهم في إيجاد مراكزَ لهم في الخليج العربي، وكانوا يُدركون أنهم إذا لم يكسبوا وُدَّ الصفويين فإن تعاوُنَ قوَّتِهم مع القوى المحلية في الخليج قد يؤدي إلى فشلِهم في تحقيق أهدافهم ولا سيما أن مشروعاتِهم في إيجاد مراكز نفوذ في البحر الأحمر مُنِيت بالفشل إلى حدٍّ كبير، لقد أدَّت هزيمة إسماعيل شاه أمام العثمانيين إلى حرصه الشديد للتحالف مع النصارى وأعداء الدولة العثمانيَّة؛ ولذلك تحالف مع البرتغاليين وأقرَّ استيلاءهم على هرمز في مقابل مساعدتِه على غزو البحرين والقطيف، إلى جانب تعهدِهم بمساندتهم ضد القوات العثمانية، وقد تضمَّن مشروع التحالف البرتغالي الصفوي تقسيمَ المشرق العربي إلى مناطقِ نفوذٍ بينهما، حيث اقترح أن يحتلَّ الصفويون مصرَ، والبرتغاليون فلسطينَ."},{"id":3603,"title":"استيلاء البرتغال على ثغر المعمورة بالمغرب .","date":["العام الهجري :921","الشهر القمري : جمادى الأولى","العام الميلادي :1515"],"text":"بلغ منويل البرتغالي أنَّ مينا المعمورة جيِّدة وبلادها نفاعة، فبعث إليها طائفةً من جنده فوصلوا إلى ساحلِها ونزلوا في البرِّ المقابل لها، وبنَوا هنالك برجًا لحصارها، ثم أردفهم مَلِكُهم منويل بعمارة تشتملُ على مائتي مركبٍ مشحونة بثمانية آلاف من المقاتلة، وكان خروج هذه العمارة من مدينة أشبونة، فوافت مينا المعمورة في الثالث والعشرين من يونيه من هذه السنة، وحاصروها وألحُّوا عليها بالقتال أيامًا، وبلغ الخبر بذلك إلى السلطان أبي عبد الله محمد البرتغالي، فبعث أخاه الناصر صريخًا في جيشٍ كثيف، وقاتل البرتغال قتالًا شديدًا وهزمهم هزيمةً قبيحة، ثم كانت لهم الكَرَّة على المسلمين فهزموهم واستولوا على المعمورة، وثبت قدمُهم بها وحصَّنوها بالسور الموجود بها الآن، واستمروا بها نحو خمس سنين ثم استرجعها المسلمون منهم بعد ذلك."},{"id":3604,"title":"وفاة القائد البحري فاسكو دي جاما البرتغالي .","date":["العام الهجري :922","العام الميلادي :1516"],"text":"هو القائد البحري فاسكو دي جاما البرتغالي، ولد سنة 1460م في عائلة نبيلة، ودرس الملاحة البحرية، أوكل إليه ملك البرتغال مانويل الأول حملةً بحرية يصل فيها لبلاد الشرق دون المرور ببلاد المسلمين, فانطلق برحلته سنة 1497م من لشبونة ووصل بلاد الهند عبر طريق رأس الرجاء الصالح، وذلك بعد اعتماده على معلومات وخبرات البحَّار المسلم أحمد بن ماجد النجدي العماني، وكان من أثر هذه الرحلة زيادةُ أطماع البرتغال الاستعمارية، فبعث الملك مانويل الأول حملةً بحرية عسكرية من 13 سفينة إلى الهند، فصدَّها الهنود، وقتلوا عددًا كبيرًا منها, فأوكل الملك مانويل إلى فاسكو دي جاما رحلة من 15 سفينة سنة 1502م, فعبَرَت رأس الرجاء الصالح ثم المحيط الهندي، حتى وصلت إلى بحر العرب، فسيطروا على مركب تجاري للمسلمين عدد ركابها 380 راكبًا كانوا عائدين من الحجِّ, فأمر فاسكو دي جاما بقتلهم جميعًا, فأضرم بها النار, واستغرقت السفينة أربعة أيام لتغرق في البحر؛ مما أدى إلى مقتل جميع من فيها من رجال ونساء وأطفال؛ مما أدى إلى ثورة المسلمين ضدَّه فهرب دي جاما شرقًا حتى وصل إلى مدينة غوا، وقد عمِلَ فاسكو دي جاما على قرصنة سفن المسلمين، فحطم لهم أسطولًا كاملًا عدد سفنه تسع وعشرين سفينة. كما قام بشنق 38 صيادًا ثم قطع رؤوسهم وأطرافهم ورمى بالجثث والأشلاء في البحر لتطفوَ بالقرب من شاطئ مدينة كاليكوت ليُرهب المسلمين فيها, ثم عاد إلى البرتغال سنة 1503م فتنقل في عدَّة مناصب عسكرية وإدارية، ثم عُيِّن نائبًا عن ملك البرتغال في الهند، وبعد وصوله بلاد الهند عاجلته المنية فهلك في الهند، ثم نُقل رفاتُه إلى البرتغال."},{"id":3605,"title":"هزيمة السلطان المملوكي على السلطان العثماني سليم الأول .","date":["العام الهجري :922","الشهر القمري : رجب","العام الميلادي :1516"],"text":"عندما استولى السلطان سليم الأول العثماني على إمارة ذي القادر التي كانت تابعة للدولة المملوكية وتوجَّه إلى الشام، أثار مخاوف السلطان المملوكي قانصوه الغوري الذي جهز جيشًا وتوجه به إلى الشام، وزاد هذا الأمر أنَّ المماليك وقفوا مع الصفويين ضد العثمانيين في ذي القادر ومرعش، بينما أمراء الشام شجَّعوا العثمانيين على القدوم إلى الشام؛ لخوفهم من الزحف البرتغالي، وربما أيضا زاد هذا أن علاء الدين الهارب من عمِّه سليم الأول والذي لجأ إلى قانصوه الغوري ولم يسلِّمْه الأخير للسلطان سليم، كلُّ ذلك ولَّد هذا التنافر بين الدولتين اللتين أصبحتا على عتبة الحرب، وكان السلطان قانصوه الغوري لعلمِه بقوة الجيش العثماني أرسل رسولًا للصلح الذي رفضه سليم الأول، فسار بجيشه إلى الشام والتقى الطرفان في مرج دابق غربيَّ مدينة حلب في الخامس والعشرين من رجب، ثم إن نواب الشام: خيري بك نائب حلب، وجانبردي نائب الشام، انضموا إلى العثمانيين فانتصر العثمانيون على المماليك، وقُتِل قانصوه الغوري فيها، ودخل السلطان سليم حلبَ وحماة وحمص ودمشق دون أي مقاومة، وأبقى ولاةَ الشام على ولاياتهم حسبما وعدهم، فعيَّن السلطانُ سليم جانبردي الغزاليَّ على دمشق، وعين فخر الدين المعني على جبال لبنان، وهو درزي لكنه كان ممن ساعد العثمانيين على المماليك رغبةً في الولاية, ثم اتجه إلى مصر، وكان المماليك قد عيَّنوا سلطانا آخر هو طومان باي."},{"id":3606,"title":"وفاة السلطان المملوكي الأشرف الغوري وتسلطن طومان باي .","date":["العام الهجري :922","الشهر القمري : رجب","العام الميلادي :1516"],"text":"هو السلطان الأشرف أبو النصر قانصوه بن بيبردى الغوري الجركسي الجنس, وهو من سلاطين المماليك البرجية. ولِدَ سنة 850 امتلكه الأشرف قايتباي وأعتقه وعيَّنه في عدة وظائف في خدمته. كان في أوائل الأمر أميًّا لا يعرف شيئًا؛ لأنه جُلب من بلاده وهو كبير قد شَرَع فيه الشيب، وصار السلطان قايتباي يرقِّيه لكونه أخًا لزوجته، وهي التي بذلت الأموال للجند ومكَّنَته من الخزائن حتى ملَّكوه بعد السلطان قايتباي، فاستمر سلطانًا سنة وسبعة أشهر، ثم خلعوه وكان قد تلقب بالأشرف وأخرجوه من المملكة سنة 905 وولي بعده أميران لم يثبت قدمُهما في السلطنة، ثم أجمع الأجناد على تولية السلطان قانصوه الغوري، وكان من أقَلِّ الأمراء شأنًا وأحقرهم مكانةً، لكن الأمراء الكبار تحامَوا الإقدام على السلطنة خوفًا من بعضهم البعض، فولوا قانصوه فقَبِلَ بعد أن شرَطَ عليهم أنهم لا يقتلونه إذا أرادوا خلعَه، فقبلوا منه ذلك فولي السلطنة سنة 906 وكان عظيم الدهاء قويَّ التدبير، فثبت قدمه في السلطنة ثباتًا عظيمًا، وما زال يقتل أكابِرَ الأمراء حتى أفناهم وصَفَت له المملكة ولم يبقَ له فيها منازعٌ، ولكنه مال إلى الظلم والعسف وانتهب أموال الناس وانقطعت بسببه المواريثُ، فضجَّ أهلُ مصر ومَن تحت طاعتِه؛ مِن أخذِه لأموالهم، فسلط الله عليه السلطان سليم الأول سلطانَ العثمانيين؛ فإنه غزاه إلى دياره ووقع بينهما مصاف، فقُتِل قانصوه الغوري تحت سنابك الخيل في معركةِ مرج دابق وعمرُه إذ ذاك يقارب الثمانين عامًا، وكانت مدة سلطنته ستة عشر سنة وعدة أشهر، فاختار المصريون سلطانًا جديدًا هو نائبه الذي تركه السلطان قانصوه على مصر: طومان باي، الذي تلقَّب بالملك الأشرف بعد أن أقسَمَ له الأمراء بالطاعة وبايعوه، وبايعه الخليفة كذلك."},{"id":3607,"title":"استيلاء القائد عروج باشا على تلمسان والتغلب على أمر بني زيان .","date":["العام الهجري :923","العام الميلادي :1517"],"text":"استولى القائد عروج باشا، وهو من قواد البحرية الترك، على تلمسان من أيدي بني زيان، إلَّا أن أهل تلمسان أنكروا سيرةَ الترك وسئِموا ملكَهم, ويقال: إن التركَ عسفوهم وصادروا أموالهم، فدارت الكَرَّة على عروج سنة 924 فقُتِل هنالك مع جماعة من وجوه عسكره، وتفرَّقت جموعه وعادت تلمسان مرةً أخرى لبني زيان."},{"id":3608,"title":"البابا ليو العاشر يستعد لحرب صليبية لمواجهة سليم الأول العثماني .","date":["العام الهجري :923","العام الميلادي :1517"],"text":"لم يلبث السلطانُ سليم الأول أن يفرغَ من انتصاراته في بلاد العربِ والعجمِ حتى دبَّ الرعبُ والفزع في قلوب الصليبيين، وما استطاعت الدولة العثمانية أن تحرِزَه من ضَمٍّ للبلدان الأوربية إليها حتى تصبِحَ تحت سيطرتِها، فحدا هذا بالبابا ليو العاشر الذي كانت أيضًا بينه وبين غيره من النصارى منافسات، فقام في هذه السنة بالنداء لحرب صليبية ضد الدولة العثمانية مانحًا صكوك الغفران كالعادة لمن يستجيب, ومثيرًا في النصارى عزائم الواجب المقدَّس لخدمة الصليب، لكن هذه الدعوة لم تلقَ سوى هزائم ولم تلقَ أي انتصار!"},{"id":3609,"title":"وفاة السلطان القائم بأمر الله أبو عبد الله محمد السعدي .","date":["العام الهجري :923","العام الميلادي :1517"],"text":"هو السلطانُ أبو عبد الله محمد بن محمد بن علي بن مخلوف بن زيدان، الملقَّب بالقائم بأمر الله، عميد الأسرة السعدية وسلطان المغرب. كان قد نشأ على عفافٍ وصلاحٍ وحجٍّ للبيت الحرام، وقيل: كان مجابَ الدعوةِ، من قرَّاءِ القرآن، ومن أهلِ العلمِ والدين، ولم يكن من بيت الرياسةِ، وكان له اطِّلاعٌ على تواريخ قُطره وعوائدِ جيله وأخلاقهم وطبائعهم، ورأى ما وصل إليه مُلكُ بني وطاس بالمغرب من الانحطاط والضعف، وتيقَّن أنَّه لا يصعب عليه تناولُه، فأعمل في ذلك فِكرَه وصار يحضُّ الناسَ على القيام بأمور دينهم والامتعاض لها، حتى ولي الأمرَ عندما بايعَتْه قبائل المغرب على حربِ البرتغال، وقدَّمت كلُّ قبيلة له عشرةَ رجال من أبنائها, فلما قضى الله ببيعته واجتماع الناس عليه، واطمأنت به في البلاد السوسية الدار وطاب له بها المقام والقرار؛ ندب الناس إلى بيعةِ أكبر ولديه، وهو الأمير أبو العباس أحمد المعروف بالأعرج، فبايعوه, ثم وفد على القائمِ بأمر الله أشياخُ حاحة والشياظمة لِما بلغهم من حسن سيرته ونصرة لوائه، فشَكَوا إليه أمر البرتغال ببلادهم, وشِدَّة شوكته واستطالته عليهم، وطلبوا منه أن ينتقل إليهم هو وولده ولي العهد، فأجابهم إلى ذلك ونهض معهم هو وابنه أبو العباس إلى الموضع المعروف بآفغال من بلاد حاحة، وترك ولده الأصغر أبا عبد الله محمد الشيخ بالسوس يرتِّب الأمور ويمهِّد المملكة ويباكر العدو بالقتال ويراوحه، واستمر الأمير أبو عبد الله القائم بمكانه من آفغال ببلاد حاحة مسموعَ الكلمة متبوعَ العقب إلى أن توفي بها وهو يجاهد النصارى الإسبان والبرتغال، ودفن بها ثم نقل إلى مراكش."},{"id":3610,"title":"عودة فتنة الشيعة القزلباش في شرقي الأناضول .","date":["العام الهجري :923","العام الميلادي :1517"],"text":"عاد جماعة من القزلباش- أي أصحاب العمائم الحمراء- إلى الانقضاض على الدولة العثمانية في منطقة ما بين النهرين بشرق الأناضول، وقد أمدتهم الدولة الصفوية الشيعية بقوة عسكرية، فأخذوا يُغيرون على الجماعات الآشورية والجماعات الكردية السُّنَّة، واستولوا على حاضرتهم آمد التي عرِفَت فيما بعد بديار بكر، وجرت بين الفريقين وقائع كانت الغلبة فيها لجماعات القزلباش، فاستنجد الأكرادُ بالسلطان سليم الأول فأمَدَّهم بقوة كبيرة في أعقاب انتصاره على دولة المماليك في وقعة مرج دابق، فانتصرت قواتُه على القوات الصفوية، وطُرِد الأكراد القزلباش من شرقي الأناضول، واستولت على الموصل وثبتت سلطة الدولة العثمانية في شمال العراق."},{"id":3611,"title":"قضاء المماليك على الطاهريين في اليمن في معركة الصافية .","date":["العام الهجري :923","العام الميلادي :1517"],"text":"كان الخطر البرتغالي يهدد التجارة في البحر الأحمر والخليج العربي، وبالتالي يهدِّد التجارة المصرية التي يتولاها المماليك، ولما كان البرتغاليون وصلوا إلى مرحلة هددوا فيها كل شيء للعرب أو المسلمين في البحر، وليس فقط التجارة، فأرسل المماليك قوة إلى اليمن لتواجه القوة البرتغالية؛ فقد أرسل السلطان قانصوه الغوري أسطولًا بحريًّا بقيادة حسين الكردي سنة 922 إلى اليمن؛ حيث طلب حسين من الملك عامر الثاني الطاهري العونَ، ولكنَّ طاهرًا رفض ذلك، فقام حسين الكردي بمقاتلته فجرت بينهما معركة كان نتيجتها أن احتلَّ حسين زبيدَ عاصمةَ اليمن وقتَها، ونصب أخاه برسباي حاكمًا عليها، وهرب عامر الطاهري وأخوه عبد الملك إلى تعز، وقد حاولا في العام التالي محاربة بارسباي؛ لاستعادة ملكِهما وإعادة البلاد لحكمِهما، فاستعدَّا بجيش من الذين بقوا معهم وممن والاهم في تعز وساروا إلى برسباي لقتاله، فوقعت بينهم معركة في الصافية استطاع جيش المماليك أن يقضيَ على جيش الملك عامر وأخيه اللذين قُتِلا في المعركة، فكان ذلك انقراضًا لدولة الطاهريين في اليمن."},{"id":3612,"title":"وفاة ابن ماجد أحد كبار الملاحين العرب .","date":["العام الهجري :923","العام الميلادي :1517"],"text":"هو البحار المشهور شهاب الدين أحمد بن ماجد بن عمر بن فضل بن دويك بن يوسف بن حسن بن حسين بن أبي معلق السعدي ابن أبي الركائب النجدي العماني، عُرِفَ بأسد البحر أحد كبار الملاحين العرب، ولد سنة 838 في مدينة جلفار- تقع في رأس الخيمة اليوم- ونشأ بها. ينحدر ابن ماجد من أسرة اشتهرت بالملاحة وارتياد البحار, اشتهر ابن ماجد بعلمه في شؤون البحار وما يتصلُ بذلك من علوم الملاحة والفلك والرياضيات والجغرافيا. رحل إلى بلاد كثيرة مدونًا كلَّ ما يشاهده من بلدان؛ فقد ذكر في مؤلفاته أسماء الجزر التي رآها والقياسات البحرية ومطالع النجوم، وطريقة استخراج القبلة، وشرحَ المسالكَ البحرية بين ساحل وآخر، ودَوَّن علمه ومعرفته في مؤلفات عديدة، منها: كتاب الفوائد في أصول علم البحر والقواعد، وهو أكبر أعماله، ويعُتبر علم الملاحة الفلكية من أهم أعماله؛ فقد كانت قياساته دقيقة ومبتكَرة، كما كانت مشاهداته للنجوم ومطالعها ومغاربها كذلك، وله أراجيز تحمل علومهَ، منها: حاوية الاختصار في علم البحار، وله قصائد في وصف شواطئ جزيرة العرب, ومن أسباب اشتهار ابن ماجد في تاريخ الملاحة ارتباطُ اسمه برحلة البرتغالي فاسكو دي جاما سنة (1498م) من ساحل إفريقيا الشرقي إلى كلكتا في الهند، وكان لهذا الحادث أثرٌ خطير في تاريخ الملاحة، وأثرٌ في الحملات الاستعمارية الأوربية لاحتلال سواحل ومراكز مهمة في بحر العرب والمحيط الهندي."},{"id":3613,"title":"وفاة الإمام العلامة شهاب الدين القسطلاني .","date":["العام الهجري :923","الشهر القمري : محرم","العام الميلادي :1517"],"text":"هو الشيخُ الإمام العلامة الحافظُ الحجَّة الرُّحَلة الفقيه المقرئ المسنِد المؤرخ الخطيبُ: شهاب الدين أبو العباس أحمد بن محمد بن أبي بكر بن عبد الملك بن الزين أحمد بن الجمال محمد بن الصفي محمد بن المجد حسين بن التاج علي القسطلاني الأصل، القتيبي المصري الشافعي، ويعرف بالقسطلاني علَّامة الحديث, وأمُّه حليمة ابنة الشيخ أبي بكر بن أحمد بن حميدة النحاس. ولِدَ في الثاني والعشري ذي القعدة سنة 851 بمصر ونشأ بها فحفظ القرآن والشاطبيتين, والقراءات السبع ثم العشر، وكذا أخذ القراءات عن الشمس بن الحمصاني إمام جامع ابن طولون, وقرأ صحيحَ البخاري بتمامه في خمسة مجالسَ على الشاوي، وكذا قرأ عليه ثُلاثيات مسند أحمد، وحجَّ غير مرة وجاور سنة أربع وثمانين ثم سنة أربع وتسعين وسنتين قبلها على التوالي. وجلس للوعظ بالجامع العمري سنة ثلاث وسبعين وكذا بالشريفية بالصبانيين، بل وبمكة, ولم يكن له نظيرٌ في الوعظ، وكان يجتمع عنده الجمُّ الغفير مع عدم ميلِه في ذلك، وولي مشيخة مقام أحمد بن أبي العباس الحرَّاز بالقرافة الصغرى، وأقرأ الطلبة وجلس بمصر شاهدًا رفيقًا لبعض الفضلاء, وبعده اعتزل وتفرَّغ للكتابة, فكتب بخطِّه لنفسه ولغيره أشياء، بل جمع في القراءات العقود السنية في شرح المقدمة الجزرية في التجويد، ومن مؤلفاته: إرشاد الساري على صحيح البخاري، انتهى منه سنة 916, وتحفة السامع والقاري بختم صحيح البخاري, ونفائس الأنفاس في الصحبة واللباس, والروض الزاهر في مناقب الشيخ عبد القادر, وعمل تأليفًا في مناقبه سماه: نزهة الأبرار في مناقب الشيخ أبي العباس الحرَّار, وتحفة السامع والقارئ بختم صحيح البخاري. وهو كثير الأسقام قانعٌ متعفِّف جيد القراءة للقرآن والحديث والخطابة، شجيُّ الصوت بها، مشارك في الفضائل، متواضع متودِّد لطيف العشرة سريعُ الحركة. قال محي الدين عبد القادر العَيدَروس: \"وارتفع شأنُه بعد ذلك فأُعطيَ السعدَ في قَلَمِه وكَلِمِه، وصنَّف التصانيف المقبولة التي سارت بها الركبانُ في حياته، ومن أجَلِّها شرحُه على صحيح البخاري مزجًا في عشرة أسفار كبار، لعله أحسَنُ شروحِه وأجمعُها وألخصُها، ومنها المواهب اللدُنِّية بالمنح المحمدية، وهو كتاب جليل المقدار عظيم الوقع كثير النفع، ليس له نظير في بابه، ويحكى أن الحافظ السيوطي كان يغُضُّ منه ويزعم أنه يأخذ من كتبه ويستمدُّ منها ولا ينسبُ النقل إليها، وأنَّه ادَّعى عليه بذلك بين يدي شيخ الإسلام زكريا فألزمه ببيان مدَّعاه، فعدد عليه مواضِعَ قال إنه نقَلَ فيها عن البيهقي، وقال إن للبيهقي عدةَ مؤلفات فليذكرْ لنا ما ذكر في أي مؤلفَّاته ليُعلَمَ أنَه نقل عن البيهقي، ولكنه رأى في مؤلفاتي ذلك النقلَ عن البيهقي فنقله برُمَّته، وكان الواجب عليه أن يقول نقل السيوطي عن البيهقي، وحكى الشيخ جار الله بن فهد رحمه الله: أنَّ الشيخ رحمه الله تعالى قصد إزالةَ ما في خاطر الجلال السيوطي فمشى من القاهرة إلى الروضة، وكان السيوطي معتزلًا عن الناس بالروضة فوصل القسطلاني إلى باب السيوطي ودق الباب فقال له: من أنت؟ فقال: أنا القسطلاني جئتُ إليك حافيًا مكشوف الرأس ليطيبَ خاطرُك عليَّ، فقال له: قد طاب خاطري عليك، ولم يفتح له الباب ولم يقابله! وبالجملة فإنه كان إمامًا حافظًا متقنًا جليل القدر حسن التقرير والتحرير، لطيف الإشارة بليغ العبارة، حسن الجمع والتأليف، لطيف الترتيب والتصنيف، كان زينة أهل عصره، ونقاوة ذوي دهره، ولا يقدح فيه تحامُلُ معاصريه عليه، فلا زالت الأكابر على هذا في كل عصرٍ- رحمهم الله\" أصيب القسطلاني بالفالج، ثم توفي ليلة الجمعة السابع محرم بالقاهرة ودفن بالمدرسة العينية جوار منزله، ووافق يومُ دفنه الثامن محرم دخولَ السلطان سليم الأول العثماني عَنْوةً إلى مصر وتملُّكه بها."},{"id":3614,"title":"انتصار العثمانيين ونهاية دولة المماليك والخلافة العباسية .","date":["العام الهجري :923","الشهر القمري : محرم","العام الميلادي :1517"],"text":"بعد أن انتصر السلطانُ العثماني سليم الأول على السلطان المملوكي قانصوه الغوري وقتَلَه في معركة مرج دابق سنة 922، سار إلى مصر، وأرسل السلطان سليم إلى السلطان الجديد طومان باي يعرِضُ عليه الصلح مقابِلَ الاعتراف بسيادة العثمانيين على مصر، غيرَ أن طومان باي رفض ذلك واستعدَّ للقتال، والتقى الطرفان أولًا على حدود بلاد الشام في معركة أولى انهزم فيها المماليك، ثم دخل العثمانيون غزةَ ثم أكملوا مسيرَهم إلى مصر حتى وصلوا إلى الريدانية على أبواب القاهرة، فجرت بين الطرفين معركةٌ انطلق فيها السلطان طومان باي المملوكي إلى مقَرِّ السلطان سليم الأول العثماني ومعه بعضُ الفرسان وقتلوا مَن حوله وأسَروا الوزير سنان باشا وقتَلَه طومان بعد ذلك، ولكن المعركةَ انتهت بانتصار العثمانيين خاصةً؛ لوجود المدافع التي معهم ثمَّ في الثامن من محرم دخل العثمانيون القاهرة، وهرب طومان باي نحو الجيزة غيرَ أنه سقط أسيرًا بأيدي العثمانيين الذين قتلوه في الحادي والعشرين من ربيع الأول من هذا العام، فكان بنهايته نهاية الدولة المملوكيَّة، ثمَّ إنَّ السلطان العثماني سليم الأول بايعه أهلُ مصر، وتنازل له الخليفة العباسي المتوكل على الله محمد بن يعقوب عن الخلافة, وبذلك أيضًا انقضت الخلافة العباسية التي دامت تحت ظلِّ المماليك قرابة المائتين وأربع وستين سنة! وانطوت من التاريخ الخلافةُ في مصر لتبدأ الخلافة من جديدٍ في إستانبول, ولَقَّب السلطانُ سليم الأول نفسَه بخادم الحرمين الشريفين أثناء خطبة الجمعة التي أُلقِيت في الجامع الكبير بحلب."},{"id":3615,"title":"وفاة السلطان طومان باي آخر سلاطين الدولة المملوكية .","date":["العام الهجري :923","الشهر القمري : محرم","العام الميلادي :1517"],"text":"هو السلطان الأشرف طومان باي آخر سلاطين الدولة المملوكية بمصر، ويُذكَر أن أصله من بلاد الغور، اشتراه قانصوه الغوري وقَدَّمه للملك الأشرف قايتباي، ثم وَرِثَه ابنُه الناصر محمد الذي أعتقه. تولى نيابة السلطنة المملوكية في عهد السلطان المملوكي الأشرف قونصوه الغوري، ثم بويع طومان باي بالسلطنة بعد معركة مرج دابق, لكِنَّ أيامه لم تطُلْ؛ فقد هُزم أمام العثمانيين في معركة الريدانية وسقط أسيرًا بأيديهم؛ حيث قتلوه في الحادي والعشرين من ربيع الأول من هذا العام، فكان بنهايته نهايةُ الدولة المملوكية التي دامت قرابة المائتين وخمس وسبعين سنة بقسميها المماليك البحرية والمماليك البرجية الشراكسة."},{"id":3616,"title":"السلطان العثماني سليم الأول يعلن الخلافة ويستلم مفاتيح الكعبة .","date":["العام الهجري :923","الشهر القمري : صفر","العام الميلادي :1517"],"text":"لَمَّا دخل السلطانُ سليم الأول القاهرةَ وقتَلَ السلطان المملوكيَّ طومان باي آخِرَ سلاطين دولة المماليك وتنازلَ الخليفة العباسي له بالخلافةِ كُرهًا- على ما قيل- وجاءه أيضًا أشراف الحجاز مع أمير مكة الشريف محمد أبا نمي بن بركات ليَدينوا له بالطاعة وسَلَّموا له مفاتيح الكعبة، فولى السلطان الشريف محمد أبا نمي ولاية الحجاز، ثمَّ بعد أن أقام شهرًا في مصر بعد أن وطَّد فيها دعائم الحُكم ملحِقًا حكم مصر بالشام لنائِبِها، وعين نائبًا له بمصر هو خيري بك، وفرض المذهب الحنفيَّ دون سائر المذاهب في الحكم والقضاء، ثم عاد إلى إستانبول آخذًا معه الخليفة العباسي المتنازل عن الخلافة وآخذًا معه أيضًا مفاتيح الحرمين الشريفين، فأصبح هو بذلك خليفةَ المسلمين وتلقَّب بخادم الحرمين الشريفين."},{"id":3617,"title":"إعلان العثمانيين قيام الخلافة الإسلامية في دولتهم .","date":["العام الهجري :923","الشهر القمري : صفر","العام الميلادي :1517"],"text":"بعد أن استطاع العثمانيون القضاء على الدولة المملوكية بمصر وسقوطها، وكانوا قبل ذلك قد استطاعوا أن يسيطروا على الشامِ، ثم بعد مصر على الحجاز، فأضحت الإماراتُ التي كانت تابعةً للماليك تابعةً لهم هم، وكانوا قد توسَّعوا في أوروبا أيضًا، فكان هذا التوسعُ في الشرق والغرب والشمال والجنوب- نصرًا لهم، وانتقلت الخلافة إليهم بعد أن كانت في العباسيين، فكان هذا إعلانًا لقيام الخلافة الإسلاميَّة في الدولةِ العُثمانية."},{"id":3618,"title":"ترتيب السلطان سليم الأول أوضاع مصر  .","date":["العام الهجري :923","الشهر القمري : صفر","العام الميلادي :1517"],"text":"لما أخذ السلطان سليم الأول مصر ورأى غالبَ حكامِها من المماليك الذين وَرِثوها عن ساداتهم؛ رأى أنَّ بُعدَ الولايةِ عن مركز الدولة ربما أوجب خروجَ حاكِمِها عن الطاعة وتطَلُّبَه الاستقلال، فجعل حكومة مصر منقسمةً إلى ثلاثة أقسام، وجعل في كل قسم رئيسًا، وجعلهم جميعًا منقادين لكلمة واحدة هي كلمة وزير الديوان الكبير، وجعله مركَّبًا من الباشا الوالي من قِبَله، ومن بيكوات السبع وجاقات، وجعل للباشا مزيةَ توصيل أوامر السلطان إلى المجلس وحَفْظ البلاد وتوصيل الخَراج إلى القسطنطينية، ومنع كلًّا من الأعضاء العلو على صاحبه، وجعل لأعضاء المجلس مزيةَ نقضِ أوامر الباشا بأسبابٍ تبدو لهم وعزله إن رأوا ذلك، والتصديق على جميع الأوامر التي تصدر منه في الأمور الداخلية، وجعل حكَّام المديريات الأربع والعشرين من المماليك، وخَصَّهم بمزية جمع الخَراج في البلاد، وقَمْع العُربانَ وصَدهم عنها والمحافظة على ما في داخلها، وكل ذلك بأوامر تصدرُ لهم من المجلس، وجردَّهم عن التصرف من أنفسِهم، ولقب أحدَهم المقيم بالقاهرة بشيخ البلد، ثم رتب الخراج وقسَّمه أقسامًا ثلاثة، وجعل من القسم الأول ماهية عشرين ألف عسكري بالقطر من المشاة واثني عشر ألفا من الخيالة، والقسم الثاني يرسَل إلى المدينة المنورة ومكة المشرفة، والقسم الثالث يرسَل إلى خزينة الباب العالي، ولم يلتفت إلى راحة الأهالي بل تركها عُرضةً للمضارِّ كما كانت، ومن هذا الترتيب تمكَّنت الدولة العلية من إبقاء الديار المصرية تحت تصرفِها نحو مائتي سنة، ثم أهملت بعد ذلك هذه القوانينَ التي وضعها السلطانُ سليم من حين استيلائِه عليها، وكانت هي الأساس، ولم تلتفت الدولة لما كان يحصُلُ من المماليك من الأمور المخِلَّة بالنظام، فضعُفَت شوكة الدولة وهيبتُها التي كانت لها على مصر، وأخذ البكوات تُكثِرُ من المماليك وتتقَّوى بها، حتى فاقت بقوتها الدولة العثمانية في الديار المصرية، فآل الأمر والنهي لهم في الحكومةِ، وصارت الدولة صوريةً غيرَ حقيقية، وسبب ذلك إكثارُهم من شراء المماليك، ولو كانت الدولة العليَّة تنبهت لهذا الأمر ومنعت بيعَ الرقيقِ، لكانت الأمور باقيةً على ما وضعه السلطان سليم، ولكن غفَلَت عن هذا الأمر كما غفَلَت عن أمور كثيرة؛ ولذلك لحق الأهالي الذلُّ والإهانة، وهاجر كثيرٌ منهم إلى الديار الشامية والحجازية وغيرهما، وخربت البلاد، وتعطلت الزراعة من قلة المزارعين وعدم الاعتناء بتطهير الجداول والخلجان التي عليها مدار الخصب، ونتج من ذلك ومن خوف الدولة العليَّة مِن تمكُّن الباشا في الحكومة: أن تغلَّبَ البكواتُ وصارت كلمتُهم هي النافذةَ، وانفردوا بالتصَرُّف."},{"id":3619,"title":"تعيين أول وال عثماني على مصر. .","date":["العام الهجري :923","الشهر القمري : ربيع الأول","العام الميلادي :1517"],"text":"عُيِّن الوزيرُ الأعظم رئيسُ الوزراء العثماني يونس باشا كأوَّل والٍ عثمانيٍّ على مصر."},{"id":3620,"title":"وفاة الملك الظافر عامر بن عبدالوهاب سلطان اليمن .","date":["العام الهجري :923","الشهر القمري : ربيع الآخر","العام الميلادي :1517"],"text":"هو الملك الظافر عامر بن عبد الوهاب بن داود بن طاهر: سلطان اليمن. ولِدَ سنة 866 بالمقرانة محل سلفه، ونشأ في كفالة أبيه فحفظ القرآن واشتغل قليلًا، ثم ملك اليمن بعد أبيه ولقِّب بالملك الظافر، فاختلف عليه بنو عامر فقهرهم وأذعنوا له، وملك اليمن الأسفل وتهامة ثم صنعاء وصعدة وغالبَ ما بينهما من الحصون. كان يحبُّ العلماء ويكرمُهم ويجمع الكتبَ, وكان على جانبٍ عظيم من الدين والتقوى والمشي في طاعة الله تعالى، لا تُعلَمُ له صبوة، وكان ملازمًا للطهارة والتلاوة والأذكار ولا يفتُرُ عن ذلك آناءَ الليل وأطراف النهار، وكان له من أعمال البِرِّ ما لا يُحصى، كبناء المساجد والمدارس وغيرها, ولم تزلْ الحربُ قائمة بينه وبين جماعةٍ من أئمة أهل البيت، فتارة له وتارة عليه. ولما خرج الجراكسة إلى اليمن غلبوه واستولوا على جميع ذخائره، وهي شيءٌ يفوق الحصرَ وأخرجوه من مدائنه وقتلوه قريب صنعاء, وكانت مدة ملكِه إلى انقضاء دولته تسعًا وعشرين سنة إلا أيامًا."},{"id":3621,"title":"بداية الامتيازات الأجنبية في البلاد الإسلامية  .","date":["العام الهجري :923","الشهر القمري : شعبان","العام الميلادي :1517"],"text":"قامت الدولة العثمانية في تاريخ العشرين من شهر شعبان من هذا العام بإبرام معاهدة تجارية مع البندقية مُنِح بموجبها قنصل البندقية في القسطنطينية الحقَّ في الفصل بأمور تركات رعيته وإرسال ترجمان لحضور المرافعات في القضايا التي يكون أفراد رعيته طرفًا فيها أمام القضاء العثماني، وامتدت هذه المعاهدة إلى مصر والشام بعد استيلاء العثمانيين عليهما، فكانت هذه المعاهدة أساس الامتيازات الأجنبية في البلاد الإسلامية!"},{"id":3622,"title":"انتشار النفوذ العثماني في الجزائر .","date":["العام الهجري :924","العام الميلادي :1518"],"text":"كانت الجزائر قد تعرَّضت لهجمات الإسبان الذين استطاعوا توطيد قدَمِهم في الجزائر، وبرز في تلك الفترة الأخوان عروج باشا وخير الدين بربروسا اللذين استطاعا أن يوقِفا المد الإسباني في البحر؛ حيث كانا بحَّارَين قويين، وكان السلطان العثماني قد منح عروج لقب أمير البحر العثماني، فأصبحت إنجازاته في ميزان الدولة العثمانية، واستطاع عروج أن يستعيد عدَّة مدن جزائرية، فدخلت بذلك الجزائر- أو بدأت تدخل- تحت النفوذِ العثماني بسبب هذين البحارين."},{"id":3623,"title":"الغزو الإسباني للجزائر .","date":["العام الهجري :924","العام الميلادي :1518"],"text":"كان الإسبان قد استولوا على تلمسان عام 915 فقام أمير البحر عروج بن يعقوب بمهاجمة تلمسان بقواته من البر والبحر، بمساعدة حاكمِها أبي حمو موسى الزياني الذي كان يتعاون مع الإسبان، فاستطاع الأمير عروج أن يستوليَ على تلمسان ويستخلصَها من أميرها المتعاوِن، وولى عليها أبو زيان أحمدَ الثاني، فاستنجد أبو حمو بالإسبان الذين كانوا يحتلون وهران، فقدموا بسرعة بقوة كبيرة توغَّلت داخل البلاد وشدَّدت الحصار على عروج بتلمسان واضطرته إلى مغادرتها، ثم لاحَقوا عروج واشتبكوا معه وهو في قلةٍ من رجاله فقاومهم حتى استُشهِد ودُعِيَ أخوه خير الدين حاكمًا على الجزائر."},{"id":3624,"title":"عودة السلطان العثماني سليم الأول إلى إستانبول .","date":["العام الهجري :924","الشهر القمري : رجب","العام الميلادي :1518"],"text":"عاد السلطان العثماني سليم الأول إلى إستانبول بعد حملته العسكرية التي استمرت سنتين وشهرين انتصر فيها على الصفويين ودخل عاصمتهم تبريز, وفتح مصر والشام والحجاز، وتعد هذه الحملة هي أطول حملة في التاريخ العثماني."},{"id":3625,"title":"وفاة القائد التركي عروج باشا .","date":["العام الهجري :924","الشهر القمري : شوال","العام الميلادي :1518"],"text":"هو القائد البحار التركي عروج باشا بن يعقوب بن يوسف، وهو أخو خير الدين بربروسا باشا, ويرجع أصلُ الأخوين المجاهدينِ إلى الأتراك المسلمين الذين استقرُّوا في جزيرة مدللي إحدى جزر الأرخبيل, وأمهم سيدة مسلمة أندلسية كان لها الأثر على أولادها في تحويل نشاطهم شطرَ بلاد الأندلس التي كانت تئن في ذلك الوقت من بطش الإسبان والبرتغال, وكان لعروج وخير الدين أخوان مجاهدان أيضًا هما إسحاق ومحمد إلياس. قُتل عروج باشا عن عمر يناهز الثمانية والأربعين عامًا على يد الإسبان وهو يدافع عن تلمسان؛ حيث قتلوه وفصلوا رأسه عن جسده وأرسلوه إلى إسبانيا. وعروج باشا أحد كبار القادة البحريين الأتراك الذين كان لهم الدور الأكبر في الحفاظ على الوجود الإسلامي في شمال إفريقيا ومقاومة الهجمات الصليبية على تلك السواحل."},{"id":3626,"title":"البرتغال يحاصرون جدة .","date":["العام الهجري :925","العام الميلادي :1519"],"text":"قام الأسطول البرتغالي بقيادة القائد سواريز بالرسو أمام جدَّة بعد أن اجتاز البحرَ الأحمر، وهذه محاولة منهم للوصولِ إلى مكة، وهم يريدون أن يهدِموا الكعبة ومِن ثمَّ يصِلون إلى المدينة، ويريدون أن ينبشوا القبر النبوي الشريف ليُساوموا به على القُدس، وهذا الأمر ليس بأوَّل مرة؛ فقد حاولوا قبل ذلك لكنَّهم فشلوا، وفي هذه الحملة تعرَّض الأسطول البرتغالي إلى عواصِفَ شديدة شتَّتت سفنه, ولما علم بهذا الحصار النائبُ العثماني على مصرَ خيري بك، قام بتوجيه أسطول بحري بقيادة سليمان الريس الرومي، فلما علم سواريز البرتغالي بقدومه انسحب من جدة إلى عدن، ومنها إلى الهند."},{"id":3627,"title":"إلحاق الجزائر بالدولة العثمانية .","date":["العام الهجري :925","العام الميلادي :1519"],"text":"بعد أن ترأَّس خير الدين بربروسا الذي خلف أخاه عروج بن يعقوب في حكم الجزائر، دعا رجال الدين والأعيان واقترح عليهم الالتحاقَ بالدولة العثمانية، فوافق الجميعُ على هذه الفكرة وصادقوا على كتاب تقرَّرَ إرساله إلى السلطانِ سليم الأول العثماني؛ لبسط حمايته على الجزائر، فتلقى السلطان العثماني الكتابَ، وولى خير الدين النيابةَ على الجزائر، وأرسل فرمانًا يقضي بذلك وأن الجزائر تحوَّلت إلى ولاية عثمانية."},{"id":3628,"title":"طرد الوجود الإسباني من الجزائر .","date":["العام الهجري :926","العام الميلادي :1519"],"text":"بعد أن دخلت الجزائر في النفوذ العثماني بجهاد البحَّارينِ عروج وأخيه خير الدين بربروسا، فقد استطاعا أن يوقِفا المدَّ الإسباني على المغرب، كما استطاعا أن يُلحِقا القسم الأكبر منه بالدولة العثمانية التي كانت بدورها تُعِين عروج بالسلاحِ والرجال, فاستطاع أن يستعيدَ جزيرة جربة سنة 916 وشرشل سنة 920 ومدينة الجزائر سنة 922, وإن احتفظ الإسبان بقلعة الجزائر، واستعاد كذلك تنسي وتلمسان، واستشهد عروج أثناء جهاده للإسبان في تلمسان سنة 924، ولكن بقي الأمرُ في طرد الوجود الإسباني من الجزائر متتابعًا بأخيه خير الدين بربروسا وغيرِه من المقاتلين."},{"id":3629,"title":"انتصار العثمانيين على البرتغاليين وطردهم من اليمن .","date":["العام الهجري :926","الشهر القمري : جمادى الآخرة","العام الميلادي :1520"],"text":"بعد قيام العثمانيين بالقضاء على الدولة المملوكية في مصر بدؤوا بالاستعداد لمنازلة البرتغاليين في البحار الشرقية بوجه عام، والبحر الأحمر بوجه خاص؛ ليتصدوا بذلك للمشاكل الاقتصادية والسياسية التي واجهوها بعد قيام البرتغاليين بتحويل طريقِ التجارة البحرية عبر البحرِ الأحمر والخليج العربي إلى رأس الرجاء الصالح من ناحية، ولمواجهة تحالف البرتغاليين مع الدولة الصفوية في إيران- التي كانت علاقتها عدائيَّة بالدولة العثمانية- من ناحية ثانية، ولصد الخطر البرتغالي الذي يهدد الأماكن المقدسة في الحجاز من ناحية ثالثة؛ حيث أصحبت مواجهة العثمانيين للبرتغاليين ضرورةً حتمية. فاتصل السلطان بدر أبو طويرق الكثيري سلطان حضرموت بالعثمانيين بعد أن أصبحوا أكبَرَ قوة إسلامية في ذلك الوقت معلنًا ولاءه للدولة العثمانية واستعدادَه للدخول في طاعتهم؛ بدافع الحصول على الأسلحة النارية وعلى الدعم العسكري منهم؛ لصد الهجمات البرتغالية على اليمن وقهْر خصومه المحليين الذين ينازعونه السلطة والنفوذ في حضرموت، وقد تمكن من تحقيق ذلك بالفعل؛ ففي شهر جمادى الآخرة من هذه السنة وصلت إلى مدينة الشحر بساحل حضرموت فرقةٌ من الجنود العثمانيين بقيادة ضابط كبير يسمى رجب، نجحت في ردع غزو البرتغاليين لليمن, وكان وصول القوات التركية تتويجًا للاتصالات التي أجراها السلطان بدر أبو طويرق مع الضباط العثمانيين خلال مرورهم بالقرب من ساحل مدينة الشحر في أثناء فترة وجودهم ضمن قوة المماليك الموجودة في منطقة زبيد باليمن، والتي أعلنت اعترافها بالسيادة العثمانية بعد سقوط دولة المماليك في مصر."},{"id":3630,"title":"وفاة السلطان العثماني سليم الأول ياوز وتولي ابنه سليمان الخلافة .","date":["العام الهجري :926","الشهر القمري : شوال","العام الميلادي :1520"],"text":"هو السلطان سليم الأول بن بايزيد الثاني بن محمد الفاتح الغازي الملقب بياوز، أي: القاطع, وهو تاسع سلاطين الدولة العثمانية، وأول من تلقَّب بأمير المؤمنين من سلاطين بني عثمان. تولى سلطنة الدولة العثمانية سنة 918 بعد نزاع مع والده بايزيد، انتهى النزاع بتنازل والده له بالحكم بدعم من الانكشارية, وقد أظهر سليم منذ بداية حكمه ميلًا إلى تصفية خصومه ولو كانوا من إخوته أو أبنائهم, فبعد توليه السلطة عيَّنَ ابنه سليمان حاكمًا للقسطنطينية، وسافر بجيوشه إلى بلاد آسيا لمحاربة إخوته وأولادهم، فاقتفى أثر أخيه أحمد إلى أنقرة ولم يتمكن من القبض عليه؛ لوجود علاقات بينه وبين الوزير مصطفى باشا الذي كان يخبره بمقاصد السلطان, ولما علم السلطان بهذه الخيانة قتَلَ الوزير شَرَّ قِتلة جزاءً له وعبرة لغيره، ثم توجه بكل سرعة إلى صاروخان مقر أخيه كركود فقبض عليه ثم قتله، أما أحمد الذي كان يتلقى دعمًا من إسماعيل شاه الصفوي فقتله بالقرب من مدينة يكى شهر, ولما اطمأنَّ خاطره من جهة داخليته عاد إلى مدينة أدرنه؛ حيث كان بانتظار سفراء من قبِلَ البندقية والمجر وموسكو وسلطنة مصر، فأبرم معهم جميعًا هدنة لمدد طويلة, وفي عهده تغيرت وِجهة الدولة العثمانية الجهادية من أوروبا إلى البلاد العربية الإسلامية؛ وذلك لحمايتها من الخطرين الصفوي والبرتغالي، والمحافظة على تماسك وحدتها خاصة بعد ضعف الدولة المملوكية وشدة الضربات الإسبانية والبرتغالية في عدد من البلدان الإسلامية في المغرب والخليج العربي إلى الهند, فاتجه سليم لبلاد الفرس لمحاربة الصفويين الشيعة، وانتصر عليهم في معركة جالديران، ثم اتجه إلى المماليك في الشام ومصر، وقضى على دولتهم بعد الانتصار عليهم في معركتي مرج دابق والريدانية، وبهذه الانتصارات ضمَّ سليم معظم البلاد العربية لدولته بما فيها بلاد الحرمين، كما نقل الخلافة الإسلامية إلى دولته وتسمى بأمير المؤمنين وخادم الحرمين الشريفين، وهو أول من تسمى بهذا الاسم من حكام المسلمين، وذلك بعد أن بايعه أشراف مكة، ثم تنازل الخليفة العباسي محمد المتوكل على الله آخر ذرية الدولة العباسية عن حقه في الخلافة الإسلامية إلى السلطان سليم العثماني وسلمه الآثار النبوية الشريفة، وهي البيرق والسيف والبردة، وسلمه أيضًا مفاتيح الحرمين الشريفين، ومن ذلك التاريخ صار كل سلطان عثماني أميرًا للمؤمنين وخليفة لرسول رب العالمين اسمًا وفعلًا, ثم بعد ذلك عَمِل على ضم اليمن لحمايتها من البرتغاليين وبسط نفوذ الدولة على بلاد المغرب وشمال إفريقيا لحمايتها من الخطر الإسباني. في التاسع من شوال ليلة السبت توفي السلطان سليم فأخفى موته الوزراءُ، وأرسلوا يُعلِمون ولده السلطان سليمان المعروف بسليمان القانوني، فلما وصل إلى القسطنطينية أعلنوا موت السلطان سليم، بمجرد وصول القسطنطينية يوم 16 شوال كان في انتظاره على إفريز السراي جنود الانكشارية فقابلوه بالتهليل وطلب الهدايا المعتاد توزيعها عليهم عند تولية كل ملك، وفي صبيحة 17 شوال جرت رسوم المقابلات السلطانية فوفد الأمراء والوزراء والأعيان يعزون السلطان بموت والده ويهنؤونه بالخلافة في آن واحد، وعند الظهر وصلت جثة والده فسار في الجنازة وصلوا عليه في جامع السلطان محمد، ثم حملوه ودفنوه في محل قبره، وأمر السلطان سليمان خان ببناء جامع عظيم، وعمارة لطعام الفقراء صدقة على والده، توفي وله من العمر أربع وخمسون سنة، وكانت مدة ملكه تسعة أعوام وثمانية أشهر."},{"id":3631,"title":"جان بردي الغزالي والي الشام يعلن تمرده على الدولة العثمانية .","date":["العام الهجري :926","الشهر القمري : ذي القعدة","العام الميلادي :1520"],"text":"ما إن علم الوالي جان بردي الغزالي والي الشام للعثمانيين بموت الخليفة سليم الأول أعلن عصيانه وتمرده، واتصل بخيري بك والي مصر ليكون نصيره، فراوغه خيري ووعده، وفي الوقت نفسه أطلع الخليفة سليمان القانوني على هذه المراسلات، وأعلن جان بردي نفسه سلطانًا على الشام وأمر بالدعاء له في خطب الجمعة، ونقش اسمه على النقود وتلقب بالملك الأشرف، وقضى على حامية دمشق العثمانية، وطرد العثمانيين من بيروت وطرابلس وحماة وغيرها من المدن، ثم سار جان بردي ليأخذ حلب أيضًا وخاصة أنها لم تعترف بسلطانه وألقى الحصار عليها، ثم وهو في حصاره وصلت إليه الجيوش العثمانية فترك الحصار، وأسرع إلى دمشق ونشبت بينه وبين القوات العثمانية حرب في برزة من أعمال دمشق في السابع عشر من شهر صفر من عام 927 انهزم فيها جان بردي وهرب ليتحصن بقلعة دمشق، فلحقته الجيوش العثمانية وحاصرته بها وفر متنكرًا ولكن أخذه بعض أعوانه وسلَّمه إلى فرحات باشا قائد الجيوش العثمانية فقتله وأرسل رأسه إلى الخليفة سليمان، وقد حاول جان بردي بهذه الحركة إحياء الدولة المملوكية مرة أخرى في بلاد الشام بعد قضاء العثمانيين عليها. وبعد قمع حركة جان بردي الغزالي قُسمت الشام إلى ثلاث ولايات وهي حلب ودمشق وطرابلس."},{"id":3632,"title":"اضطهاد الأسبان للموريسكيين المسلمين وترحيلهم إلى مراكش .","date":["العام الهجري :927","العام الميلادي :1520"],"text":"لم تنجح محاكم التفتيش التي أقامها الصليبيون الإسبان ولا الأساليب التي اتبعوها في إجبار المسلمين على ترك دينهم كما تريد الكنيسة التي أدركت مدى عمق الإيمان بالعقيدة الإسلامية في نفوس الموريسكيين، فقررت إخراجهم من إسبانيا، فأصدر مجلس الدولة بالإجماع في (30/1/1608م) قرارًا بطرد جميع الموريسكيين من إسبانيا، ولم يحُلَّ شهر أكتوبر عام (1609م) حتى عمَّت موانئَ المملكة وبلنسية من لقنت جنوبًا إلى بني عروس شمالًا حركةٌ كبيرة، فرحل بين (9/1606م) إلى (1/1610م) نحو 120 ألف مسلم من موانئ لقنت ودانية والجابية ورصافة وبلنسية وبني عروس وغيرها, وفي (5/1611م) صدر قرار إجرامي للقضاء على المتخلِّفين من المسلمين في بلنسية، يقضي بإعطاء جائزة ستين ليرة لكل من يأتي بمسلم حي، وله الحق في استعباده، وثلاثين ليرة لمن يأتي برأس مسلم مقتول، وقد بلغ عدد من طُرِد من إسبانيا في الحقبة بين سنتي (1609 و1614م) نحو 327 ألف شخص، مات منهم 65 ألف غرقًا في البحر، أو قُتلوا في الطرقات، أو ضحية المرض والجوع والفاقة، وقد استطاع 32 ألف شخص من المطرودين العودة إلى ديارهم في الأندلس، بينما بقي بعضهم متسترًا في بلاده بعد الطرد العام لهم، وقد استمرَّ الوجود الإسلامي بشكل سري ومحدود في الأندلس في القرنين السابع عشر والثامن عشر. وهكذا حكمت محاكم التفتيش في غرناطة سنة (1726م) على ما لا يقل عن 1800 شخص، بتهمة اتباع الدين الإسلامي، وفي (9/5/1728م) احتفلت غرناطة بأوتوداف ضخم؛ حيث حكمت محاكم التفتيش على 64 غرناطيًّا بتهمة الانتماء للإسلام، وفي (10/10/1728م) حكمت محكمة غرناطة مرة أخرى على ثمانية وعشرين شخصًا بتهمة الانتماء إلى الإسلام، وتابعت محاكم غرناطة القبض على المتهمين بالإسلام إلى أن طلبت بلدية المدينة من الملك سنة (1729م) طرد كل الموريسكيين حتى تبقى المملكة نقية من الدم الفاسد."},{"id":3633,"title":"حدوث غلاء وجوع كبير ببلاد المغرب .","date":["العام الهجري :927","العام الميلادي :1520"],"text":"وقع الغلاء والجوع الكبير الذي صار تاريخًا في الناس مدة، وحدث هذا بعد عام من انحباس المطر واضطرار الناس إلى استخراج السواقي من الأودية والأنهار لسقي زرعهم وثمارهم."},{"id":3634,"title":"استيلاء العثمانيين على بلغراد .","date":["العام الهجري :927","الشهر القمري : رمضان","العام الميلادي :1521"],"text":"بعد أن اعتلى السلطان سليمان القانوني عرش الخلافة العثمانية أرسل رسولا إلى ملك المجر يُعلِمه بأنه أصبح الخليفة ويطالبه بدفع الجزية، فقام ملك المجر بقتل الرسول، فجهَّز سليمان جيشًا وسار على رأسه لقتال المجر، ودخل مدينة بلغراد بعد أن حاصرها قليلًا وغادرها الجنود المجريون، ثم صلى السلطان سليمان الجمعة في أحد كنائسها بعد أن حولها إلى مسجد جامع."},{"id":3635,"title":"انتشار وباء بالمغرب .","date":["العام الهجري :928","العام الميلادي :1521"],"text":"انتشار وباء بالمغرب، وكان وقوعه بعد ما حدث من غلاء وجوع في العام الذي قبله."},{"id":3636,"title":"سيطرة البرتغاليين والإسبان على جزر إندونيسيا .","date":["العام الهجري :928","العام الميلادي :1521"],"text":"استطاع البرتغاليون احتلال مالاقا سنة 917, واتخذوها قاعدةً لشن حملاتهم على الجزر الإندونيسية، وخاصة جزر الملوك، وهي الجزر التي يعرفونها بجرز التوابل، وتمكنوا من السيطرة على شمالي سومطرة هذه السنة, ووصلوا إلى جزيرة سيلبيس سنة 947، وقد قامت الثورات ضدَّهم لتعصبهم الصليبي الذي كان واضحًا لا خفاء فيه، وقد زادت هذه الحركات بعد أن قُتل غدرًا سلطان جزيرة ترنات ويدعى هارون، أما الإسبان فقد وصلوا إلى جزيرة بورنيو وإلى جزيرة الملوك هذه السنة في طريق عودتهم بعد مقتل قائدهم الرحالة ماجلان في جزر الفلبين، وكان سبب قتله هو إظهار صليبيته علنًا؛ حيث أراد أن يفرض على السكان التنصر، ولم تستطع إسبانيا أن تثبت قدمها إلا في جزر الملوك."},{"id":3637,"title":"استرداد هرمز بعد طرد البرتغاليين منها .","date":["العام الهجري :928","الشهر القمري : ذي الحجة","العام الميلادي :1522"],"text":"بعد أن توفِّي السفاح البرتغالي بوكيرك شرع سكان الخليج العربي لتحريك ثورة تحت قيادة هرمز على الحكم البرتغالي، بحيث امتدت الثورة إلى جميع القواعد والحصون البرتغالية في منطقة الخليج العربي، فقام في تشرين الثاني من عام 1521م رئيس التجَّار بمهاجمة السفينتين الموجودتين في ميناء هرمز، وأشعل النار فيهما وهاجم السكانَ البرتغاليين وحاصروهم في القلعة، ونجحت الثورة نجاحًا جيدًا، ثم قام البرتغاليون بنقل التعزيزاتِ العسكرية إلى جزيرة هرمز مركز الثورة، وقضوا على الثورة بعد أعمالٍ وحشيَّة ونكَّلوا بالأهالي، ثم عاد العربُ إلى الثورة ثانيةً بعد خمسة أعوام وشاركهم حكَّامُ مسقط وقلهات. فأرسل البرتغال حملة عسكرية مؤلَّفة من خمس سفن برتغالية شنَّت هجومًا على ظفار، واستمرت كذلك حتى قضت على الثورة، ثم عادت البحرين للثورة في عام 1529م وفشل البرتغاليون في قمعِها، فقلَّت هيبتهم فثارت القطيفُ عام 1550م, واستمَرَّ الأمر على مثل هذه الثورات بين حينٍ وآخر حتى استطاعوا في النهاية القضاءَ على الوجود البرتغالي في الخليج العربي، وخاصة أنَّ العمانيين واصلوا استعداداتِهم لطرد لبرتغاليين من بلادهم وبخاصةٍ بعد خروج هرمز من يد البرتغال، وتنامت قوةُ العرب العمانيين من أسرة اليعاربة التي استطاعت حسم الصراع لصالحهم سنة 1069."},{"id":3638,"title":"فتح العثمانيين رودس وانتزاعها من فرسان القديس يوحنا .","date":["العام الهجري :929","الشهر القمري : صفر","العام الميلادي :1523"],"text":"كانت جزيرة رودس جزيرة مشاكِسة؛ إذ كانت حصنًا حصينًا لفرسان القديس يوحنا الذين كانوا يقطعون طريق الحجَّاج المسلمين الأتراك إلى الحجاز، فضلًا عن أعمالهم العدوانية الموجهة لخطوط المواصلات البحرية العثمانية، فاهتمَّ السلطان سليمان القانوني بفتحها، وأعدَّ حملة عظيمة ساعده على تحقيقِها عدةُ أمور: انشغال أوروبا بالحرب الكبرى بين شارل الخامس (كنت) إمبراطور الدولة الرومانية المقدسة وفرانسوا ملك فرنسا، وعقْد الصلح بين الدولة العثمانية والبندقية، وكذلك نموُّ البحرية العثمانية على عهد سليم الأول، فشَنَّ القانوني حربًا كبيرة ضِدَّ رودس ابتداءً من اليوم الثاني من شهر صفر من هذا العام وفتَحَها وأعطى للفرسان حقَّ الانتقال منها، فذهبوا إلى (مالطة) وهناك أعطاهم شارل كنت حَقَّ حكم هذه الجزيرة."},{"id":3639,"title":"زحف إسباني صليبي على الفلبين للقضاء على الإسلام فيها .","date":["العام الهجري :929","الشهر القمري : ربيع الآخر","العام الميلادي :1523"],"text":"الفلبين هي عبارة عن مجموعة كبيرة من الجزر تمتدُّ في المحيط الهادي ما بين الأرخبيل الإندونيسي وأرخبيل اليابان، وقد دخلها الإسلام قديمًا، ولكن في ربيع ثاني من هذه السنة فوجئ السكان بسفن إسبانية عسكرية بقيادة ماجلان احتلُّوا الجزر وأخذوا في القتل والنهب، ثم أراد ماجلان أن ينصِّرَ السكان المسلمين قسرًا، فكان هذا سببًا في مصرعه؛ حيث ثار عليه مجموعة من السكان الذين استاؤوا من طريقة تنصيره وإجباره الناسَ على ذلك، فقاموا باغتياله، فأرسلت إسبانيا أربع حملات انتقامية قامت بأعمال قتل جماعي لجميع المسلمين في جزر الفلبين الذين أبَوا أن يتنصَّروا!"},{"id":3640,"title":"وفاة إسماعيل شاه مؤسس الدولة الصفوية وتولي ابنه طهماسب .","date":["العام الهجري :930","العام الميلادي :1523"],"text":"هو أبو المظفر إسماعيل شاه بن حيدر بن جنيد بن إبراهيم بن خواجة علي بن صدر الدين موسى بن الشيخ صفي الدين إسحاق بن جبريل الأردبيلي، المشهور بإسماعيل شاه الصفوي، وجدُّه إبراهيم هو شيخ الطريقة الصفوية التي أسَّسها أصلًا صفي الدين إسحاق, وقيل: إن أول من تشيَّع فيهم صفيُّ الدين أو ابنه موسى صدر الدين. ولد إسماعيل بأردبيل سنة 892هـ وأمه بنت الحسن الطويل، وكانت أمها كاترينا ابنة كارلو يوحنا ملك مملكة طرابزون اليونانية النصرانية، ولما قُتِل أبوه الشيخ حيدر في المعركة أُسِرَ إسماعيل مع إخوته وهو طفل وحُبس في قلعة إصطخر إلى أن توفِّيَ خاله السلطان يعقوب بن أوزن حسن الطويل سنة 892 وتفرقت الكلمة بين أولاده، فهرب أولاد الشيخ حيدر إلى لاهجان ودخل إسماعيل في بيت صائغ يقال له نجم زركر، وبها كثيرٌ من الروافض، فتعلم منهم إسماعيل في صغره مذهب الرفض، ثم كثُرَ أتباعه فخرج من لاهجان بأنه يريد أخْذ ثأر والده في أواخر سنة 905هـ، فغلب شروان شاه الذي قُتِل في المعركة وهرب ولدُه شيخ شاه إلى كيلان, وكان ذلك أول فتوحات إسماعيل الصفوي، ثم قاتل الأمير الوزير المستولي على أذربيجان بنخجوان، فهزمه أيضًا واستولى على خزائنه، وسار إلى تبريز فدخلها سنة 907هـ وبويع له بالسلطنة، فأظهر مذهب الإلحاد والرَّفض، وغيَّرَ اعتقاد أهل العجم, وخطب الخطباء باسمه على مذهب الإمامية، ثم هَزَمَ مراد بك ابن السلطان يعقوب بن أوزن حسن الطويل وأخذ خزائنه، ثم صار لا يتوجَّه إلى بلاد إلا يفتحُها ويقتل جميعَ من فيها وينهبُ أموالهم، إلى أن ملك أذربيجان وعراق العرب والعجم وخراسان، وكاد أن يدَّعي الرُّبوبية وكان يسجد له عسكرُه! وقتل خلقًا لا يحصَون بحيث لم يُبقِ أحدًا من علماء أهل السُنَّة، وأحرق جميع كتبِهم ومصاحِفِهم، وأخرج عظامَهم من القبور وأحرقَها، إلى أن كسره السلطانُ العثماني سليم الأول سنة 920هـ في معركة جالديران, وكانت مدة ملكه أربعًا وعشرين سنة، وكان سفَّاكًا غدَّارًا، ينظم بالتركي والفارسي نظمًا وسطًا. قال علي دده بن مصطفى الموستاري، المتوفى سنة 1007 في (محاضرة الأوائل ومسامرة الأواخر): \"أولُ من تجبَّر وطغى، ورفضَ أحكام الشريعة وغوى، وخان الملَّة الإسلامية خيانةً لم يُسمَع بمثلها من الفراعنة، وقهر ملوك العراقينِ، وأبطل الخطبةَ من الجوامع كلِّها: الملك الشقيُّ الغَويُّ الشهير إسماعيل بن حيدر بن جنيد بن إبراهيم بن الشيخ خواجة علي بن صدر الدين ابن الشيخ الصفي الأردبيلي، قطَعَ الله أعراقَهم من العِراق وجميع ممالك الآفاق مع أشياعهم الشِّيعة النَّجِسة المنجوسة المجوسيَّة الدَّهرية، بل إنَّهم أخبثُ الفِرَق الضَّالَّة المضلَّة، أهلك الله أسرارَهم، ومحا من وجهِ الأرض آثارَهم بسيوف الملوك العثمانية السُّنِّية المؤيَّدة بالقوة القدسيَّة، لا زالت سيوفُهم مسلولةً عليهم وعلى أمثالهم من أعداء الدين\" هلك إسماعيل شاه عن 78 عامًا وخلفه ابنه طهماسب وهو في العاشرة من العمر."},{"id":3641,"title":"أبو العباس أحمد السعدي يمتلك مدينة مراكش .","date":["العام الهجري :930","العام الميلادي :1523"],"text":"لما توفِّيَ أبو عبد الله محمد السعدي حاكِمُ المغرب اجتمع الناسُ على بيعة ابنه ووليِّ عهده السلطان أبي العباس الأعرج من سائر الآفاق، وآتوه طاعتهم عن رضًا منهم، فاستقام أمره وصرف عزمه إلى تمهيد البلاد واقتناء الأجناد، وتعبئة الجيوش إلى الثغور وشن الغارات على العدو في الآصال والبكور، في أحواز تيلمست وآسفي وغيرهما. وكان النصارى قد خيَّموا بشاطئ البحر وعاثُوا في تلك السواحل فأجلاهم عنها وطهَّر تلك البقاع من رِجسِهم، وأراح أهلَها مِن شؤمهم ونحسِهم، وهنا بَعُدَ صيتُه وانتشر في البلاد ذِكرُه، وهُرِع الناسُ إليه من كل جانب، ودخلت في طاعته سائرُ البلاد السوسية، فعند ذلك كاتَبه أمراء هنتاتة ملوك مراكش يخطبون أمرَه ويرومون الدخولَ في طاعته، فأجاب داعيَهم، وانتقل إلى مراكش فدخلها واستولى عليها."},{"id":3642,"title":"أحمد باشا والي مصر يعلن استقلاله عن الخلافة العثمانية .","date":["العام الهجري :930","العام الميلادي :1523"],"text":"طمع أحمد باشا في منصب الصدر الأعظم ولم يفلحْ في تحقيق هدفه، وطلب من السلطانِ أن يعيِّنَه واليًا على مصر فعَيَّنه، وما إن وصل إلى مصر حتى حاول استمالةَ الناس وأعلن نفسه سلطانًا مستقلًّا؛ حيث جمع حولَه بعض مماليك الشراكسة وشيوخ العربان، وأعاد تنصيبَ المتوكل على الله الخليفة العباسي المتنازل عن الخلافة للعثمانيين، وسرَّح الجيش الانكشاري عنده، ونظَّم جيشًا جديدًا من المماليك وحاول كذلك أن يوطِّدَ علاقات مع فرسان القديس يوحنا ومع الشاه الصفوي إسماعيل شاه، ولكِنَّ الخليفة العثماني سليمان القانوني أرسل له حملةً إلى مصر بقيادة إبراهيم باشا، وكان أحمد باشا الوالي قد هرب من أميرين كان أمر بسجنهما، فهرب إلى ابن قرفة شيخ العرب، ولكنهما لاحقاه حتى قبضا عليه، وقتله إبراهيم باشا وقمع هذا العصيان الذي لم يدُمْ طويلا، وتولى ولايةَ مصر إبراهيم باشا."},{"id":3643,"title":"وفاة المؤرخ ابن إياس زين الدين المصري .","date":["العام الهجري :930","العام الميلادي :1523"],"text":"هو زين الدين أبو البركات محمد بن أحمد بن إياس المصري الحنفي، شركسي الأصل، وُلِد في القاهرة سنة 852 وكان جده ووالده من أمراء المماليك، ومع ذلك لم يتصِلْ بالبلاط المملوكي، بل انصرف للتأليف، وهو من تلاميذِ جلال الدين السيوطي، كتب تاريخًا لمصر وصل فيه إلى سنة 928، اشتهر بحياده في التأليف، وبتحرِّيه الدقةَ فيما يكتب، وفيما يصدر من أحكامٍ على معاصريه من السلاطين والأمراء, وكان يقِفُ عند كل حادثة بالشرح والتعقيب، مع شيء من القوة في الحكم والجرأة في التقدير، كما كان له اهتمام بالجغرافيا، فله كتاب نشق الأزهار في عجائب الأقطار، وله في التاريخ عقود الجمان في وقائع الأزمان، وله نزهة الأمم في العجائب والحِكَم، وله بدائع الزهور في وقائع الدهور."},{"id":3644,"title":"وفاة شيخ الإسلام القاضي شهاب الدين أحمد المزجد .","date":["العام الهجري :930","الشهر القمري : ربيع الآخر","العام الميلادي :1524"],"text":"هو شيخ الإسلام العلامة ذو التصانيف المفيدة والفتاوى السديدة، قاضي قضاة المسلمين شهاب الدين أبو السرور أحمد بن عمر بن محمد بن عبد الرحمن بن القاضي يوسف بن محمد بن علي بن محمد بن حسان بن الملك سيف بن ذي يزن المذحجي السيفي المرادي الشهير بالمُزَجد الشافعي الزبيدي، وكان من العلماء المشهورين وبقية الفقهاء، واحد المحقِّقين المعتمدين المرجوع إليهم في النوازل المعضلة والحوادث المشكلة، وكان على الغاية من التمكن في مراتب العلوم الإسلامية من الأصول والفروع وعلوم الأدب، وهو الذي أفتى بجواز شرب البنِّ والقهوة، وقد كان الخلاف بجواز شربها منتشرًا في عدد من الأمصار. ولد المُزَجد سنة 847 بجهة قرية الزبيدية، ونشأ بها وحفظ جامع المختصرات، ثم انتقل إلى بيت الفقيه بن عجيل فأخذ فيها على شيخ الإسلام إبراهيم بن أبي القاسم جغمان, ثم ارتحل إلى زبيد واشتغل فيها على عدد من أهل العلم، فحصَّل الفقه والأصول والحديث والحساب والفرائض, وبرع في علوم كثيرة لكنَّه تميز في الفقه حتى كان فيه أوحدَ وقته، ومن مصنفاته المشهورة في الفقه: العباب والمحيط بمعظم نصوص الشافعي والأصحاب، وهو كاسمه, وهو على أسلوب الرَّوْض جمع في مسائل الروض ومسائل التجريد، وهو كتاب عظيم جامع لأكثر أقوال الإمام الشافعي وأصحابه وأبحاث المتأخرين منهم على الغاية من جزالة اللفظ وحسن التقسيم، ولقد اشتهر هذا الكتاب في الآفاق ووقع على حسنِه ونفاسته الإجماع والاتفاق، وكثر اعتناءُ الناس بشأنه وانتفاع الطلبة به واغتباطهم ببيانه، واعتناء غير واحد من علماء الإسلام بشرحه، كالعارف شيخ الإسلام أبي الحسن البكري؛ فإنه شرحه بشرحين: صغير وكبير, ومنها تجريدُ الزوائد وتقريب الفرائد في مجلدين، جمع فيه الفروع الزائدة على الروضة غالبًا، وكتاب تحفة الطلاب ومنظومة الإرشاد في خمسة آلاف وثمانمائة وأربعين بيتًا, وزاد على الإرشاد كثيرًا من المسائل والقيود، ونظم أوائله إلى الرهن في مدة طويلة ثم مكث نحو خمس عشرة سنة، ثم شرع في تتمته فكمله في أقل من سنة، وله غير ذلك، وتفقه به خلائق كثيرون من أكابر الأعيان واختلاف أجناس الطلبة من جهات شتى، وله شِعرٌ حَسن، ومنه في الحصن الحصين، وكان ينظِم في اليوم الواحد نحو ثمانين بيتًا مع القيود والاحترازات، وله مرثية عظيمة في شيخه عمر الفتى. قال حفيدُه شيخ الإسلام قاضي قضاة الأنام أبو الفتح بن حسين المزجد: كان جدي شرَحَ جامع المختصرات للنسائي في ست مجلدات، ثم لما رآه لم يستوفِ ما حواه الجامع المذكور من الجَمع والخلاف، ألقاه في الماء فأعدمه، والله المستعان. قال علامة العصر ومفتيه أحمد بن عبد الرحمن الناشري: \"كان القاضي شهاب الدين المزجد إذا سئم من القراءة والمطالعة، استدعى بمقامات الحريري، فيطالع فيها ويسمِّيها طبق الحلوى\" ووليَ قضاء عدن ثم قضاء زبيد، وباشر ذلك بعفَّة وديانة، وطالت مدته فيها. وحكي: \"أنه لما جاء زبيد وأُتيَ إليه بمعلومها، قال: جئنا من عدن إلى عدم. وكأنه- والله أعلم- كان غير راض بهذه المرتبة لِما فيها من الخطر العظيم؛ وذلك لكمال ورعه واحتياطه في دينه واستحقاره لزهرة الدنيا ومنصبها، وكان على جانب عظيم من الدين، حتى قال بعضهم في عصره: لو جاز أن يبعث الله نبيًّا في عصرنا، لكان أحمد المزجد هو ذلك النبي!\" قال النماري: \"لما دخلت عليه وشرعتُ في قراءة العباب لديه، أخذتني من دهشته الهيبةُ والعظمة ما منعني استيفاءَ ما كنت آلَفُه من الانبساط في حال القراءة، ففهم ذلك مني وأخذ يباسطني بذكرِ بلدي وأنَّ منها الشاعر الفلاني الذي قال في قصيدته ما هو كيت وكيت، حتى زال عني ذلك الدَّهشُ وثابَتْ إليَّ نفسي, وكانت أوقات شيخنا مرتبة: يجعل أواخر الليل وأول النهار لدرس القرآن، ثم يشتغل بما له من أوراد، ثم بالتفسير، ثم بالفقه، ثم يخرج إلى الحُكم إلى وقت الظهر، ثم يَقيل، ثم يشتغل بالإحياء للغزالي ونحوه من كتب الرقائق، وفي آخر النهار ينظر في التاريخ إلى أن يخرج لمجلس الحُكم بعد صلاة العصر؛ لأنه كان يجلس للحكم في اليوم مرتين\" وقد انتفع به الناس، وأخذ عنه الطلبة واستمر على عظمته ووجاهته حتى مات في دولة الأروام- جمع رومي- قال محي الدين العيدروس: \"ومناقب المزجد كثيرة وترجمته طويلة، وقد أفردها بالتصنيف حفيدُه القاضي أبو الفتح بن الحسين المزجد في جزء لطيف سمَّاه: منية الأحباب في مناقب صاحب العباب، وإذا تأملتَ ما أسلفناه عنه من الأخبار الجميلة والسِّيَر الحميدة، علمتَ أنَّه من العلماء الأخيار الأبرار، ولا ينافي ذلك ما كان متلبسًا به من القضاء ونحوه؛ فقد ابتلى بمثل ذلك غيرُ واحد من العلماء الصلحاء، كشيخ الإسلام تقي الدين السبكي، وشيخ الإسلام زكريا الأنصاري\" كان لشهاب الدين المزجد أربعة أولاد: علي، والحسن، والحسين، وعبد الرحمن، وكل منهم أفتى في حياة أبيه، ومات منهم اثنان في حياة أبيهما، وهما عبد الرحمن وحسن، ورثاهما وحزن عليهما. توفي شهاب الدين فجر يوم الأحد شهر ربيع الآخر من هذه السنة ببلدة زبيد، وصُلِّي عليه بجامعها الكبير ودُفن بباب سهام، وقبره قبلي تربة الشيخ علي أفلح، ولم يخلف بعده مثله- رحمه الله تعالى ونفعنا بسره وسر علومه- ورثاه جماعة من أكابر العلماء والأدباء من تلامذته ومعاصريه، وعظُمَ الأسفُ عليه."},{"id":3645,"title":"وفاة السلطان محمد الوطاسي وتولي أخيه ثم خلعه .","date":["العام الهجري :931","العام الميلادي :1524"],"text":"هو السلطان أبو عبد الله محمد بن محمد شيخ الوطاسي المعروف بالبرتغالي، صاحب المغرب، وقع في الأسر عند البرتغاليين مدةً من الزمن وهو صغير السن؛ ولذلك لقِّب بالبرتغالي, تولى السلطنة بعد والده محمد شيخ، وقد انشغل بجهاد البرتغاليين, وبعد وفاته تولى أخوه أبو الحسن علي بن محمد الثاني الملقب أبو حسون، فقام أبو العباس أحمد بن أبي عبد الله محمد بخلع عمه أبي حسون."},{"id":3646,"title":"إجراء عين حنين إلى مكة وعين نعمان إلى عرفات .","date":["العام الهجري :931","العام الميلادي :1524"],"text":"كانت الأوامر السلطانية السليمانية قد صدرت بإصلاح عين حنين وعين نعمان- التي أجرتهما زبيدة بنت جعفر بن المنصور زوجة الرشيد، وعَمَرها بعدها الملوك والسلاطين- وعُين لذلك ناظرٌ اسمه مصلح الدين مصطفى من المجاورين بمكة، فبذل جهدَه في عمارتهما، فجَرَت عين حنين إلى مكة، وعين نعمان إلى عرفات."},{"id":3647,"title":"تنصير الموريسكيين المسلمين الإسبان .","date":["العام الهجري :931","الشهر القمري : جمادى الأولى","العام الميلادي :1525"],"text":"أمر الإمبراطور شارل الخامس بتنصير الموريسكيين المسلمين الأسبان، وعهد لمحاكم التفتيش بتنفيذ ذلك الأمر."},{"id":3648,"title":"وفاة الأمير أبي عبد الله محمد الحفصي وقيام ابنه الأصغر وقتاله .","date":["العام الهجري :932","العام الميلادي :1525"],"text":"هو الأمير المتوكل أبو عبد الله محمد الخامس بن الحسن الحفصي صاحب تونس، ومن الأعمال التي تنسب إليه المكتبة العبدلية التي أسسها بجامع الزيتونة, وبعد وفاته قام بالأمر بعده ابنه الحسن بن محمد خلفًا له مع وجود الابن الأكبر رشيد، فلجأ رشيد إلى خير الدين بربروسا حاكم الجزائر وطلب مساعدته لاسترداد تونس من أخيه المتغلب عليها، فاستأذن خير الدين السلطان العثماني سليمان، فأذن له وأمده بقوة من الجند، فاستعدَّ لامتلاكها واستطاع استعادتها في سنة 937."},{"id":3649,"title":"تمرد شيعي رافضي على الدولة العثمانية .","date":["العام الهجري :932","العام الميلادي :1525"],"text":"بدعم من الدولة الصفوية قاد تمرد شيعي رافضي رجلٌ يقال له بابا ذو النون في منطقة يوزغاد؛ حيث جمع هذا البابا ما بين ثلاثة آلاف وأربعة آلاف ثائر من مريديه، وفرض الخراجَ على المنطقة، وقَوِيت حركته حتى إنه استطاع هزيمة بعض القُواد العثمانيين الذين توجَّهوا لقمع حركته، ثم أرسل له السلطان سليمان القانوني حملةً عسكرية قضت عليه وقتلته، وأُرسِلَ رأسُه إلى إستانبول، ثم ظهر رجلٌ آخر يقال له قلندر جلبي في منطقتي قونية ومرعش، وكان عدد أتباعه ثلاثين ألف شيعي قاموا بقتل المسلمين السُّنَّة في هاتين المنطقتين، ويقول بعض المؤرخين إن قلندر جلبي جعل شعارَه أن من قتل مسلمًا سنِّيًّا واعتدى على امرأة سُنية يكون بهذا قد حاز أكبر الثواب، فتوجه بهرام باشا لقمع هذا العصيان، فقتله العصاة، ثم نجحت الحيلة معهم؛ إذ إن الصدر الأعظم إبراهيم باشا قد استمال بعض رجال قلندر جلبي، فقَلَّت قواته وهُزم وقُتِل بأيدي أهل السنة الذين أنهوا تمرُّده."},{"id":3650,"title":"وفاة السلطان الأعظم مظفر شاه صاحب كجرات .","date":["العام الهجري :932","العام الميلادي :1525"],"text":"هو السلطان الأعظم مظفر شاه بن محمود شاه، صاحب كجرات، كان عادلًا فاضلًا محبًّا لأهل العلم معروفًا بعنايته بالعلم وتورُّعِه عن غزو ممالك المسلمين، وكان حسنَ الخط، وكتب بيده جملةً من المصاحف، أرسل منها مصحفًا إلى المدينة. وقد خرجت روحُه وهو ساجد."},{"id":3651,"title":"هزيمة إبراهيم اللودي على يد ظهير الدين المغولي بالهند .","date":["العام الهجري :932","الشهر القمري : رجب","العام الميلادي :1526"],"text":"غزا ظهير الدين محمد بن عمر الشيخ ميرزا بابر البنجاب، واستولى على لاهور بعد هزيمة إبراهيم اللودي, فكان لهذا النصر أثر في سيطرة بابر على دلهي وآكره، وشمال الهندوستان من نهر السند إلى سواحل بنطالة، وإقامة الدولة المغولية."},{"id":3652,"title":"انتصار العثمانيين في موهاكس على ملك المجر .","date":["العام الهجري :932","الشهر القمري : ذي القعدة","العام الميلادي :1526"],"text":"كان ملك المجر فيلاد يسلاف الثاني جاجليو قد عزم على فكِّ أي تعهدات كانت قد أُعطيت من قِبَل أسلافه لسلاطين الدولة العثمانية، وذهب إلى حدِّ قَتْل مبعوث السلطان سليمان إليه، وكان المبعوثُ يطالب بالجزية السنوية المفروضة على المجر، فسيَّرَ السلطان سليمان القانوني جيشًا من القسطنطينية لمحاربة المجر، مؤلفًا من مائة ألف جندي و300 مدفع و800 سفينة في نهر الطونة- الدانوب- لنقل الجيوش من برٍّ إلى آخر، فسار الجيش تحت قيادة السلطان ووزرائه الثلاثة إلى بلاد المجر من طريق الصرب مارين بقلعة بلغراد التي جُعِلت قاعدةً لأعمالهم الحربية، وبعد أن افتتح الجيش عدةَ قلاع ذات أهمية حربية على نهر الطونة، وصل بجمعه إلى وادي موهاكس في 20 ذي القعدة من هذه السنة، وفي اليوم الثاني اصطفَّت الجنود العثمانية على ثلاثة صفوف، وكان السلطان ومعه كافة المدافع وفرقة الانكشارية في الصف الثالث، فهجم فرسان المجر المشهورون بالبسالة والإقدام تحت قيادة ملكِهم على صفِّ العساكر العثماني الأول، فتقهقر أمامهم العثمانيون خلفَ المدافع، ولَمَّا وصلت فرسان المجر بالقرب من المدافع أمر السلطان بإطلاقِها عليهم فأطلقت تباعًا وتوالى إطلاقها بسرعة غريبة أوقعت الرعبَ في قلوب المجَريين، فأخذوا في التقهقر تتبعُهم العساكر المظفرة، حتى قُتِل أغلب الفرسان المجرية وقُتِل مَلِكُهم ولم يُعثَر على جثته، فكانت هذه الواقعة سببًا في ضياع استقلال بلاد المجر بأسرها؛ لعدم وجود جيش آخر يقاوم العثمانيين في مسيرهم، ولحصول الفوضى في البلاد بسبب موت ملِكِهم؛ ولذلك أرسل أهالي مدينة بودبست عاصمة المجر مفاتيحَ المدينة إلى السلطان سليمان فاستلمَها وسار يحفُّ به النصر ويحدوه الجلال حتى وصل إلى مدينة بود ودخلها في 3 ذي الحجة مشددًا الأوامر على الجنود بعدم التعرض للأهالي، والمحافظة على النظام، لكن لم تُجدِ تنبيهاته شيئًا بل انتشرت الجنود في جميع أنحاء المدينة وفي جميع أرجاء بلاد المجر, وبعد دخول السلطان إلى مدينة بود جمع أعيان القوم وأمراءهم، ووعدهم بأن يعيِّنَ جان زابولي أمير ترانسلفانيا ملكًا عليهم ثم غادرها إلى مقر خلافته مستصحبًا معه كثيرًا من نفائس البلاد وأهمُّها الكتب التي كانت موجودة في خزائن متياس كورفن."},{"id":3653,"title":"إقامة محكمة التفتيش الإسبانية في غرناطة .","date":["العام الهجري :933","العام الميلادي :1526"],"text":"أقام شارل الخامس (شارلكان) ملك إسبانيا محكمةَ تفتيش بغرناطة مهمتُها القبض على المسلمين في حال قيامِهم بأحد الأنشطة التالية: الاتجاه للقبلة (وهذا يعني مجرد الصلاة), أو ذبح الماشية على الطريقة الإسلامية, أو التكلم باللغة العربية, أو ارتداء الملابس العربية، وغيرها من الأشياء الأخرى، وكلها قاضية بقمع الهُوية الإسلامية نهائيًّا في إسبانيا ظاهرًا وباطنًا!"},{"id":3654,"title":"هطول مطر غزير بمراكش .","date":["العام الهجري :933","العام الميلادي :1526"],"text":"نزل مطر غزير بمراكش حتى امتلأت منه الآبار وتهدَّمت الدُّور، وصار الناس يؤرِّخون بعام الآبار."},{"id":3655,"title":"انتصار السلطان ظهير الدين بابر شاه على جيش هندي .","date":["العام الهجري :933","الشهر القمري : شعبان","العام الميلادي :1527"],"text":"انتصر السلطانُ ظهير الدين محمد بن عمر الشيخ ميرزا بابر شاه على جيش هندي ضخم يضم 100 ألف جندي، وألف فيل، في معركة بانيبات التي استمرت 7 ساعات فقط، وينتمي بابر شاه إلى سلالة تيمورلنك التي أقامت حكمًا إسلاميًّا للدولة المغولية في الهند استمر 3 قرون."},{"id":3656,"title":"استيلاء خير الدين بربروسا والي الجزائر على البينون من الإسبانيين .","date":["العام الهجري :935","العام الميلادي :1528"],"text":"تمكَّن خير الدين بربروسا من طرد الإسبان من الجيوبِ التي أقاموها في الجزائر، فضمَّ إليه عنابة وقالة في شرقي الجزائر، ثم حقق انتصارًا باهرًا على الإسبانيين حين استولى في هذا العام على حصن بينون الإسباني على الجزيرة المواجهة لبلدة الجزائر، وقد كان قد استمر يقصِفُ الحصنَ بقذائف مدافعه طوال عشرين يومًا حتى تداعت جوانبه، ثم اقتحم الحصنَ مع قوات كثيفة العدد كانت تحملُها خمس وأربعون سفينة جاءت من الساحل، وأُسِرَ قائد الحصن مع كبار ضباطه. إنَّ استيلاء خير الدين على البينون يعدُّ بداية تأسيس ما عرف باسم نيابة الجزائر، ومنذ ذلك التاريخ أصبح ميناء الجزائر عاصمةً عثمانية كبرى للمغرب الأوسط، بل ولكل شمال إفريقيا فيما بعد، وبدأ استخدامُ مصطلح الجزائر؛ للدَّلالة على إقليم الجزائر."},{"id":3657,"title":"وفاة الشيخ أبي محمد الغزواني .","date":["العام الهجري :935","العام الميلادي :1528"],"text":"هو الشيخ أبو محمد عبد الله بن عجال الغزواني أصلُه من مراكش من غزوان، قبيلة من عرب تامسنا، ولِدَ بمدينة القصر الكبير وبها تعلم مبادئ علوم الدين والأدب, وكان في ابتداء أمره يقرأ العلمَ بمدرسة الوادي من عدوة الأندلس بفاس، فحصلت له إرادة فسافر إلى مراكش ولازم الشيخ التباع وتخرج به، ثم انتقل إلى بلاد الهبط فنزل بها على قبيلة، يقال لهم: بنو فزنكار، واجتمع عليه كثيرٌ من مريديه واشتهر أمرُه وعظُمَ صيتُه وكان يغزو مع السلطان, ومات فجأة وهو راكبٌ دابتَه ودُفن بتربته في حومة القصور."},{"id":3658,"title":"تقوية الجبهة الداخلية في الجزائر بإدخالها تحت الحكم العثماني .","date":["العام الهجري :935","العام الميلادي :1528"],"text":"في الوقت الذي كان خير الدين بربروسا يواجه خطر الإسبان في الجزائر، كان يعمل في ذات الوقت على تقوية الجبهة الداخلية بتوحيد المغرب الأوسط, والذي لم يخلو من مؤامرات بني زيان والحفصيين ومن بعض القبائل الصغيرة، ولكنه استطاع مدَّ منطقة نفوذه باسم الدولة العثمانية، ودخلت الإمارات الصغيرة تحت السيادة العثمانية؛ لكي تحتمي بهذه القوة من الأطماع الصليبية الإسبانية ومِن قهرِها على اعتناق النصرانية، وما لبث أن مدَّ خير الدين النفوذَ العثماني إلى بعض المدن الداخلية الهامة مثل قسنطينة. لقد نجح خير الدين في وضع دعامات قوية لدولة فتيَّة في الجزائر، وكانت المساعدات العثمانية تصلُه باستمرار من السلطان سليمان القانوني، واستطاع خير الدين أن يوجِّه ضرباته القوية للسواحل الإسبانية، وكانت جهوده مثمرة في إنقاذ آلاف المسلمين من بطش الإسبان."},{"id":3659,"title":"أول معاهدة امتيازات أجنبية في الدولة العثمانية مع فرنسا .","date":["العام الهجري :935","العام الميلادي :1528"],"text":"كانت أوروبا تعيش انقساماتٍ سياسيةً ودينية خطيرة، أدى ذلك إلى أن تنوعت مواقفُ الدول الأوروبية من الدَّولة العثمانية حسَبَ ظروف كلِّ دولة، فكان تشارلز الخامس ملك الإمبراطورية الرومانية المقدَّسة ينافسُ فرانسوا الأول ملِكَ فرنسا على كرسيِّ الحكم للإمبراطورية الرومانية، فرأى فرانسوا الأولُ أن يكسِبَ الدولة العثمانية صديقاً له، فوقف منها موقِفَ التودد والرغبة في الوِفاق ، فبدأت مفاوضات فرنسا مع الدولة العثمانية بعد معركة \"بافيا\" بين فرنسا وألماني والتي أسِرَ فيها ملك فرنسا \"فرانسوا الأول\" سنة 931هـ فأرسلت والدتُه والوصيةُ على العرش مبعوثَها ومعه خطابٌ منها وخطاب من الملك الأسير يطلبان فيهما مهاجمة قوات ألمانيا وإطلاق سراح الأسير، وعلى الرغمِ من أن الأسير أُطلق بموجب معاهدة بين فرنسا وألمانيا إلَّا أن فرنسوا بعد إطلاق سراحه أرسل في سنة 941هـ سكرتيره إلى السلطان سليمان القانوني؛ بهدف عقد تحالفٍ في شكل معاهدة، سُمِّيت فيما بعد بـ \"معاهدة الامتيازات العثمانية الفرنسية\"، وكان من نتائج هذه المعاهدة زيادة التعاون بين الأسطولين الفرنسي والعثماني، وكانت هذه الامتيازاتُ التي أُعطيت للدولة الفرنسية أوَّلَ إسفين يُدَقُّ في نعش الدولة العثمانية حيث ظهرت آثاره البعيدةُ فيما بعد! وتسببت في التسلط الغربي على العالمِ الإسلاميِّ، وكانت الاستفادة من المعاهدة تكاد تكون مقصورةً على فرنسا ورعاياها، في حين لم تستفِد الدولة العثمانية ورعاياها من هذه المعاهدة بكبيرِ فائدة، بل مهَّدت فيما بعد لقدومِ جيوش الاستعمار الأوروبي النصراني؛ بحجَّة حماية المصالح الاقتصادية الأوروبية في المنطقة!!"},{"id":3660,"title":"حدوث وقعة آنماي بين الوطاسيين والسعديين بالمغرب .","date":["العام الهجري :935","الشهر القمري : ذي القعدة","العام الميلادي :1529"],"text":"لم يعُدْ لبني وطاس وصولٌ إلى مراكش ولا إلى أحوازها، فكان أبو العباس أحمد الأعرج السعدي يتلاقى مع أبي العباس أحمد الوطاسي بتادلا وأحوازها، ووقعت بينهما معركة بموضع يقال له: آنماي، وهو قرب مراكش، وبه زاوية الشيخ أبي العزم رحال الكوش، وكانا قد افترقا على اصطلاح."},{"id":3661,"title":"السلطان العثماني سليمان القانوني يحاصر فيينا عاصمة النمسا .","date":["العام الهجري :936","العام الميلادي :1529"],"text":"بعد أن استطاع العثمانيون فتحَ بودابست عاصمة المجر, وتعيين الخليفة سليمانِ القانوني أميرَ ترانسلفانيا جان زابولي عليها, ادَّعى الأمير فرديناند أخو ملك النمسا شارلكان أحقيَّةَ ملك المجر بدلَ جان الذي وضعه سليمان القانوني، فهجم عليه وهزم الملِكَ جان الذي استنجد بسليمان، فسار إليه الخليفة فهرب فرديناند متجهًا إلى فيينا، فتبعه الخليفة سليمان وتابع في ضغطِه حتى بلغت جيوشه أسوار فيينا عاصمة الإمبراطورية الرومانية المقدسة، وألقى عليها الحصار في محرَّم من هذه السنة، إلَّا أن طول خطوط المواصلات وتحوُّل (شارل كنت) من قتال فرانسوا إلى التصالح معه للتفرُّغ لحرب العثمانيين ولإنقاذ عاصمة الهايسبورج جعل من المستحيل على سليمان القانوني فتحَ هذه العاصمة، وزاد ذلك دخولُ فصل الشتاء في مطلع سنة 937هـ ونفاد الذخيرة المدفعية؛ كلُّ ذلك أدى لتراجع الخليفة سليمان عنها، بينما استمر الصراع بين سليمان والقوى الأوروبية المؤيدة لملك المجر؛ من أجل السيطرة على هذه المملكة حتى وفاة سليمان."},{"id":3662,"title":"خير الدين بربروسا والي الجزائر يهاجم السواحل الإسبانية .","date":["العام الهجري :936","العام الميلادي :1529"],"text":"قام خير الدين بربروسا والي الجزائر في هذا العام بتوجيه ست وثلاثين سفينة خلال سبع رحلات إلى السواحل الإسبانية في الحوض الغربي للبحر المتوسط، وبفضل الله ثمَّ مساعدات الدولة العثمانية وموارد خزينة الجزائر المتنوِّعة من ضرائبَ وسبيٍ ومغانمَ وزكاة والعُشر والجِزية والفيء والخراج، وما يقوم به الحكَّام ورؤساء القبائل والعشائر من دفْعِ العوائد وغيرها- أصبحت دولة الجزائر لها قاعدةٌ اقتصادية قوية، لقد تضرَّرت إسبانيا من نجاح خير الدين في الشمال الإفريقي، وكانت إسبانيا يتزعَّمها شارل الخامس إمبراطور الدولة الرومانية المقدسة، والتي كانت تضم وقتذاك إسبانيا وبلجيكا وهولندا وألمانيا والنمسا وإيطاليا، وكانت الدولة الرومانية المقدَّسة تدفع عن أوروبا النصرانية الخطرَ العثماني؛ لذا يمكن القول بأن الصراع بين شارل الخامس وبين ببليربكية الجزائر كان بمثابة فتح جبهة حربية جديدة ضِدَّ الدولة العثمانية في الشمال الإفريقي."},{"id":3663,"title":"سلطان حضرموت يعلن ولاءه للدولة العثمانية .","date":["العام الهجري :937","الشهر القمري : محرم","العام الميلادي :1530"],"text":"أخذت علاقة السلطان بدر أبو طويرق بالدولة العثمانية تزداد يومًا بعد يوم؛ ففي أواخر سنة 936 توقَّفت حملة القائد العثماني مصطفى بيرم المتَّجهة إلى الهند للتصدِّي للبرتغاليين في ميناء الشحر؛ بسبب رداءة الأجواء الملاحية، وعَقِبَ توقفها خرج الضابِطُ صفر سلمان إلى المدينة بعد أن استأذن من السلطان بدر أبو طويرق حاملًا معه خِلعةً وكساء قدَّمها هدية للسلطان بدر أبو طويرق نيابةً عن قائد الحملة مصطفى بيرم، وقد أحسن السلطان استقبالَهم وضيافتهم، وعند مغادرة الحملة لميناء الشحر في 4 محرم سنة 937 طلبوا من السلطان بدر أبو طويرق السماح لمركبٍ لهم قد تأخَّر في اللحاق بالحملة، ويحمِلُ نساءهم وأبناءهم بالبقاءِ في الشحر، وبوصول ذلك المركب إلى ميناء الشحر أنزل السلطان بدر أبو طويرق من فيه تحت رعايته بمدينة الشحر, ثم غادر مصطفى بيرم بحملته من ميناء الشحر إلى الهند، وأبقى مائةَ جندي من العثمانيين تحت قيادة الضابطِ صفر سلمان لمساعدة السلطان بدر أبو طويرق في حربِه التي كان يخوضُها مع أعدائه في حضرموت الداخل على أن يلحقوا به بعد ذلك، وفي 15 رجب من هذه السنة غادر صفر سلمان ومن تبقى معه من الجنود العثمانيين مدينة الشحر متجهًا إلى الهند."},{"id":3664,"title":"خوض الأسطول العثماني معركة بحرية مع الأسطول البرتغالي .","date":["العام الهجري :937","الشهر القمري : جمادى الآخرة","العام الميلادي :1531"],"text":"خاض الأسطول العثماني معركةً بحرية مع الأسطول البرتغالي المكوَّن من 190 سفينة حربية و210 سفن نقل محمَّلة بستة وعشرين ألف جندي، وذلك قربَ جزيرة ديو الواقعة في المحيط الهندي، والتي تبعد عن شمال جزيرة بومباي بمسافة 250 كم. وقد حقَّق العثمانيون انتصارًا كبيرًا في هذه المعركة."},{"id":3665,"title":"معاهدة الصلح بين العثمانيين والنمسا .","date":["العام الهجري :938","العام الميلادي :1531"],"text":"بعد أن طرد العثمانيون ملكَ النمسا فرديناند من المجَر؛ لتدخله في أمورِها وحصارِهم لفيينا سنة936. عاد ملك النمسا بجيشه هذا العام ودخل بودابست، لكنه لم يستطع أن يستوليَ عليها؛ بسبب مقاومة الحامية العثمانية فيها، فلما سار الخليفةُ سليمان بجيشه نحو المجر ليُخرج منها ملك النمسا طلب الملك فرديناند من الخليفة الصلحَ فوافق عليه وعلى الرجوع بجيشه, وذلك لِما بلغه من قوة استعدادات شارلكان الدفاعية، وأنَّ سفنًا بحرية تابعة لشارلكان والبابا احتلَّت بعض المواقع في شبه جزيرة المورة اليونانية التابعة للدولة العثمانية؛ لذلك آثر الخليفة سليمان أن يوقِعَ المعاهدة مع النمسا."},{"id":3666,"title":"معاهدة إستانبول بين العثمانيين وألمانيا .","date":["العام الهجري :939","الشهر القمري : ذي القعدة","العام الميلادي :1533"],"text":"قامت الدولة العثمانية بإبرام معاهدة إستانبول مع ألمانيا، والتي تم بمقتضاها تثبيت الحدود بين الجانبين، واعترف الألمان بموجِبها بالفتوحات التركية في أوروبا، وقرَّرت المعاهدة أن يدفع الألمانُ ضريبة سنوية للعثمانيين، وألا تُستعمَلَ صفة \"إمبراطور\" في المكاتبات الرسمية مع الدولة العثمانية."},{"id":3667,"title":"وقعة الحمر وهزيمة المسلمين في المغرب .","date":["العام الهجري :940","العام الميلادي :1533"],"text":"وقعت غزوة الحمر بين النصارى والقائد عبد الواحد بن طلحة العروسي على مقربةٍ من آصيلا، وانتصر فيها النصارى على المسلمين, واستُشهد فيها الشيخ أبو الحسن علي بن عثمان الشاوي. كان رحمه الله لما انهزم الناسُ استقبل النصارى وسيفُه في يدِه، فكان ذلك آخِرَ العهد به، ولما رجع الناسُ من الغد ليحملوا قتلاهم لم يوقَفْ لأبي الحسن على عينٍ ولا أثر، وإنما وُجد غنباز من لباسِه عند النصارى وفيه أثَرُ طعنة في صدره- الغنباز عند أهل المغرب: لباسٌ غليظ يستر العنُق."},{"id":3668,"title":"السلطان العثماني سليمان القانوني ينشئ أول أسطول بحري .","date":["العام الهجري :940","العام الميلادي :1533"],"text":"عزم السلطانُ سليمان القانوني- بعد أن استولى على بلغراد، السَّفَرَ بسائر جنوده إلى إسبانيا للاستيلاء عليها، وبدا للسلطان سليمان القانوني أنَّه لا بد له من رجلٍ يعتمد عليه في دخول تلك البلاد على أن يكون عالِمًا بأحوالها، فوقع اختياره على خير الدين بربروسا؛ لما يعرفه عنه من شجاعة وإقدام، وكثرة هجومِه على تلك النواحي، وما استردَّه من بلاد المسلمين في شمال إفريقيا، وكيف أقَرَّ الحكم العثماني فيها، فوجه إليه خطابًا يطلبه فيه إلى حضرته ويأمُره باستنابة بعضِ مَن يأمنه في الجزائر، فعزم خير الدين على السفرِ إلى إستانبول في هذه السنة، وعيَّن مكانَه حسن آغا الطوشي، ولَمَّا وصل إلى إستانبول احتُفل به واستُقبِل بكلِّ حفاوة، وفوَّض إليه الخليفةُ سليمان النظرَ في دار الصناعة، ومنحه لقب قبودان باشا وزير بحرية، حتى تظَلَّ له السلطة الكاملة لمساندةِ النظام في الجزائر؛ لتحقيق هدف الدولة في استعادة الأندلس."},{"id":3669,"title":"استيلاء خير الدين باشا التركي على تونس ثم طرده منها .","date":["العام الهجري :940","العام الميلادي :1533"],"text":"كان أمر بني أبي حفص أصحاب تونس قد مرج في هذه المدَّة وتداعى إلى الاختلال، فقام القائد خير الدين باشا التركي- وهو من القادة الأتراك العظماء- بالاستيلاء على تونس، ففرَّ صاحبها الحسن بن محمد الحفصي إلى طاغية الإسبان صاحب قشتالة، فأعطاه العساكِرَ وجاء بها إلى تونس، فنزل عسكر النصارى ببرج العيون قرب حلق الوادي، وتقدَّموا إلى تونس فملكوها، وانهزم خير الدين إلى الجزائر، وشارك النصارى الحسن بن محمد في إمرة تونس، واستباحوا أهلها قتلًا وأسرًا ونهبًا, ويقال: إنهم قتلوا من أهل تونس الثلثَ، وأسروا الثلثَ، وأبقوا الثلث، وكل ثلث ستون ألفًا!!"},{"id":3670,"title":"غارات خير الدين بربروسا على السواحل الأوربية .","date":["العام الهجري :940","العام الميلادي :1533"],"text":"بعد أن تمَّ إعدادُ الأسطول العثماني الجديد بقيادة خير الدين بربروسا خرج بأسطوله القوي من الدردنيل متجهًا نحو سواحل إيطاليا الجنوبية، فاستطاع أن يأسِرَ الكثير منها، وأغار على مدنِها وسواحلِها، ثم اتجه نحوَ جزيرة صقلية، فاسترجع كورون وليبانتو وكريت."},{"id":3671,"title":"عقد صلح بين بني وطاس والسعديين لإنهاء حالة الحرب بينهما\n  .","date":["العام الهجري :940","العام الميلادي :1533"],"text":"لما رأى أهل المغرب ما وقع بين السلطان أبي العباس أحمد الوطاسي صاحب فاس وأبي العباس أحمد السعدي المعروف بالأعرج صاحب مراكش من الاقتتال على الملك، والتهالك عليه، وفناء الخلق بينهم- دخلوا في الصلح بينهم والتراضي على قسمة البلاد، وحضر لذلك جماعةٌ من العلماء والصلحاء، منهم أبو حفص عمر الخطاب، وأبو الرواين المحجوب، وكان صاحب حالٍ وجذبٍ، فجعل الناس يوصونه بالسكوت مخافةَ أن يُفسِدَ عليهم أمرَهم، فلما دخلوا على أبي العباس الأعرج السعدي وأخيه ووزيره محمد الشيخ وتكلموا فيما جاؤوا لأجله، وجدوا فيهما شدةً وغلظة وامتناعًا من مساعدتهم على ما أرادوا، فحلف أبو حفص الخطاب لا دخلوها يعني فاسًا ما دمتُ على وجه الأرض فما دخلها السعديون حتى مات بعد مدة, وقد أُبرِمَ الصلح بين الطائفتين على أنَّ للسعديين من تادلا إلى السوس، ولبني وطاس من تادلا إلى المغرب الأوسط، وإن ممن حضر الصلح قاضيَ الجماعة بفاس أبا الحسن علي بن هارون المطغري، والإمامَ الشهير أبا مالك عبد الواحد بن أحمد الوانشريسي وغيرهما من مشايخ فاس, ولما تواطأت كلمةُ الحاضرين على الصلح وعقدوا شروطه وهدأت الأصوات وسكن اللجاج، أُتى بدواة وقرطاس ليكتب الصلح, فوضعت الدواةُ بين يدي أحد الفقهاء الحاضرين فوجم وانقبض ودفعَها عن نفسه استحياءً في ذلك المحفل أن يكتُب, فأنشأ أبو مالك الوانشريسي في الحين خطبةً بليغة ونسج الصلحَ على منوال عجيب، واخترع أسلوبًا غريبًا تحير فيه الحاضرون، وعجبوا من ثبات جأشه وجموم قريحته في مثل ذلك المشهد العظيم الذي تخرس فيه ألسن الفصحاء هيبةً وإكبارًا! فقام قاضي الجماعة وقبَّله بين عينيه، وقال: جزاك الله عن المسلمين خيرًا."},{"id":3672,"title":"وفاة السلطان أبو عبد الله الصغير آخر حكام بني الأحمر في غرناطة .","date":["العام الهجري :940","العام الميلادي :1533"],"text":"هو السلطان أبو عبد الله الصغير محمد الثاني عشر بن الحسن بن سعد بن علي بن يوسف بن محمد: آخر حكام بني نصر ابن الأحمر، المنحدرة من قبيلة الخزرج القحطانية في غرناطة، وكان قد تولى الرياسةَ بعد منازعاته مع عمه أبي عبد الله الزغل محمد بن سعد، وكانت دولة بني الأحمر في هذه المدة متماسكةً، والفتنة بين أفرادها متشابكة، والعدو فيما بين ذلك يخادعُهم عمَّا بأيديهم، جاهد أبو عبد الله الصغير النصارى كثيرًا ووصل الأمر إلى أنهم عرضوا عليه التنازل عن غرناطة مقابل أموال جزيلة أسوةً بعمِّه أبي عبد الله الزغل محمد بن سعد صاحب وادي آش، فرفض أبو عبد الله الصغير وواصل جهاده إلى أن شدُّوا عليه الحصار فتنازل كسابقِه، وبعد فترة سافر إلى فاس فاستوطنها تحت كنف السلطان محمد الشيخ الوطاسي؛ حيث عاش فيها حياة لم يعرف أحد عنها شيئًا حتى مات عن عمر يناهز الخمسة والسبعين عامًا متهمًا بالعار والخيانة والتفريط في بلاد المسلمين في الأندلس, وقد دُفن بإزاء المصلَّى خارج باب الشريعة، وخلَّف ذريةً مِن بعده."},{"id":3673,"title":"خير الدين بربروسا يفتح تونس .","date":["العام الهجري :941","العام الميلادي :1534"],"text":"كانت المرحلة الثانية بالنسبة لخير الدين بربروسا بعد هجومه على السواحل الجنوبية لإيطاليا وجزيرة صقلية هي تونس؛ وذلك لتنفيذ خطة الدولة العثمانية، والتي تقتضي تطهير شمال إفريقيا من الإسبان كمقدمة لاستعادة الأندلس، وصل الأسطول العثماني تحت قيادة خير الدين إلى السواحل التونسية، فعرج على مدينة عنابة، وتزوَّد ببعض الإمدادات، ثم تقدَّم نحو بنزرت، ثم اتجه إلى حلق الواد؛ إذ تمكَّن منها بدون صعوبة، واستُقبِل خيرُ الدين من قِبَل الخطباء والعلماء، وأكرموه وتوجَّهوا إلى تونس في نفس الوقت، وهرب السلطان الحفصي الحسن بن محمد إلى إسبانيا، ثم عيَّن خير الدين الرشيد أخا الحسن بن محمد على تونس، وأعلن ضمَّ تونس للأملاك العثمانية، في وقتٍ بدت فيه سيادةُ العثمانيين بالظهور في حوض البحر المتوسط الغربي."},{"id":3674,"title":"العثمانيون يعاودون السيطرة على العراق .","date":["العام الهجري :941","الشهر القمري : ربيع الآخر","العام الميلادي :1534"],"text":"بعد أن ظلَّت العراق تحت الحكم الصفوي من أيام مؤسِّسها الأول إسماعيل شاه، قام الخليفة سليمان القانوني بإعلان الحرب في هذه السنة على الصفويين، فسار بجيشِه من أجل إبطال محاولات شاه طهماسب بن إسماعيل الصفوي لنشر المذهب الشيعي في العراق بدلًا من المذهب السنِّي. فتحرك موكب الجيشِ العثماني تحت قيادة سليمان القانوني، وكبار قادته والأعيان، وكتائب الخيالة؛ حيث خرج الجميعُ من إسكدار عبر آسيا الصغرى، مرورًا بسيواس وأرزنجان، حتى وصل الجيش العثماني إلى تبريز، بعد ذلك توجه نحو همذان؛ ليجد الشاه الفارسي قد فرَّ بقواته إلى أصفهان، ثمَّ إلى منطقة سهل علي، ففضَّل العثمانيون قضاء الشتاء في همذان قبل التوجه إلى بغداد. عندما بلغ أسماعَ محمد خان- أمير بغداد من قِبَل الشاه الصفوي- اقترابُ جحافل العثمانيين، سارع بتقديم فروض الطاعة والولاء، وعلى الرغم من قبول السلطان القانوني ذلك، فإنَّ هواجس الخوف من انتقام العثمانيين راودت محمد خان، فاستقرَّ عزمه على الفرار برفقة جنودِه من بغداد إلى البصرة، ومنها إلى مقرِّ الشاه طهماسب، فتقدم العثمانيون إلى بغداد، ووصلوا في ربيع الآخر من هذه السنة. وعندما حل الربيع شرعت القواتُ العثمانية في حملات تأديب لفلول القوات الموالية للشاه الصفوي. ثم أرسل إلى أحمد خان حاكم الأقاليم العثمانية في هنغاريا ورومانيا بسرعةِ إرسال الجنود؛ لمساندة حملته ضد الصَّفويين، كما لم ينسَ تذكيرَه بإعداد الطبول والفِرَق الموسيقية للاحتفال بالنصر العثماني المرتقَب. وبمجرد دخول سليمان القانوني إلى بغداد ارتفعت الخطبة وضُرِبت السكة باسمه، وجرى إبطال القوانين الصفوية السابقة كافةً، بعد ذلك أرسل السلطان العثماني للشاه الصفوي رسالةَ تهديد فحواها أنه قادِمٌ للاستيلاء على أقاليمه وضمِّها لدولة العثمانيين. كما أرسل إلى سليمان باشا والي مصر الذي خرج بعدة آلاف من المحاربين للانضمام إلى سليمان القانوني في العراق."},{"id":3675,"title":"استعادة الإسبان احتلال تونس بعد انتزاعها من العثمانيين  .","date":["العام الهجري :942","الشهر القمري : محرم","العام الميلادي :1535"],"text":"لم تلبث تونس كثيرًا تحت يد العثمانيين حتى اتفق شارل الخامس (شارلكان) ملك إسبانيا وأسبان برشلونة ورهبان مالطة على الحرب واستعادة تونس التي كانت تحت يد الإسبان قبل أن يستعيدها خير الدين بربروسا العام الماضي، مستغلين انشغال العثمانيين بحربهم ضد الصفويين الرافضة، فتوجَّه الجيش بقيادة شارلكان نفسه ملك إسبانيا بحملة بحرية كبيرة، تكوَّنت من ثلاثين ألف مقاتل إسباني وهولندي وألماني ونابولي وصقلي، على ظهر خمسمائة سفينة، وركب الإمبراطور البحرَ من ميناء برشلونة، وعندما رست سفُنُه أمام تونس قامت المعارك العنيفة بين الطرفين، لم تكن قوة خير الدين كافيةً للرد على هذا الهجوم، فكان تعدادُ جيشه سبعةَ آلاف جندي عثماني وصلوا معه، ونحو خمسة آلاف تونسي، كما تخلَّف الأعراب عن الجهاد، فكانت النتيجة الحتمية أنَّ استيلاء شارل على معقِل حلق الوادي مرسى تونس، ونصَب الإسبان حليفَهم الحسن بن محمد الحفصي حاكمًا عليها، وعملًا بمنطوق المعاهدة كان الحسن بن محمد سيسلِّم بونة والمهدية إلى شارل الخامس، فاستولى على بونة، وبما أنَّ المهدية كانت في حوزة العثمانيين فإنَّ الحسن لم يستطع الوفاءَ بعهده، فاشترط الإسبان عليه أن يكون حليفًا ومساعِدًا لفرسان القديس يوحنا بطرابلس، وأن يقوم بمعاداة العثمانيين، وأن يتحمل نفقات ألفي إسباني على الأقل يُترَكون كحامية في قلعة حلق الواد، وعاد شارل الخامس إلى إسبانيا بعد أن ارتكبوا أفظع الجرائم في تونس عند دخولهم فيها، مُظهرين الحقدَ الدفين، فجعلوا جامِعَ الزيتونة إسطبلًا لخيولهم، وأحرقوا المساجِدَ والكتب النادرة فيها، غير قتلِهم النساء والأطفال!!"},{"id":3676,"title":"توقيع الوزير العثماني داماد إبراهيم باشا معاهدة امتيازات مع فرنسا .","date":["العام الهجري :942","الشهر القمري : شعبان","العام الميلادي :1536"],"text":"حصلت فرنسا بموجِب معاهدة أبرمتها مع الدولة العثمانية على امتيازاتٍ عسكرية واقتصادية؛ لتنميتِها والحيلولة دون وقوع فرنسا تحت نفوذ ملك إسبانيا وألمانيا، وهو ما مهَّد السبيل لكي يرسوَ الأسطول العثماني في ميناء طولون الفرنسي في البحر المتوسط."},{"id":3677,"title":"خير الدين بربروسا يلاحق الأسطول الإسباني في عدة معارك .","date":["العام الهجري :943","العام الميلادي :1536"],"text":"قام خير الدين بربروسا بالهجومِ على جزر البليار الإسبانية وعلى سواحلها الجنوبية، فاجتاز مَضِيقَ جبل طارق، وأطلق العِنانَ لنفسِه بالانقضاض على السفُن الإسبانية والبرتغالية العائدة من الأراضي الأمريكية، والمحمَّلة بالذهب والفضة، فاهتَزَّت لتلك الأحداث جميعُ الأوساط النصرانية، وأقلقت شارل الخامس ملك إسبانيا الذي اعتقد أنَّ خير الدين لن يقوى شأنُه بعد حادثة تونس السابقة، ويُعتبَر ذلك هو ردَّ الفعل على الهجوم المضادِّ الذي قام به الإسبان على تونس، وبدا وكأن الإمبراطوريةَ الرومانيةَ المقدَّسة قد طُوِّقت من قِبَل خصومها الفرنسيين والعثمانيين؛ مما أدى إلى استئناف الحروب بينهما من جديدٍ، كما صارت أهداف إسبانيا والبرتغال واحدةً، وذلك في احتلال مراكزَ في بلاد المغرب بالإضافة إلى خوفهم من تقدُّم العثمانيين داخلَ شِبه الجزيرة الأيبيرية."},{"id":3678,"title":"معاهدة بين البرتغال والوطاسيين  .","date":["العام الهجري :943","العام الميلادي :1536"],"text":"إثر الهزيمة التي تلقَّتها أسرة الوطاسيين أمام السعديين في وقعة بير عقبة تقرَّب أحمد الوطاسي من البرتغال؛ وذلك نتيجة شعوره بانشغال العثمانيين في حروبِهم ضِدَّ الإسبان، ووقَّع معهم معاهدة لمدة أحد عشر عامًا تقضي بوضع المغاربة المقيمين في ضواحي آصيلا وطنجة والقصر الصغير تحت السلطة القضائية لملك فاس، كما يجوز لرعايا الملك الوطاسي المتاجرة بحُرية داخلَ تلك المناطق باستثناء تجارة الأسلحة والبضائع المحظورة، وإذا وصلت مراكِبُ عثمانية أو فرنسية أو تابعة لنصارى من غير الإسبان ولا البرتغاليين إلى أراضي برتغالية، محمَّلة بغنائم أُخِذَت من المغاربة- فلن يُشترى منها شيء، وكذلك الحالُ بالنسبة للمغاربة لن يشتروا من العثمانيين، ويتم الاستيلاءُ على الغنائم وتُرَدُّ من طرفٍ لآخر مالم يسمح قوات العدو في مهاجمتِها."},{"id":3679,"title":"وقعة بير عقبة بوادي العبيد بين الوطاسيين والسعديين .","date":["العام الهجري :943","الشهر القمري : صفر","العام الميلادي :1536"],"text":"كانت الأسرة الوطاسية هي الحاكمةَ على فاس بزعامة أبي العباس أحمد بن أبي عبد الله محمد، وكانت الأسرةُ السعدية أخذت في التوسُّع بزعامة أبي العباس أحمد الأعرج وانتقلت من مراكش، وهدَّدت سلطنة الوطاسيين، فقامت بين الأسرتين حروبٌ دامت أيامًا، تعتبر وقعةُ بير عقبة من أعظم الوقعاتِ التي كانت بين الوطاسيين والسعديين، وتحدَّث بها العامة في أنديتهم كثيرًا وبالغوا في وصفِها والإخبار عنها، وقد ذكرها شعراؤهم في أزجالهم-نصوصهم- الملحونة، وهي محفوظة فيما بينهم، وذلك أنَّه لَمَّا طمى عباب السعديين على بلاد الحوز وكادوا يَلِجون على الوطاسيين دارَ مُلكِهم من فاس، نهض إليهم السلطان أبو العباس أحمد الوطاسي أواخِرَ سنة اثنتين وأربعين وتسعمائة يجرُّ الشوك والمدَر في جمعٍ كثيف من الجند وقبائل العرب في حُلَلِها وظُعُنها، وجاء أبو العباس السعدي في قبائل الحوز بحللها وظعنها كذلك. فكان اللقاءُ بمشروع بير عقبة- أحد مشاريع وادي العبيد- من تادلا، فنشبت الحرب وتقاتل الناسُ وبرز أهل الحفائظ منهم والتراث، وقاتل الناسُ على حرمهم وأحسابهم وعِزِّهم، فأفنى بعضهم بعضًا إلا قليلًا، ودامت الحرب أيامًا على ما قيل إلى أن كانت الهزيمة على الوطاسيين؛ وذلك بسبب تخلي قبائل الخلوط التي كادت تكون القوةُ الأمامية للجيش الوطاسي؛ مما أدى إلى انتشار الفوضى في سائر جيش الوطاسيين, وعلى إثر هذه الهزيمة عُقِد صلحٌ بين الطرفين في مدينة تادلا يقضي بتقسيم البلاد بين الأسرتين، وبموجِبه انسحب الوطاسيون إلى فاس وبقيت تادلا بيد الشريفِ السعدي أبي العباس أحمد الأعرج، وأظهرت هذه المعركة قوةَ السعديين."},{"id":3680,"title":"هزيمة البنادقة على يد السلطان العثماني سليمان القانوني .","date":["العام الهجري :944","العام الميلادي :1537"],"text":"نشبت معركةٌ كبيرة بحرية بين الأسطول العثماني بقيادة خير الدين بربروسا وبين الأسطولين الإسباني والبندقي على شواطئ اليونان الغربية، استطاع فيها الأسطولُ العثمانيُّ تحطيمَ الأسطولين المشتركين، فأدى ذلك لبسط السيادة العثمانية على البحر المتوسطِ الجزءِ الغربيِّ منه بعد أن كان للإسبان."},{"id":3681,"title":"دخول اليمن تحت الحكم العثماني .","date":["العام الهجري :944","العام الميلادي :1537"],"text":"كان الأسطولُ العثماني المتجه لقتال البرتغاليين على شواطئ الهند من مهمَّاته المرورُ على اليمن وإخضاعُها للحكم العثماني، فعند وصول الأسطول العثماني بقيادة سليمان باشا الخادم، والمؤلَّف من سبعين سفينة، اتجه على رأس عشرين ألف جندي وفتح عدن ومسقط، وحاصر جزيرة هرمز حتى فتحَها."},{"id":3682,"title":"وفاة العلامة وجيه الدين عبد الرحمن بن الدَّيبع .","date":["العام الهجري :944","الشهر القمري : رجب","العام الميلادي :1538"],"text":"العلَّامةُ الحافِظُ وجيهُ الدِّين أبو محمد عبد الرحمن بن علي الدَّيبع الشيباني العبدري الزَّبيدي الشافعي. قال في آخِرِ كتابه «بغية المستفيد بأخبار زبيد»: \"كان مولدي بمدينة زَبيد المحروسةِ في يوم الخميس الرابِعَ مِن المحَرَّم الحرام سنةَ سِتٍّ وستين وثمانمائة في منزل والدي منها، وغاب والدي عن مدينةِ زبيدٍ في آخرِ السنة التي وُلِدتُ فيها ولم تَرَه عيني قطُّ، ونشأتُ في حجر جدِّي لأمِّي العلَّامة الصَّالح العارف بالله تعالى: شرف الدِّين أبي المعروف إسماعيل بن محمد بن مبارز الشافعي، وانتفعتُ بدعائه لي، وهو الذي ربَّاني- جزاه الله عنِّي بالإحسان، وقابله بالرَّحمة والرِّضوان\". وكان ثقةً صالحًا حافظًا للأخبار والآثار، متواضِعًا، انتهت إليه رئاسةُ الرحلةِ في علم الحديث، وقَصَده الطلبةُ من نواحي الأرض, ومن مصنَّفاتِه «تيسير الوصول إلى جامع الأصول» في مجلدين, و«حدائق الأنوار ومطالع الأسرار في سيرة النبي المختار صلى الله عليه وعلى آله المصطفين الأخيار»، و«تمييز الطَّيِّب من الخبيث فيما يدور على ألسنة الناس من الحديث»، و«مصباح المشكاة»، و«شرح دعاء ابن أبي حربة»، و«غاية المطلوب وأعظم المنَّة فيما يغفِرُ الله به الذنوبَ ويوجِبُ به الجنَّة»، و«بغية المستفيد في أخبار مدينة زَبيد»، و«قرَّة العيون في أخبار اليمن الميمون»، إلى غير ذلك. ومِن شِعرِه قولُه في «صحيح» البخاري ومسلم:تنازع قومٌ في البخاري ومُسلِم لديَّ وقالوا: أيَّ ذينِ يقدَّم فقلتُ: لقد فاق البخاريُّ صَنعةً كما فاق في حُسنِ الصِّياغة مُسلِم . ولم يزَلْ على الإفادة وملازمةِ بيته ومسجدِه لتدريسِ الحديثِ والعبادة، إلى أن توفِّيَ ضُحى يوم الجمعة السادسَ والعشرين من رجب."},{"id":3683,"title":"البرتغال يوقِّعون معاهدة مع السعديين للحد من نفوذ العثمانيين .","date":["العام الهجري :944","الشهر القمري : ذي القعدة","العام الميلادي :1538"],"text":"حاول البرتغاليون عقدَ هُدنة مع السعديين كما فعلوا مع خصومِهم الوطاسيين، فبعثوا وفدًا إلى مراكش للتفاوض مع السلطان أبي العباس أحمد الأعرج الذي استجاب لذلك؛ لأنه كان في حاجة إلى تنظيم أمور دولته الناشئة لا سيما بعد الانتصارات التي حقَّقها ضد خصومه الوطاسيين في موقعة بير عقبة، واتفق البرتغاليون مع السعديين على عقدِ هدنة بينهما في 25 ذي القعدة من هذه السنة, لمدة ثلاث سنوات، مع إقامة تبادُل تجاري بين رعايا الطرفين, وكان هدفُ البرتغاليين من التقرب مع الوطاسيين والسعديين هو الحيلولةَ دون قيام تعاوُن حقيقي بين العثمانيين من ناحية والوطاسيين والسعديين من ناحية أخرى، لأنَّ أي تعاون من هذا القبيل معناه تهديدٌ لمصالح شبه الجزيرة الأيبرية في المغرب، والأهمُّ من ذلك خوفُ إسبانيا والبرتغال من تقدُّمِ الدولة العثمانية داخِلَ شبه الجزيرة الأيبرية، وتحقيقِ هدفِها في استرداد الأندلس."},{"id":3684,"title":"تحالف عثماني فرنسي لغزو إيطاليا .","date":["العام الهجري :945","العام الميلادي :1538"],"text":"كان العثمانيون قد تحالفوا مع الفرنسيين على غزو إيطاليا: العثمانيون بحرًا من الجنوب، والفرنسيون برًّا من الشمال، لكنَّ العثمانيين ترددوا في الاستمرار؛ خشية من التمرد الأوربي عمومًا، وكانت فرنسا تشجِّعُها على الاستمرار لإنقاذ جزيرة كورفو من البنادقة، فتابعت فرنسا سيرَها من الشمال حتى احتلَّت ميلانو وجنوة، ثم قام البابا بالتوسُّط بين فرانسوا ملك فرنسا، وبين النمسا في سبيل الوحدة الأوربية عمومًا، ووعد فرانسوا أيضًا بالاشتراك في حرب صليبية ضدَّ العثمانيين، في الوقت الذي كان العثمانيون يجهِّزون جيشًا من ألبانيا لنقله إلى إيطاليا، ووعد فرانسوا بسحب جيوشِه من الشمال."},{"id":3685,"title":"حملة عثمانية لطرد البرتغاليين من سواحل البحر الأحمر .","date":["العام الهجري :945","العام الميلادي :1538"],"text":"أرسل السلطانُ العثماني سليمان القانوني حملةً عسكرية بهدف ضرب البرتغاليين في ميناء ديو بالهند، الذين كانوا يعيثون فسادًا في موانئ البحر الأحمر والبحر العربي، بينما كان الغرض الحقيقي من ورائها هو السيطرةَ على بلاد اليمن، وكانت الحملة تتكَّون من عشرين ألف جندي، تحملهم ثمانون سفينة بقيادة سليمان باشا الخادم أحد المماليك المقرَّبين من السلطان العثماني سليمان القانوني، وكان قد سبق وصولَ هذه الحملة إلى سواحل حضرموت وصولُ وفدٍ عثماني إلى مدينة الشحر في شهر ربيع الأول سنة 944 يتكوَّنُ من ثلاثين فردًا بقيادة الأمير فرحات الشوباصي؛ بقصد إطلاع حكام حضرموت على مهمة الحملة العثمانية بقيادة سليمان باشا الخادم، والمتمثِّلة في محاربة البرتغاليين في المحيط الهندي والبحار الشرقية، وحماية البلاد العربية من اعتداءاتهم، وإعادة خط التجارة العالمي إلى ما كان عليه قبل اكتشاف رأس الرجاء الصالح، وكان من ضمن أهدافِ هذا الوفد التعرفُ على مصداقيَّة حكام حضرموت وولائِهم للدولة العثمانية."},{"id":3686,"title":"استنجاد الهند بالعثمانيين ووقعة ديو الثانية .","date":["العام الهجري :945","العام الميلادي :1538"],"text":"وصل السفيرُ الهندي من كوجرات يستنجد الخليفة العثماني ضِدَّ البرتغاليين الذين وصلوا إلى سواحل الهند، وآخَرُ مِن دلهي يستنجد ضِدَّ همايون بن ظاهر الدين محمد المشهور ببابر، وهو من المغول الذين دخلوا الهندَ وحكموها، فانطلق سليمان باشا الخادم إلى كوجرات ودخل بعض القلاع التي أقامها البرتغاليون على سواحل الهند، فالتقى الأسطولُ العثماني بالأسطول البرتغالي أمام مدينة ديو على ساحل الملبار، ولكِنَّ الأسطول العثماني باء بالهزيمة والفشل، فاضطرَّ للانسحاب؛ مما أتاح للبرتغاليين بسطَ سيادتهم على المحيط الهندي، وظَلَّ البرتغاليون أصحابَ السيادة حتى أواخر القرن السادس عشر الميلادي دون منازعٍ."},{"id":3687,"title":"استيلاء العثمانيين على ميناء عدن .","date":["العام الهجري :945","الشهر القمري : صفر","العام الميلادي :1538"],"text":"استولى العثمانيون على ميناء عدن، وبعدها شنَقوا أمير عدن \"عامر الثالث\" بتهمة تقديم التسهيلات للبرتغاليين، وعدم طاعته للخليفةِ العثماني."},{"id":3688,"title":"معركة بروزة وهزيمة أندرى حليف ملك إسبانيا  .","date":["العام الهجري :945","الشهر القمري : جمادى الأولى","العام الميلادي :1538"],"text":"دارت معارك عديدة بين أندرى دوريا القائدِ البحري الجنوي- حليف ملك إسبانيا شارلكان ضد العثمانيين- وبين الأسطول العثماني، كان أشهرُها معركة بروزة والتي مُنِيَ فيها أندرى بهزيمةٍ ساحقة أمام الأسطول العثماني بقيادة خير الدين برباروسا."},{"id":3689,"title":"فتح السلطان محمد الشيخ السعدي حصن النصارى فونتي بسوس .","date":["العام الهجري :947","العام الميلادي :1540"],"text":"لما استقلَّ السلطان أبو عبد الله محمد الشيخ السعدي بأمر السوس، واجتمعت الكلمةُ عليه؛ صرفَ عَزمَه إلى جهاد العدوِّ الذي بثغوره وحصونه، وأرهف حدَّه لتطهيرها من بقايا شغبه، فانتصر عليهم واستأصل شأفتَهم وقطع من تلك النواحي دابِرَهم، وحسم آفتَهم، ففتح حصن فونتي الذي بناه البرتغاليون بالسوس بعد أن أقاموا فيه اثنتين وسبعين سنة، وكان السلطان السعدي منصورًا بالرعب!"},{"id":3690,"title":"بناء حصن أغادير .","date":["العام الهجري :947","العام الميلادي :1540"],"text":"بنى الأميرُ السلطان أبو عبد الله محمد الشيخ السعدي حصنَ أغادير بالسوس الأقصى، وذلك بعدما أجلى النصارى البرتغال من الموضع المعروف بفونتي، وكان له في اختطاطه رأيٌ مصيب وفِراسة تامة."},{"id":3691,"title":"معاهدة إستانبول بين الدولة العثمانية والبندقية .","date":["العام الهجري :947","الشهر القمري : جمادى الآخرة","العام الميلادي :1540"],"text":"عقدت الدولةُ العثمانية معاهدةً مع البندقية عُرِفت بمعاهدة إستانبول دفَعَت البندقية بمقتضاها حوالي 300 ألف ليرة ذهبية للعثمانيين، كغرامة حرب، وقد حالت هذه المعاهدةُ دون انضمام البندقية إلى الإمبراطور الألماني شارل كوينت، الذي كان في حربٍ مع العثمانيين أثناءَ تلك الفترة."},{"id":3692,"title":"السعديون يفتحون سانتاكروز والبرتغال يتخلون عن آسفي وأزمور .","date":["العام الهجري :948","العام الميلادي :1541"],"text":"حقَّق السعديون على صعيدٍ آخر نصرًا كبيرًا على البرتغاليين، وفتحوا حصن سانتاكروز في السوس، وما أن علِمَ ملك البرتغال جان الثالث بهذا الخبر حتى أمر حامياتِ آسفي وأزمور بالجلاء فورًا عنها، وقد وجَّه الملك جان الثالث في هذا الشأن إلى سفيره بمدريد رسالةً يُطلِع فيها الإمبراطور الإسباني شارل الخامس، حيث جاء فيها ذِكرُ الأسباب التي أجبرت البرتغال على اتخاذ قرار الجلاء عن قاعدتي آسفي وأزمور، ومنها تزايُدُ قوات السعديين بفضل المساعدات العثمانية، بحيث صار الحاكمُ السعدي يملِكُ المدفعيةَ العثمانية، والآلاتِ الحربيةَ، وجنودًا مدربين، وقد ظهر أثرُ تلك الإمدادات عند حصار سانتاكروز؛ ممَّا جعل الاحتفاظَ بهذين المركزين آسفي وأزمور أمرًا شاقًّا وصعبًا."},{"id":3693,"title":"هزيمة ملك إسبانيا شارلكان في معركة باب الواد في الجزائر .","date":["العام الهجري :948","الشهر القمري : رجب","العام الميلادي :1541"],"text":"عزم شارل الخامس (شارلكان) ملكُ إسبانيا على القيام بحملة عسكرية تستهدفُ القضاء على حركةِ الجهاد الإسلامي في الحوضِ الغربيِّ للبحر المتوسط، وقبل أن يشرَعَ في تنفيذها حدث هدوءٌ نسبيٌّ ساد القارةَ الأوربية إثرَ عقدِ هُدنة نيس في محرم 945 (يونيو 1538م) مع فرنسا، والتي كانت مدتها عشر سنوات. ومما شجع شارلكان على هذه الحملة علمُه بأن القائد التركي خير الدين بربروسا قد ذهب إلى إستانبول للَّقاء بالسلطان العثماني وأسند قيادةَ الأسطول العثماني للقائد حسن آغا الطواشي. رسا شارلكان بسُفُنه أمام مدينة الجزائر في يوم 28 جمادى الآخر من هذه السنة, وعندما شاهده الطوشي اجتمع في ديوانه مع أعيان الجزائر وكبار رجال الدولة، وحثَّهم على الجهاد والدِّفاع عن الإسلام والوطن، ثم بدأ حسن آغا في إعدادِ جيوشِه والاستعداد للمعركةِ، من ناحية أخرى بدأ الإسبانُ في تحضير متاريسِهم، وتعجَّب شارل الخامس لاستعداداتِ حسن آغا وأراد أن يستهزئَ به، وفي الليلة ذاتها وصل إلى معسكر شارلكان رسولٌ مِن قِبَل والي الجزائر يطلُبُ إذنًا للسماح بحُرية المرور لمن أراد من أهل الجزائر- وخاصَّةً نساءَها وأطفالَها- مغادرةَ المدينة عبرَ باب الواد، وعرف شارلكان أن حامية الجزائر مصَمِّمة على الدفاع المستميت، وأنَّه من المُحال احتلال الجزائر إلا إذا تم تدميرُها تدميرًا تامًّا، ولم يكن شارلكان قد أنزل مدفعيةَ الحصار حتى تلك الساعة، فلم يتمكن بذلك من قصفِ الجزائر بالمِدفعية، وفي الوقت نفسِه كان المجاهدون يوجِّهون ضرباتِهم الموجعة إلى القوات الإسبانية في كل مكان، وكانت أعداد المجاهدين تتعاظم باستمرار بفضل تدفُّق مقاتليهم من كل مكان، بمجرد سماعِهم بإنزال القوات الإسبانية، وكان المجاهدون يستفيدون في توجيههم لضرباتهم من معرفتهم الدقيقةِ بالأرض واستخدامهم لمميزاتها بشكلٍ رائع، وسخر الله لجنود الإسلام الأمطارَ والرياحَ والأمواجَ، وهَبَّت ريحٌ عاصِفٌ استمرَّت عِدَّةَ أيام واقتلعت خيام جنود الحملة وارتطمت السفنُ بعضُها ببعض؛ مما أدى إلى غرق كثير منها، وقذفت الأمواج الصاخبةُ ببعض السفن إلى الشاطئ، وهجم عليها المدافعون المسلمون واستولوا على أدواتِها وذخائرها، أما الأمطار فقد أفسدت مفعولَ البارود، وفي وسط هذه الكوارث حاول شارلكان مهاجمةَ مدينة الجزائر إلا أنَّ كلَّ محاولاته باءت بالفشل، واضطُرَّ إلى الانسحاب مع بقية جنوده على ما تبقَّى لهم من سفن، واتجه بأسطوله إلى إيطاليا بدلًا من إسبانيا بعد أن قُتِلَ من جيشه في المعركة أكثر من 20 ألفًا وانتشرت جثثهم لعدة كيلو مترات على ساحل البحر، وأُسِر حوالي 130 سفينة! ويُعَدُّ هذا الانتصارُ من الانتصارات الكبرى في تاريخ العثمانيين والجزائريين، ولم تفكِّرْ أي قوة صليبية بعدها في احتلال الجزائر إلَّا في عام 1830م."},{"id":3694,"title":"انتزاع الأسطول العثماني مدينة نيس من الإسبان وتسليمها لفرنسا  .","date":["العام الهجري :950","العام الميلادي :1543"],"text":"قام شارلكان ملكُ إسبانيا بإعلان الحرب ضِدَّ فرنسا التي تعتبَرُ عدوًّا له باعتبارها من حلفاء الدولة العثمانية, فقام الفرنسيون بالاستنجاد بالعثمانيين وتوقيع معاهدةٍ جديدة ضِدَّ شارلكان الذي كان يحكُمُ نيس، فانضمَّ الأسطول الفرنسي إلى الأسطول العثماني بأمرٍ من ملك فرنسا، ووضَعَ قائدُ الأسطول الفرنسي الأمير فرانسوا دبو بوربون قواتِه تحت قيادة القائد التركي خير الدين بربروسا، باعتباره القائِدَ العامَّ للقوات المتحالفة العثمانية-الفرنسية, وكان أوَّلُ عمل قام به خير الدين هو قيادةَ هذه القوات لمهاجمة نيس وطرْدَ حاكمِها دوق سافوا، وانتزاعَها من الحُكم الإسباني وإعادتها لملك فرنسا."},{"id":3695,"title":"بسط العثمانيين نفوذهم على المغرب الأوسط .","date":["العام الهجري :950","العام الميلادي :1543"],"text":"استطاع العثمانيون أن يسيطروا على الجزائرِ بمساعدة أمير البحرِ عروج باشا، ومن بعدِه أخوه خير الدين بربروسا، وكذلك استطاعوا أن يسيطروا على تونس شيئًا فشيئًا، وكذلك على ليبيا بعد ذلك حتى صارت أقاليمها الثلاثة- طرابلس وبرقة وفزان- تحت الولاية العثمانية."},{"id":3696,"title":"انقراض أمر أمراء بني عبد الحميد العروسيين .","date":["العام الهجري :950","العام الميلادي :1543"],"text":"كان لأمراء بني عبد الحميد العروسيين- أصحاب قصر كتامة- رياسةٌ وسياسةٌ وجهادٌ في العدوِّ إلى أن انقرض أمرُهم, وأخبر غيرُ واحد من فقهاء قصر كتامة أنَّ الشيخ أبا الرواين المحجوب جاء إلى القصر وصاحَبَه يومئذ القائدُ عبد الواحد العروسي في عصبةٍ من أقاربه أولاد عبد الحميد، فصعد أبو الرواين صومعةَ المسجد ثم نادى بأعلى صوتِه: يا بني عبد الحميد، اشتروا مني القصرَ وإلَّا خرجتُم منه في هذه السنة، فسمع القائدُ عبد الواحد ذلك، فقال: إن كان القصرُ له أو بيده فلينزِعْه منَّا، ما بقي لنا إلا كلامُ الحمقى نلتفت إليه! ومِن الغد خرج الشيخ أبو الرواين من البلد وهو يقول: القائدُ عبد الواحد وأهله يخرجون من القصرِ ولا يعودون إليه أبدًا، فكان كذلك بقدرةِ الله تعالى."},{"id":3697,"title":"اتخاذ خير الدين بربروسا مدينة طولون الفرنسية قاعدة للعثمانيين .","date":["العام الهجري :950","العام الميلادي :1543"],"text":"بعد طردِ خيرِ الدين بربروسا الإسبانَ من مدينة نيس وتسليمِها للفرنسيين استقَرَّ بأسطوله في مدينة طولون الفرنسية، وجعلَها قاعدةً للجيشِ الإسلاميِّ وأسطولِه، بعد أن غادرَها معظَمُ سكانِها بأمرِ ملك فرنسا وتركوها في أيدي المسلمين."},{"id":3698,"title":"استيلاء الأسطول العثماني على صقلية وبعض السواحل الإيطالية .","date":["العام الهجري :950","الشهر القمري : ربيع الأول","العام الميلادي :1543"],"text":"استولى الأسطول العثماني بقيادة خير الدين بربروسا على صقلية وبعضِ السواحل الإيطالية، ودمَّرَ استحكاماتِها، ثم استولى على ميناء أوستيا الواقع على نهر تيبر، الذي يبعد 15 كم عن مدينة روما مقرِّ البابويَّة الكاثوليكية في العالم."},{"id":3699,"title":"سقوط نيس وطولون ثانية في يد النصارى  .","date":["العام الهجري :951","العام الميلادي :1544"],"text":"كان تحرير نيس من أيدي الإسبان- بعد اتفاق الفرنسيين مع العثمانيين ضد الإسبان- قد أثار ثائرة النصارى جميعًا في أوروبا ضد هذا التصرُّف الفرنسي، وأخذت الدعايةُ المضادة للمسلمين تجتاحُ أرجاء أوروبا، يحمِلُها الإسبان وغُلاة الصليبية، ويستثمرونها إلى أقصى الحدود، ومن ذلك قولهم: إنَّ خير الدين بربروسا القائدَ العثماني قد اقتلع أجراسَ الكنائس، فلم تعُدْ تَسمع في طولون إلا أذان المؤذنيين, وبقي خير الدين والجندُ الإسلامي بمدينة طولون حتى هذه السنة، وكان شارلكان ملك إسبانيا أثناء ذلك قد هاجم شمال شرقي فرنسا وانهزم تحت جدران شاتوتييري، ثم اضطرَّ للذهاب إلى ألمانيا؛ حيث كانت حركة التمرد البروتستانتي ضد الكاثوليكية بصفة عامة- وضده بصورة خاصة- قد أخذت أبعادًا خطيرة، وأرغمه ذلك بعد أن هوى نجمُه وذبُل عوده نتيجة نكبته أمام الجزائر إلى عقد معاهدة مع ملك فرنسا (في 18 أيلول سبتمبر 1544م) في مدينة كريسبي دي فالوا، ونتج عن هذه المعاهدة جلاءُ خير الدين وقواته عن مدينة طولون, ورجع إلى العاصمة إستانبول."},{"id":3700,"title":"استيلاء السلطان محمد الشيخ السعدي على مراكش وتجديد البيعة له .","date":["العام الهجري :951","العام الميلادي :1544"],"text":"كان السلطان أبو عبد الله محمد الشيخ السعدي بعد القبض على أخيه واستقلاله بالأمر، قد أقام بالبلاد السوسية مثابرًا على جهاد العدوِّ إلى أن قلع عروقَ مفسدتِه منها، وكانت مراكش في هذه المدَّة قد توقَّفت عن بيعته، وتربصت عن الدخول في دعوته اتقاءً للوطاسيين وارتيابًا في أمره إلى ماذا يؤول، واستمَرَّ الحال إلى هذه السنة فانقادت له حينئذ، وبايعه أهلُها فقَدِمَها واستولى عليها وخَلُصَ له جميعُ ما كان بيد أخيه المخلوع: من تادلا إلى وادي نول."},{"id":3701,"title":"خير الدين بربروسا يواصل جهاده على سواحل أوروبا .","date":["العام الهجري :952","العام الميلادي :1545"],"text":"لم تتوقف الحرب بين إسبانيا والمسلمين؛ فقد استمرَّ خير الدين بربروسا في ممارسة الأعمال القتالية أثناء طريق عودته، فتوقَّف أمام مدينة جنوة، فارتاع مجلسُ شيوخها فأرسل له مجموعةً من الهدايا الثمينة مقابِلَ عدم التعرض للمدينة بأذًى، فتابع خير الدين طريقَه حتى وصل جزيرة (البا) التي كانت تحت حكم إسبانيا فاحتلَّها وغَنِمَ ما بها، كما احتَلَّ عددًا من المدن الساحلية، من بينها مدينة (لبياري) ورجع إلى إستانبول بسفُنِه مثقلةً بالغنائم، فاستُقبل كأحسَنِ ما تَستقبلُ به الأمُّ أبناءها البَرَرة."},{"id":3702,"title":"معاهدة بين الصفويين بإيران والبرتغال .","date":["العام الهجري :952","العام الميلادي :1545"],"text":"تم توقيع معاهدة بين إيران الصفوية والبرتغال، سلَّمت بموجِبها إيرانُ بسيطرةِ البرتغال على ميناء هرمز، في مقابل أن تتعهد البرتغال بالوقوفِ مع إيران ضِدَّ العثمانيين، وظلَّ حكم البرتغاليين لهرمز حتى عام 1031."},{"id":3703,"title":"وقعة وادي درنة بتادلا وأسر الأمير أبي زكريا الوطاسي ومهلكه .","date":["العام الهجري :952","الشهر القمري : رجب","العام الميلادي :1545"],"text":"حدثت وقعة وادي درنة بتادلا بين الأشراف السعديين والوطاسيين، وقد أُسِرَ فيها الأمير أبو زكريا الوطاسي، ومات في تلك الليالي القريبة غمًّا وأسفًا، وكان سلطانُ السعديين يومئذ أبا عبد الله محمد الشيخ الملقَّب بالمهدي؛ فإنَّه تغلَّب على أخيه أبي العباس أحمد الملقب بالأعرج وانتزَع منه المُلكَ وسجَنَه."},{"id":3704,"title":"استيلاء العثمانيين على تلمسان .","date":["العام الهجري :952","الشهر القمري : شعبان","العام الميلادي :1545"],"text":"استولى العثمانيون على تلمسان بقيادة حسن بن خير الدين بربروسا، وذلك في أواسط شعبان، وأخرج منها الأمير أحمد ابن الأمير عبد الله ووزيره منصور بن أبي غانم ولَحِقا بدبدو، واستمرَّت تلمسان في يد العثمانيين إلى أواسط صدر المائة الثالثة عشرة."},{"id":3705,"title":"وفاة القائد المجاهد خير الدين بربروسا  .","date":["العام الهجري :953","العام الميلادي :1546"],"text":"هو القائد العثماني خيرُ الدين خضر بن يعقوب بن يوسف أحدُ أكبرِ قادة الأساطيل العثمانية، وأحد رموزِ الجهاد البحري، لقَّبه السلطان سليم الأول بخير الدين باشا، وعُرِف لدى الأوروبيين ببربروسا، أي: ذي اللحية الحمراء، ولِدَ سنة 871 ويذكَرُ أن والده يعقوب أصلُه من بقايا الفاتحين المسلمين الأتراك الذين استقرُّوا في جزيرة مدللي إحدى جزر الأرخبيل، وأمه سيدة مسلمة أندلسية كان لها الأثرُ على أولادها في تحويل نشاطِهم شطرَ بلاد الأندلس التي كانت تئِنُّ في ذلك الوقت من بطش الإسبانِ والبرتغاليين، عاش هو وأخوه عروج في جربة التونسية، وجعلاها مركزًا لعملياتهم العسكرية في البحر المتوسط، والتصدي للقراصنة الصليبيين, فحقَّق هو وأخوه عروج باشا كثيرًا من الانتصارات ضِدَّ النصارى القراصنة، ثم تحالف خير الدين مع العثمانيين لمواصلة نشاطه الجهادي المميَّز، وقد أُعجِب به السلطان العثماني سليمان القانوني حتى عيَّنه أميرَ البحار، وخاض مع العثمانيين كثيرًا من الحروب البحرية الهامَّة، خاصةً في سواحل شمال إفريقيا والسواحل الأوروبية, ثم عُيِّنَ واليًا على الجزائر، وكان شعلةً من النشاط في القتال والجهاد البحري, فاكتسب شهرةً واسعة حتى في أوروبا التي أصبحت تخافُه, وتنسِبُ كلَّ شر يصيبها إلى خير الدين بربروسا. توفي في الجزائر."},{"id":3706,"title":"العثمانيون يصلون إلى الخليج العربي .","date":["العام الهجري :954","العام الميلادي :1547"],"text":"وجَّه الخليفة العثماني سليمان القانوني حملةً بحرية بقيادة محيي الدين بيري، مهمتُها طرد البرتغاليين من الخليج العربي، فحاصر هرمزَ التي كانت بيدِ البرتغاليين، لكنَّه فَشِلَ في الاستيلاء عليها بعد أن تكبَّد خسائر فادحة، فتوجَّه إلى البصرة ومعه ثلاث سفُنٍ فقط، وبقيَ فيها بعضَ الوقتِ، ثمَّ ذهب إلى مصر، ولَمَّا علم الخليفةُ سليمان به أمرَ بالقبض عليه وقُتل بعد ذلك في عام 961هـ."},{"id":3707,"title":"معاهدة إستانبول بين الدولة العثمانية وألمانيا .","date":["العام الهجري :954","الشهر القمري : ربيع الأول","العام الميلادي :1547"],"text":"عقدت الدولة العثمانية معاهدةَ إستانبول مع ألمانيا، اعترف الألمان بموجِبها بالفتوحات التركية في أوروبا، وقرَّرت المعاهدة أن يدفعَ الألمان ضريبةً سنوية للعثمانيين، وألَّا تُستعمل صفة إمبراطور في المكاتبات الرسمية مع الدولة العثمانية."},{"id":3708,"title":"الدولة العثمانية تعقد صلحًا مع النمسا .","date":["العام الهجري :954","الشهر القمري : ربيع الأول","العام الميلادي :1547"],"text":"وقَّعت الدولة العثمانية معاهدةَ صلحٍ في عهد السلطان سليمان القانوني مع النمسا، بقيادة ملكها فردينالد، واتَّفق الطرفان على هدنة خمس سنوات، شريطة أن يدفع ملك النمسا جزيةً سنوية مقدارها ثلاثون ألف دوكا."},{"id":3709,"title":"العثمانيون يضمون أراضي للصفويين ويدخلون تبريز للمرة الثالثة .","date":["العام الهجري :955","العام الميلادي :1548"],"text":"جاء إلى إستانبول أخو الشاه الصفوي يشكو ظلمَ أخيه له ويستنجِدُ بالخليفة سليمان القانوني، فسار الخليفةُ بجيش إلى تبريز عاصمةِ الصفويين منتزعًا كلَّ الأراضي الواقعة شمال شرقي نهر دجلة حتى بحيرة وان، ويدخل تبريز للمرة الثالثة ويفتح قلعة وان."},{"id":3710,"title":"استيلاء السلطان محمد الشيخ السعدي على مكناسة  .","date":["العام الهجري :955","العام الميلادي :1548"],"text":"لما استولى السلطان أبو عبد الله محمد الشيخ على مراكش وصَفَت له أعمالها، طَمِحت نفسُه للاستيلاء على بقيةِ بلاد المغرب وأمصاره، وقَطْعِ الوطاسيين من سائر أقطاره، فجمع الجموعَ وتقدَّم بها إلى أعمال فاس، وكان أوَّلُ ما ملك منها مكناسة الزيتون؛ فإنه افتتحها بعد حصارٍ وقتال كبير."},{"id":3711,"title":"استيلاء السلطان محمد الشيخ السعدي على مدينة فاس .","date":["العام الهجري :956","الشهر القمري : محرم","العام الميلادي :1549"],"text":"لما غلب السلطانُ محمد الشيخ السعدي على أخيه أبي العباس أحمد الأعرج، واستولى على مراكش، طَمِحَت نفسه للتوغل في بلاد المغرب وقراه، فتفرغ لحرب بني وطاس ونكَثَ ما كان بينه وبينهم من الصلح، وردَّد إليهم البعوث والسرايا وأكثَرَ فيهم من شَنِّ الغارات، وصار يستلبُهم البلادَ شيئًا فشيئًا إلى أن استولى عليها، وكان أولُ ما ملك من أمصار المغرب مكناسة الزيتون افتتحها العام الماضي, ثم تقدَّم إلى فاس فألح عليها بالقتال وضايقها بالحصار مدةً قريبة من السنة، ثم استولى عليها بعد أن أسَرَ سلطانها أبا العباس أحمد الوطاسي وصار في قبضته، ولَمَّا دخلها قبض على الوطاسيين جميعًا وبعث بهم مُصَفَّدين إلى مراكش، عدا أبا حسون أخا أبي العباس الوطاسي المخلوع؛ فإنه فرَّ إلى الجزائر."},{"id":3712,"title":"استعادة العثمانيين ترانسلفانيا .","date":["العام الهجري :957","العام الميلادي :1550"],"text":"تنازلت إيزابيلا أرملة زابولي عن ترانسلفانيا إلى فرديناند الأمير النمساوي مخالِفةً بذلك شروطَ الهدنة الموقَّعة مع العثمانيين والنمساويين، فأرسل الخليفةُ العثماني سليمانُ القانوني جيوشَه التي استطاعت أن تُعيدَ ترانسلفانيا بعد مقاومةٍ مِن قِبَل النمساويين."},{"id":3713,"title":"هدم دار الندوة بمكة .","date":["العام الهجري :957","العام الميلادي :1550"],"text":"لما تسلَّم الأمير كلدي أمير إمارة مكَّة، هدم دارَ الندوة في هذا العام, وبني مقامًا مُربَّعًا داخِلَ الحرم ذا طبقتين: الأولى للإمام والمُصلِّين، والثانية للمؤذِّنين والمبلِّغين."},{"id":3714,"title":"الغزو الإسباني على تونس .","date":["العام الهجري :957","العام الميلادي :1550"],"text":"قام الأسطول الإسباني بغزو المهدية وطَوَّق أسوارَها من البحر، وأنزل الإسبان قواتِهم إلى البر، فسارع الوالي العثماني طورغوت حاكِمُ جزيرة جربة بإرسال أسطولٍ لنجدة الحامية العثمانية بالمهدية، فقامت معركةٌ بين الأسطولين أسفرت عن هزيمةِ طوغورت وتراجُعِه، فاستولى الإسبان على المهدية، وقتلوا عددًا كبيرًا من المدافعين عنها وأسَرُوا الرجال النساء."},{"id":3715,"title":"استيلاء السلطان محمد الشيخ السعدي على تلمسان .","date":["العام الهجري :957","الشهر القمري : جمادى الأولى","العام الميلادي :1550"],"text":"لما فتح أبو عبد الله محمد الشيخ السعدي حضرة فاس، تاقت نفسُه إلى الاستيلاء على المغرب الأوسط، وكان يعزُّ عليه استيلاء الترك العثمانيين عليه، مع أنهم أجانبُ عن هذا الإقليم ودُخَلاء فيه، فيَقبُحُ بأهلِه وملوكه أن يتركوهم يغلبون على بلادِهم، لا سيما وقد فرَّ إليهم عدوٌّ من أعدائه، وهو أبو حسون الوطاسي، فرأى محمد الشيخ من الرأي وإظهار القوة في الحربِ أن يبدأَهم قبل أن يبدؤوه، فنهض من فاس قاصدًا تلمسان في جموعِه إلى أن نزل عليها وحاصرها تسعة أشهر وقُتِلَ في محاصرتها ولدُه الحران وكان نائبًا من أنيابه وسيفًا من سيوفه، ثم استولى محمد الشيخ على تلمسان ودخلها يوم الاثنين الثالث والعشرين من جمادى الأولى من هذه السنة، ونفى الترك عنها وانتشر حكمُه في أعمالها إلى وادي شلف، واتسعت خطةُ مملكته بالمغرب ودانت له البلاد، ثم كرَّت عليه الأتراك وأخرجوه من تلمسان، فعاد إلى مقرِّه فاس، ثم عاود غزو تلمسان حين بلغه قيامُ رعاياها على الترك وانحصار الترك بقصبتها، فأقام مرابطًا عليها أيامًا، فامتنعت عليه وأقلع عنها ولم يعاودْ غزوها بعد ذلك وخَلُص أمرُها إلى العثمانيين."},{"id":3716,"title":"العثمانيون يضمون ليبيا لحكمهم ويطردون فرسان القديس يوحنا .","date":["العام الهجري :958","العام الميلادي :1551"],"text":"كان العثمانيون وقائِدُهم خير الدين بربروسا وحسن الطوشي قد انشغلوا بمحاربة الأسبان في الجزائر والمغرب فترةً طويلةً من الوقت، جَعَلت فرسان القديس يوحنا (وهم بقايا الإسبتارية الصليبيين المطرودين من فلسطين ثم من قبرص ورودس سنة 928) يسيطرون على طرابلس سنة 942 بعد خروجهم من رودس بأمر البابا, واستمرَّ الحالُ حتى وفاة خير الدين بربروسا، وتمَّ تعيينُ طرغود أو «طرغوت، أو طرغول» باشا في منصب قبطان الأساطيل العثمانية. وبعد الاستغاثات التي وجَّهها سكَّان ليبيا إلى السلطان العثماني باعتباره خليفةً للمسلمين، وَضَع سنان باشا وطرغوت باشا خطةً مُحكَمةً لتحرير طرابلس من فرسان القديس يوحنا، وذلك بالهجوم البري من ناحية الشرق يقودُه والي مصر سنان باشا،وهجوم بحري يقوم به طرغود باشا بالأساطيل العثمانية من ناحية الشمال، ففرضا عليها حصارًا دام أسبوعًا واحدًا، وبحركة الكمَّاشة المحكمة استطاع العثمانيون بدعمٍ من المجاهدين الليبيين تحريرَ طرابلس في 12 شعبان سنة 958هـ، الموافق 15 أغسطس 1551م. دخلت ليبيا منذ 1551م عهدًا جديدًا، اتفق المؤرخون على تسميته بالعهد العثماني الأول، والذي انتهى سنة 1711م، عندما استقلَّ أحمد باشا القره مانلي بزمام ولاية ليبيا."},{"id":3717,"title":"استيلاء العثمانيين على جزيرة مالطة  .","date":["العام الهجري :958","الشهر القمري : جمادى الآخرة","العام الميلادي :1551"],"text":"استولى الأسطول العثماني على جزيرة مالطة، وقام بتخريبها، وكانت مالطة من القواعدِ العسكريةِ البحريةِ المزعجة للمسلمين في البحر المتوسط؛ حيث ضمَّت عددًا من الفرسان الصليبيين المتعصِّبين ضِدَّ الإسلام."},{"id":3718,"title":"تجديد المعاهدة بين العثمانيين والفرنسيين والإغارة على صقيلية .","date":["العام الهجري :959","العام الميلادي :1551"],"text":"لما هلك ملك فرنسا فرانسوا الأول خلفَه ابنه هنري الثاني الذي جدَّد المعاهدة مع العثمانيين في هذا العام, ثم أغار الطرفان على صقلية وجنوبي إيطاليا، وفتحت أساطيلُهما جزيرة كورسيكا، ثم اختلف قائدا الأسطولين فتركا الجزيرة وعاد كلٌّ منهما إلى بلده."},{"id":3719,"title":"محاولات العثمانيين استرجاع هرمز من البرتغاليين .","date":["العام الهجري :960","العام الميلادي :1552"],"text":"بعد أن فشِلت محاولة محيي الدين بيري استرجاعَ هرمز من البرتغاليين، أعاد السلطان سليمان القانوني إرسالَ حملة بحرية أخرى بقيادة مراد رئيسي، وهو من مشاهير أمراءِ البحريَّة العثمانية، ولما وصل إلى هرمز وجد أسطولًا هائلًا من البرتغاليين، فدارت بينهما معركة عنيفةٌ تكبد فيها العثمانيون خسائرَ فادحةً جدًّا، فعاد إلى البصرة، ثم جهَّز السلطان حملةً أخرى بقيادة علي جلبي الذي قاتل البرتغاليين في معركة بالقربِ من مسقط، ولكنه هزِمَ هو الآخر وتوجه عائدًا إلى السويس، ولكنَّ الرياح ألقته على ميناء سوارت بولاية كجرات فتحطَّم بعض سفنِه وباع ما سلم منها إلى محمد شاه الثالث أمير كجرات، وأقام عنده عدَّة أشهُر ثم عاد إلى بلاده."},{"id":3720,"title":"وفاة عالم الجغرافيا والبحار أحمد محيي الدين الريس العثماني .","date":["العام الهجري :960","العام الميلادي :1552"],"text":"هو عالمُ الجغرافيا والبِحار العثماني أحمد محيي الدين الريس (بيري ريس بالتركية) ولِدَ سنة 871, في مدينة غاليبولي غرب إسطنبول، على الجانب الأوروبي من بحر مرمرة، وكانت هذه المدينة بمثابة المركز الرئيسي للقوات البحرية العثمانية, وهو أبرز القادةِ البحريين في الأسطول العثماني وراسِمُ الخرائط. في الوقت الذي استطاع البحَّارة العثمانيون آنذاك أن يصلوا إلى المحيط الأطلسي ويبلغوا بحر الهند، ورسموا خرائِطَ السواحل المحيط الهندي وأمريكا الشمالية والقطب الجنوبي، كان بيري ريس هو أوَّلَ من برز في هذا المجال، وخرائطُه التي اكُتشفت في قصر الباب العالي سنة 1929 حيَّرَت كثيرًا من علماء البحار والخرائط؛ كيف تمكَّن في تلك الفترة بين القرنين الخامس عشر والسادس عشر أن يصِلَ إلى هذه الدقة في رسم حدود سواحل إفريقيا وأمريكا، ويدلِّلُ بعضهم على أنَّ هذا التفوق يدُلُّ على مدى تطوُّر وضخامة الأساطيل العثمانية التي كانت تجوبُ بحارَ ومحيطات العالم آنذاك، وكثرة فِرَق العمل والعلماء الذين كانوا يعملون بجانب هذه الأساطيل."},{"id":3721,"title":"توقيع الدولة العثمانية معاهدة إستانبول مع فرنسا .","date":["العام الهجري :960","الشهر القمري : صفر","العام الميلادي :1553"],"text":"اعترف ملك فرنسا هنري الثاني في معاهدة إستانبول بالسلطان العثماني كإمبراطور أوروبا الأوحد، ووضع الأسطولَ الفرنسيَّ رهْنَ الدولة العثمانية في مقابِلِ تقديم تركيا مساعداتٍ بحريةً لفرنسا، وأن تترك فرنسا أسطولها لتركيا في حالة عدمِ تسديدها مصاريفَ الحملة البحرية العثمانية."},{"id":3722,"title":"استيلاء العثمانيين على جزيرة كوريكا ومدينة كاتانيا في صقلية .","date":["العام الهجري :960","الشهر القمري : رمضان","العام الميلادي :1553"],"text":"استولى القائدُ البحري العثماني طرغد بك على جزيرة كوريكا ومدينة كاتانيا في صقلية بعد إبادتِه لحاميتها، وتخليصِه لسبعة آلاف أسيرٍ مسلم، ثم قام بتسليم كوريكا للفرنسيين الذين لم يستطيعوا الاحتفاظَ بها طويلًا أمام الإسبان الذين سيطروا عليها في نفس العامِ!"},{"id":3723,"title":"قيام دولة السعديين بالمغرب الأقصى .","date":["العام الهجري :961","العام الميلادي :1553"],"text":"بعد أن استولى السعديون على فاس سنة 956هـ ثم قام العثمانيون بطردهم وإعادة الوطاسيين، ثم ترك العثمانيون فاس وعادوا إلى الجزائر؛ واجه أبو حسون منافسةَ محمد الشيخ السعدي الذي جمع قواتٍ من السوس والحوز وأتى بجنوده إلى أن وصل رأس الماء من أحواز فاس، وكان أبو حسون بعد انسحاب العثمانيين قد أخذ في إعداد الجيوشِ وآلات الحرب إلى أن قضت ثمانية شهور، فأمر بالخروج لمواجهة محمد الشيخ السعدي والوصول إلى مراكش، ولما تقابل الجيشان قام بينهم قتالٌ عظيم واستطاع أبو حسون أن ينزل بالسعديين هزيمةً شنيعة حتى استطاع أن يردَّهم على أعقابهم، ثم أرسل أبو حسون لمحمد الشيخ وقال له: اخرج أنت وأولادك إلى لقائي، وأنا أخرج إليكم بنفسي، ونترك المسلمين بدون قتال، فتظاهر محمدٌ ورجع إلى والده وإخوته الستة الذين اجتمعوا على أبي حسون فجعل يطاردهم حتى طمر به فرسُه فسقط فطعنوه فاحتزُّوا رأسه وأتوا به جيشَه، فانهزم جيشُ أبي حسون بلا قتال، وأخذ محمد الشيخ فاس، فكانت أحداث هذه الوقائع تعني أن الفرصةَ ما زالت واسعة أمام العثمانيين لاستيلائهم المحلِّي للمغرب، لا سيما وأن محمد الشيخ السعدي باسمِ القضاء على الحزب العثماني بين المغاربة أنزل القتلَ في أكثر من مائتين من كبار أعيان فاس، فضلًا عن الفقيهين المرينيين محمد عبد الوهاب الزقاق قاضي فاس، والحسن علي حزوز خطيب فاس."},{"id":3724,"title":"وفاة الأمير الشريف أحمد بن أبي نمي  .","date":["العام الهجري :961","العام الميلادي :1553"],"text":"هو الأميرُ الشريف أحمد بن أبي نمي محمد الثاني بن بركات الثاني شريف حسني جدِّ آل منديل وآل حراز، وهو صاحِبُ مكة، وكان هو الذي دعس بساطَ السلطان سليمان القانوني ولم يدعَسْه غيره من أمراء مكَّة، أرسله أبوه إليه سنة 945 واجتمع به، ولما عاد إلى مكة توفِّيَ بها في حياة أبيه، ولم يلِ الإمارةَ استقلالًا, وكانت شوكتُه قد استقرَّت في حياة أبيه."},{"id":3725,"title":"قيام الدولة الثانية للسلطان أبي حسون الوطاسي .","date":["العام الهجري :961","الشهر القمري : صفر","العام الميلادي :1554"],"text":"لما دخل السلطان أبو عبد الله محمد الشيخ السعدي إلى فاس سنة 956 وقبض على بني وطاس بها، فرَّ أبو حسون- أخو السلطان أبي العباس أحمد الوطاسي- إلى ثغر الجزائر حقنًا لدمه ومستعينًا بالعثمانيين على السعدي، وكان العثمانيون قد استولوا على المغرب الأوسط وانتزعوه من يد بني زيان، فلم يزل أبو حسون عندهم يفتلُ لهم في الغارات والسنام ويحسِّنُ لهم بلاد المغرب الأقصى ويعظِّمُها في أعينهم ويقول: \"إن المتغلِّبَ عليها قد سلبني ملكي ومُلك آبائي، وغلبني على تراث أجدادي، فلو ذهبتم معي لقتاله لكنَّا نرجو الله تعالى أن يتيحَ لنا النصر عليه ويرزُقَنا الظَّفَر به ولا تعدِمونَ أنتم مع ذلك منفعةً مِن ملء أيديكم غنائِمَ وذخائِرَ\". ووعدهم بمال جزيل فأجابوه إلى ما طلب وأقبلوا معه في جيشٍ كثيف تحت راية الباشا صالح التركماني المعروف بصالح رئيس، إلى أن اقتحموا حضرةَ فاس بعد حروب عظيمة ومعاركَ شديدة، وفَرَّ عنها محمد الشيخ السعدي إلى منجاتِه، وكان دخول السلطان أبو حسون إلى فاس ثالثَ صفر من هذه السنة, ولما دخلَها فرح به أهلُها فرحًا شديدًا، وترجل هو عن فرسه وصار يعانقُ الناس؛ كبيرًا وصغيرًا، شريفًا ووضيعًا، ويبكي على ما دهمَه وأهلَ بيته من أمر السعديين، واستبشر الناسُ بمقدَمِه وتيمَّنوا بطلعتِه، وقُبض على كبير فاس يومئذ القائد أبي عبد الله محمد بن راشد الشريف الإدريسي, واطمأنت بالسلطان أبي حسون الدارُ، ثم لم يلبث إلا يسيرًا حتى كثرت شكايةُ الناس إليه بالترك وأنهم مدُّوا أيديَهم إلى الحريم وعاثوا في البلاد، فبادر أبو حسون بدفع ما اتَّفق مع الترك عليه من المال وأخرجَهم عن فاس."},{"id":3726,"title":"نشوب حرب بحرية بين الأسطولين العثماني والبرتغالي .","date":["العام الهجري :961","الشهر القمري : رمضان","العام الميلادي :1554"],"text":"نشبت حربٌ بحرية طاحنة بين الأسطولين العثماني والبرتغالي في مضيق هرمز بالخليج العربي, واستمرت الحرب 18 ساعة بدون توقُّف، ولم تؤدِّ إلى نصرٍ حاسمٍ لأحد الفريقين."},{"id":3727,"title":"استيلاء السلطان محمد الشيخ السعدي على مدينة فاس .","date":["العام الهجري :961","الشهر القمري : شوال","العام الميلادي :1554"],"text":"لما فرَّ السلطان محمد الشيخ السعدي من وقعة الأتراك بفاس وصل إلى مراكش، فاستقَرَّ بها وصرف عزمَه لقتال أبي حسون، فأخذ في استنفار القبائل وانتخاب الأبطال وتعبئة العساكر والأجناد، فاجتمع له من ذلك ما اشتدَّ به أزْرُه وقويَ به عَضدُه، ثم نهض بهم إلى فاس، فخرج إليه السلطان أبو حسون في رُماة فاس وما انضاف إليهم من جيش العرب، فكانت الهزيمة على أبي حسون فرجع إلى فاس وتحصَّن بها، فتقدم الشيخ السعدي وحاصره إلى أن ظفِرَ به في وقعة كانت بينهما بالموضع المعروف بمسلمة، فقتله واستولى على حضرة فاس وصفا له أمرُها، وكان استيلاؤه عليها يوم السبت الرابع والعشرين من شوال من هذه السنة, وبمقتل السلطان أبي حسون انقَرَضت دولة الوطاسيين المرينيين بالمغرب."},{"id":3728,"title":"معاهدة بين السعديين بالمغرب الأقصى والبرتغاليين .","date":["العام الهجري :962","العام الميلادي :1554"],"text":"بعد عودة فاس للسعديين ظهر السلطان محمد الشيخ السعدي كخصم عنيد للعثمانيين، ومن المعارضين لسياستهم التوسعيَّةِ في بلاد المغرب، بل والأكثر من ذلك أنه أعلن إثرَ دخوله فاس بأنه عازمٌ على الذهاب إلى الجزائر لمنازلة العثمانيين هناك، فهذا التنافسُ السعديُّ العثماني على شمال إفريقيا، بل وعلى الخلافةِ الإسلامية كان في صالحِ الإسبان والبرتغال، ولا عجب إذا رأينا بعد ذلك تقاربًا بين هؤلاء جميعًا ضد العثمانيين حيث بعث الملك البرتغالي جون الثالث رسالةً إلى حاكم مازكان البرتغالي الفارودي كالفولو ردًّا على الطلب الذي تقدم به السلطانُ محمد الشيخ إلى كلٍّ من مدريد ولشبونة لتزويده بقوات عسكرية ضد العثمانيين، كما حددت الرسالةُ بعض الشروط التي يراها البرتغاليون لمساعدة السعديين، كتسليم بعض المراكز البحرية المغربية، مثل: بادس بنيون والعرائش، بالإضافة إلى تموين القوات التي سيرسلها لمساعدته، وأخيرًا يختتمُ الملك جون الثالث بضرورة إخبار الإمبراطور الإسباني بذلك للتنسيق في عمل مشترك ضِدَّ العثمانيين؛ ونتيجة لهذا التقارب فقد عُقِدت هدنةٌ بين السعديين والبرتغال بواسطة حاكم مازكان لمدة ستة أشهر, وظلَّ مفعول هذه الهدنة زمنًا طويلًا."},{"id":3729,"title":"معاهدة أماسيا بين العثمانيين والصفويين .","date":["العام الهجري :962","الشهر القمري : جمادى الآخرة","العام الميلادي :1555"],"text":"عُقِدت معاهدة أماسيا بين الخليفة سليمان القانوني والدولة الصفوية بإيران؛ لتثبيت الحدود بين الدولتين، بموجِبِها ضُمَّت كل الأراضي الواقعة شمالَ شرق نهر دجلة حتى بحيرة وان إلى الدولة العثمانية كما استقرت عام 955، وبموجِب هذه المعاهدة تخلى الصفويون عن حقوقِهم بالعراق، واعتَرَفوا بها على أنَّها جزءٌ من الدولة العثمانية."},{"id":3730,"title":"العثمانيون يسيطرون على المغرب الأقصى .","date":["العام الهجري :963","العام الميلادي :1555"],"text":"نتيجةً لتحالف السعديين مع الإسبان والبرتغال ضِدَّ العثمانيين تحَّركت القوات العثمانية تحت قيادةِ صالح رايس والي الجزائر من قِبَل العثمانيين للوقوف مع أبي حسون الوطاسي وحصلت اصطدامات عسكرية بين قوات محمد الشيخ السعدي والقوات العثمانية قرب بادس التي رسا بها الأسطول العثماني، فلحقت الهزيمة بالقوات السعدية؛ مما أفسح المجالَ أمام العثمانيين لكي يواصلوا زحفهم نحو الداخل، وفي هذا العام سقطت مدينة تازة في يد العثمانيين الذين اشتبكوا مع السعديين في معاركَ متواصلة أهمُّها بكدية المخالي في ساحة فاس، عند ذلك تقدَّمت القوات العثمانية ومعها أبو حسون نحو فاس التي دخلتها في 3 صفر سنة 964, وأعلن الباب العالي ضمَّ المغرب إلى الدولة العثمانية بعد أن خطب الإمام للسلطان العثماني، مكث صالح رايس بمدينة فاس أربعة أشهر ضَمِن خلالها استقرار الأمور للدولة العثمانية، وخلال وجود صالح رايس في فاس لم يترك الجهادَ ضِدَّ الإسبان فأرسل فرقة من جيشه إلى الريف المغربي استرجع من الإسبان مَعقِلَهم الكبير باديس أو صخرة فالين كما يَدْعونها، كما حاول صالح رايس أن يستبدل الباشا العثماني أبا حسون بالشريف الإدريسي الراشدي بوبكر، بناء على اقتراح المرابطين الصوفيين للقيامِ على حكم فاس باسم السلطان العثماني، إلا أنَّ ثورة الأهالي اضطرَّت صالح رايس لإعادة أبي حسون إلى حكم فاس، فأذعن أبو حسون لشروط العثمانيين بشأنِ الحفاظِ على السيادة العثمانية من حيث الخطبةُ باسم السلطان العثماني، وإقامةُ حاميةٍ عثمانية في مقَرِّ بلاطه."},{"id":3731,"title":"انتزاع بجاية من يد الإسبان .","date":["العام الهجري :963","العام الميلادي :1555"],"text":"لم يكن صالح رايس والي الجزائر يهتمُّ قبل كلِّ شيء إلا بمحاربة الإسبان، ولا يهدفُ من وراء أي عملٍ إلَّا جمعَ القوى الإسلامية من أجلِ تطهير البلاد من الوجودِ الأوروبي الصليبي، فكان يرى قبل كل شيءٍ وجوبَ طردِ الإسبانِ مِن وهران، لكن كيف يتسنَّى له ذلك وسلطانُ السعديين بالمغرب يترقَّبُ به الفُرَص، وسلطانُ قلعة بني عباس ببلاد مجانة يُعلنُ انفصاله واستقلاله، ترامت لصالح رايس يومئذٍ الأنباءُ عن ضعفِ القوى الإسبانية بمدينة مجانة، علاوةً عن معاناةِ الحامية بالضيقِ، فرأى صالح أن يغتنمَ الفرصةَ وأن يبدأ بتطهير الشرقِ من الإسبان قبل أن يُطهِّرَ الغربَ، ولعلَّ انقاذ بجاية سيكون له أثرٌ في عودة مُلك بجاية إلى حظيرة الوحدةِ الإسلامية تحت ضغطِ السكَّان، سار صالح رايس في ربيع أول من هذه السنة نحو مدينة بجاية على رأسِ قوةٍ كبيرةٍ بنحو ثلاثين ألف رجلٍ عزَّزهم في الطريقِ بالمجاهدين في إمارةِ كوكو، فوطَّدت الجيوشَ العثمانية وحاصروا المدينة، بينما جاء الأسطولُ العثماني يحمِلُ الأسلحة والمدافِعَ بجانب الجيشِ، وصوَّب المسلمون قذائفَهم على القلعة ودارت معركةٌ عنيفة، ونجح صالح رايس في انتزاعِ بجاية من الإسبان, ولم يستطع حاكم نابولي من نجدةِ حاكمِها في الوقتِ المناسب، كما استسلم الحاكِمُ الإسباني للقوَّات العثمانية."},{"id":3732,"title":"محاولة العثمانيين انتزاع وهران من سيطرة الإسبان .","date":["العام الهجري :963","العام الميلادي :1555"],"text":"أُطلِعَ صالح رايس- والي الجزائر من قِبَل العثمانيين- على تلك المؤامرةِ التي كانت تُحاك ضِدَّ الدولة العثمانية بين ملكِ المغرب السلطانِ الشيخ المهدي أبي عبد الله محمد السعدي والإسبان، والتي كان هدفُها طردَ العثمانيين من الجزائر؛ لأنَّه طالما أن الدولة في الجزائر معناه خطرٌ على إسبانيا، فبعث صالح رايس للباب العالي يخبرُه بشأن تلك المحادثات، فكان جوابُ السلطان سليمان سريعًا وحاسمًا بوجوبِ مهاجمة وهران قبل أن تسفِرَ المحادثات بين الجانبين السعدي والإسباني عن نتيجةٍ عملية، فأرسل السلطانُ سليمان أربعين سفينة لمساعدة رايس في الاستيلاءِ على وهران والمرسى الكبير، ومنذ ذلك الوقت كانت الهجرةُ والتجنيدُ الطوعي من مختلِفِ أنحاء الدولة العثمانية، فاستعَدَّ صالح رايس لفتح وهران، وضَمَّ أسطوله الى جانب أسطول السلطان، وصار لديه نحو سبعين سفينة، واجتمع لديه من الجند ما يقارب من أربعين ألف جندي، وكان ينوي من إتمام زحفه هذا بالمسير الى مراكش للقضاء على الفِتَن والاضطرابات وإخضاعها لسلطانه، ولكن القَدَر لم يمهِلْه، فتوفِّي صالح رايس بالطاعون في شهر رجب 963هـ وقام القائد يحيى بإكمال خطة صالح رايس، فأبحر نحو وهران، وفي الطريق وصلت الأوامر السلطانية بتعيين حسن قورصو لمنصب بيلرباي، ووصلت الجيوش البرية والبحرية إلى وهران، وحوصرت حصارًا شديدًا، إلَّا أنها لم تُفتحْ رغم استعدادات العثمانيين الكبيرة؛ وذلك بسبب النجدات المتواصلة التي كانت تبعثُها إسبانيا إلى المدينة المحاصَرة."},{"id":3733,"title":"وفاة القائد أمير البحر صالح رايس .","date":["العام الهجري :963","العام الميلادي :1555"],"text":"هو القائدُ أمير البحر صالح رايس، ويقال (ريس)، قائدُ البحرية العثمانية في البحر المتوسط, وهو عربيٌّ من الإسكندرية، ولد فيها سنة 893 تعرَّف على الأتراك حين قدِموا إلى مصر، ورافق أميرَ البحار خير الدين بربروسا في رَحَلاته البحرية, ومن أهمِّ أعمال رايس أنَّه ساهم في إنقاذ بقايا المسلمين في الأندلس، وقد تولى منصِبَ حاكم الجزائر عام 1552م. كان صالح رايس يهتم كثيرًا بمحاربة الإسبان، ويهدف من ورائه جمعَ قوى المسلمين من أجل تطهير بلاد المغرب من الوجود الصليبي فيها؛ لذا كان يرى قبل النزولِ إلى الأندلس لاستردادها وجوبَ طرد الإسبانِ من وهران، فعَمِلَ على إتمام فتح بجاية فدَكَّ الحصون التي يتحصَّن بها الإسبان، ثم هزَمَهم واسترَدَّ بجاية منهم, واحتفظ بها العثمانيون قرابة 188 سنة, ثم بدأ بالاستعداد لفتح مدينة وهران، لكنَّ الأجل أدركه أثناء استعداداته لفتحِها, فتوفِّي بالطاعون عن عمر سبعين سنة."},{"id":3734,"title":"وفاة السلطان الشيخ المهدي محمد بن محمد السعدي .","date":["العام الهجري :964","العام الميلادي :1556"],"text":"هو محمد بن محمد بن محمد بن عبد الرحمن بن زيدان الحسني، أبو عبد الله، المعروف بالشيخ، والملقب بالسلطان المهدي: ثالثُ سلاطين الدولة السعدية بالسوس ومراكش. ولِدَ سنة 896. كان مع أبيه القائمِ بأمر الله في بدء ظهورِه، ثم كان مع أخيه أحمد الأعرج، وكانت كلمتُهما واحدة مدة 23 عامًا، ثم افترقت كلمتُهما، فقام محمد بخلع أخيه أحمد والقبض عليه وعلى أولاده سنة 946، واجتمعت الكلمة عليه، فباشر الجهادَ في الثغور، فافتتح حصنَ فونتي وآسفي، واختط مرسى أغادير بالسوس الأقصى سنة 947, ثم ضمَّ مراكش سنة 951 فانتقل إليها. وبعدها طمِحَت نفسه للاستيلاء على بقية المغرب والقضاء على الوطاسيين أصحابِ فاس وأطرافِها، فافتتح مكناسة الزيتون سنة 956, وقبض على أكثَرَ مَن بها من الوطاسيين وأرسلَهم مُصفَّدين إلى مراكش. وقاتل العثمانيين في تلمسان وكانوا قد استولوا عليها، فأخذها منهم، ثم امتنعوا عليه بها. وكانت قد بقيت بفاس طائفةٌ من الترك العثمانيين الذين أحضرهم أبو حسون الوطاسي، فجعلهم الشيخ المهدي جندًا على حِدَة وسمَّاهم اليشكارية- العسكر الجديد- وأرسل له السلطانُ سليمان القانوني يهنِّئُه بالمُلك ويطلب منه الدعاء له على منابر المغرب وأن يكتُبَ اسمَه على سكَّته، فرفض طلبه، ثم أرسل السلطانُ سليمان أشخاصًا اتصلوا باليشكارية فتربَّصوا الشيخ المهدي حتى قتلوه غيلةً, وكان من عظماء الرِّجال؛ مهيبًا، غزير العلم، عُنِيَ بالتفسير، وحفظ صحيح البخاري وديوانَ المتنبي."},{"id":3735,"title":"وقوع وباء عظيم بالمغرب .","date":["العام الهجري :965","العام الميلادي :1557"],"text":"كسا هذا الوباءُ سهلَ المغرب وجبالَه، وأفنى كُماتَه وأبطالَه، واستمَرَّ وجوده إلى سنة ست وستين بعدها."},{"id":3736,"title":"مبايعة أهل فاس ومراكش للسلطان عبد الله السعدي .","date":["العام الهجري :965","الشهر القمري : محرم","العام الميلادي :1557"],"text":"تولَّى السلطانُ الغالب بالله الحُكمَ، وذلك بعد مقتل أبيه ومبايعةِ أهل فاس له وأهلِ مراكش، فاستوثق له الأمرُ وتمهَّد له ملك أبيه. وكان قد نشأ في عفافٍ وصيانة، وحَفِظَ القرآن وأخذ بطرفٍ صالحٍ من العلم، وكان وليَّ عهد أبيه، وكان يلقَّب من الألقاب السلطانية بالغالب بالله، لقَّبَه به غيرُ واحد من الأئمةِ."},{"id":3737,"title":"هزيمة حسن بن خير الدين التركي من السلطان الغالب بالله .","date":["العام الهجري :965","الشهر القمري : جمادى الأولى","العام الميلادي :1558"],"text":"لَمَّا ولِيَ السلطان أبو محمد عبد الله الغالب بالله الخلافةَ، اشتغل بتأسيس ما بيده وتحصينِه بالعَدَد والعُدَّة، ولم تطمح نفسه إلى الزيادة على ما ملك أبوه من قَبلِه. وغزاه حسن بن خير الدين باشا التركي صاحبُ تلمسان في جيشٍ كثيفٍ من الأتراك، فخرج إليه السلطان الغالب بالله فالتقيا بمقربةٍ من وادي اللبن من عمالة فاس، فكانت الدائرة على حَسنٍ، فرجع منهزمًا يطلب صياصيَ الجبال إلى أن بلغ إلى باديس، وكانت يومئذ للترك ورجع الغالب بالله إلى فاس، لكنَّه لم يدخلها لوباءٍ كان بها يومئذ."},{"id":3738,"title":"معركة مستغانم بين العثمانيين والإسبان  .","date":["العام الهجري :965","الشهر القمري : ذي القعدة","العام الميلادي :1558"],"text":"حقَّق القائد العثماني الشهير حسن باشا بن بربروسا انتصارًا كبيرًا على النصارى الإسبان في معركة \"مستغانم\" بالجزائر؛ حيث قُتل في هذه المعركة 12 ألفًا من الإسبان، وتشتهرُ هذه المعركة في التاريخ بأنَّه لم يبقَ فيها جندي إسباني على قيدِ الحياة، حيث تمَّ إفناءُ الجيش الإسباني عن بَكرة أبيه. وكان سببُها أن حاكم وهران دو الكوديت كان يدركُ أنَّ استرجاع العثمانيين لتلمسان يهدِّدُ الوجود الإسباني تهديدًا خطيرًا، فقرَّر الاستيلاءَ على مستغانم التي جعلها العثمانيون قاعدةً لهم للهجومِ على وهران، وكان دو الكوديت يأملُ أن يجعَلَها قاعدةً للهجوم على الجزائر؛ لذلك أعدَّ قوة كبيرة تتكون من اثني عشر ألف مقاتل وخرج على رأسها فهاجم مدينة مستغانم، إلَّا أن محاولته باءت بالفشل، وكان حاكم وهران الكوديت من بين هؤلاء القتلى."},{"id":3739,"title":"نشوب حرب قونية الميدانية .","date":["العام الهجري :966","الشهر القمري : رمضان","العام الميلادي :1559"],"text":"نشبت حرب قونيَّة الميدانية بين السلطان سليمان القانوني وأخيه بايزيد حولَ أمور متعلِّقة بولاية العهدِ في الدولة العثمانية، وقد هُزِمَ بايزيد وهَرَب إلى الدولة الصفويَّة المعادية للعثمانيين، إلَّا أن الصفويين ما لبثوا أن قتلوه بناءً على طلبٍ مِن سليمان القانوني."},{"id":3740,"title":"استيلاء الإسبان على جزيرة جربة .","date":["العام الهجري :967","الشهر القمري : شعبان","العام الميلادي :1560"],"text":"استولى الأسطول الإسباني الضخم المكوَّن من 200 سفينة و30 ألف جندي، على جزيرة جربة التونسية وقلعتِها، بعد انسحاب الحاميةِ العثمانية منها، والتي تقدَّر بألف رجل."},{"id":3741,"title":"انتصار الأسطول العثماني على الأسطول الإسباني في معركة جربا .","date":["العام الهجري :967","الشهر القمري : شعبان","العام الميلادي :1560"],"text":"انتصر الأسطولُ العثماني بقيادة طرغد باشا على الأسطول الإسباني الصليبي في معركة \"جربا\" قرب تونس، في واحدة من كبرى المعارك البحرية في التاريخ العالمي في تلك الفترة، وقُتِلَ أكثرُ من ثلثي بحَّارة الأسطول الإسباني، في حين لم يسقُط من العثمانيين سوى ألف."},{"id":3742,"title":"حرب بحرية بين أسطول العثمانيين وأساطيل أوروبية .","date":["العام الهجري :967","الشهر القمري : رمضان","العام الميلادي :1560"],"text":"أمير البحر العثماني طورغوت يستولي على جزيرة جربة بعد معركةٍ جرت قبلها في شهر رمضان من هذا العام، هزمت فيها أساطيل جنوة وفلورنسا وصقلية ومالطة وإسبانيا، وتوغَّل طوغورت بعد ذلك في الداخل، فاستولى على مدُنِ قفصة وصفاقس والموناستير والقيروان وسوسة، وكان الأعرابُ الشابية قد استولوا عليها فحرَّرها منهم وانتقلت إلى الدولة العثمانية."},{"id":3743,"title":"استيلاء القائد العثماني طرغد باشا على قلعة جربا في تونس .","date":["العام الهجري :967","الشهر القمري : ذي القعدة","العام الميلادي :1560"],"text":"كانت هذه القلعة سابقًا خاضعة للإسبان، واستولى العثمانيون عليها بعد حصار دام 63 يومًا، وقد أطلقوا فيها نحو 12 ألف طلقة مدفعٍ على القلعة، وقُتل من الإسبان 8800 جندي، ومن العثمانيين ألف."},{"id":3744,"title":"وفاة طاش كبري زاده .","date":["العام الهجري :968","العام الميلادي :1560"],"text":"أحمد بن مصطفى بن خليل المعروف بطاش كبري زاده، من مشاهير الموسوعيين الأتراك وكُتَّاب السِّيَر، ولد في بروصا  عام 901هـ ثم انتقل إلى أنقرة ثم إستانبول، قرأ الفقه والنحو والصرف، وتولى قضاءَ حلب، ويعتبَرُ من المصنِّفين في الموسوعات، فكتابه: مفتاح السعادة ومصباح السيادة، يعتبر ذخيرةً للتعريف بكثيرٍ من العلوم، وله كتابٌ في السير هو: الشقائق النعمانية فيه سيرة شيوخ الطرق، وله العقدُ المنظوم في ذكر أفاضل الروم، وله مؤلَّفٌ في البحث والمناظرة، وله نوادر الأخبار في مناقب الأخيار."},{"id":3745,"title":"وفاة القائد البحري الإسباني دوريا .","date":["العام الهجري :968","الشهر القمري : جمادى الأولى","العام الميلادي :1561"],"text":"توفِّيَ القائد البحري الإسباني الشهير \"أندريا دوريا\"، كان قد خاض العديدَ من المعارك ضِدَّ المسلمين العثمانيين، وكان النصرُ فيها سِجالًا، وتوفِّيَ بعد انتصار العثمانيين في معركة \"جربا\" البحرية."},{"id":3746,"title":"وفاة الأمير بايزيد ابن السلطان سليمان القانوني  .","date":["العام الهجري :969","العام الميلادي :1561"],"text":"هو الأمير بايزيد (بالتركية شاهزاده بايزيد) بن سليمان بن سليم الأول بن بايزيد الثاني بن محمد الفاتح, هو الابنُ الرابع من أبناء سليمان القانوني، والابن الثالث من زوجته الثانية روكسلان. قاد جيشًا متمردًا على الدولة اعتراضًا على ولاية العهد لأخيه سليم الثاني الذي يصغُرُه بسنة ونصف، فهُزم في معركة قونية الميدان سنة 966, فاضطرَّ بايزيد أن يلجأ لإيران عند شاه, ولكن بموجب المعاهدة بين الطرفين قام الشاه طهماسب الصفوي بتسليم بايزيد وأبنائه مقابل مال دُفع له أيضًا، فقام سليمان القانوني بقتل ولده بايزيد وقَتَل معه أبناءَه الخمسة في قزوين, وكان بايزيد يبلُغُ من العمر سبعًا وثلاثين سنة!!"},{"id":3747,"title":"السلطان العثماني سليمان القانوني وولاية العهد .","date":["العام الهجري :969","العام الميلادي :1561"],"text":"كان القانوني قد قتل سابقًا ابنه مصطفى بدسيسة من زوجته روكسلانا الروسية؛ ليتولى ابنُها سليم الخلافة، بل سعت أيضًا لقتل ابن مصطفى الذي لا يزال رضيعًا، وعَهِدَ بالخلافةِ لابنه سليم دون الأكبر بايزيد الذي ثار على أبيه، فأرسل إليه جيشًا فهزمه، فاضطر بايزيد للُّجوء إلى بلاد فارس عند الصفويين، فلما استردَّه سليمان القانوني ثم قتله، صفت ولاية العهد لسليم بن سليمان."},{"id":3748,"title":"فتح السعديين مدينة شفشاون بالمغرب وانقراض أمر بني راشد منها .","date":["العام الهجري :969","الشهر القمري : صفر","العام الميلادي :1561"],"text":"لما توفِّيَ الأمير أبو الحسن علي بن موسى بن راشد مختطُّ مدينة شفشاون في شمال المغرب، وبقِيَت بيد أولاده يتولَّون رياستها ولم يزالوا فيها بين سِلمٍ وحرب إلى أن حاصرهم بها الوزير أبو عبد الله محمد بن عبد القادر ابن السلطان محمد الشيخ السعدي بجيوشِ عَمِّه السلطان أبي محمد عبد الله الغالب بالله، وصاحب شفشاون يومئذ الأمير الفاضل أبو عبد الله محمد ابن الأمير أبي الحسن علي بن موسى بن راشد، فلمَّا اشتَدَّ عليه الحصارُ خرج فيمن إليه من أهله وولده وقرابته، وصعدوا الجبلَ المطِلَّ على شفشاون، وذلك ليلة الجمعة الثاني من صفر من هذه السنة، وساروا إلى ترغة، فركبوا منها البحر يوم الجمعة تاسِعَ من هذا الشهر واستقَرَّ الأمير أبو عبد الله بالمدينة النبوية إلى أن مات بها."},{"id":3749,"title":"حدوث سيل عظيم هائل بحضرموت (سيل الإكليل)  .","date":["العام الهجري :970","الشهر القمري : شوال","العام الميلادي :1563"],"text":"حدث سيلٌ عظيم هائل بحضرموت لم يُسمَع بمثله، أتلف كثيرًا من النخيل, وأهلُ تلك الجهة يذكرونه، ويؤرِّخون به، وهو المسمى عندهم (سيل الإكليل) ويقال إنه وقع في قديم الزمان سيلٌ مثلُه أو قريبٌ منه."},{"id":3750,"title":"محاولة الإسبان احتلال جزيرة باديس .","date":["العام الهجري :971","العام الميلادي :1563"],"text":"بدأ فيليب الثاني يستعدُّ لاحتلال جزيرة باديس، وشجَّعه على ذلك النصرُ الذي حقَّقه في وهران، فوجَّه لذلك أسطولًا في هذه السَّنة, فقاومه المجاهدون مقاومةً عنيفةً، واضطرَّ الأسطول إلى التراجع, والجديرُ بالذكر أنَّ جزيرة باديس كانت أقربَ نقطة مغربية إلى جبل طارق، وأنَّها كانت بالنسبة للمجاهدين ميناءً هامًّا؛ إذ يمكِنُهم من خلالها العبور للأندلس، كما يمكِنُهم التسلل لداخل الأراضي الإسبانية؛ لتقديم المساعدة للمسلمين هناك، والذين أطلقوا على أنفُسِهم الغرباء، وهذا ما دفع الإسبانيين إلى الهجوم عليها من خلال محاولتهم السابقة، كما كانت جزيرة باديس بالإضافة إلى ذلك مثارَ رعب وخوفٍ لدى السلطان السعدي الغالب بالله؛ إذ خاف السلطان أن يخرجَ الأسطول العثماني من تلك الجزيرة إلى المغرب، فاتَّفق مع الإسبان أن يخلِّيَ لهم الأدالة من حجرة باديس ويبيع لهم البلاد ويُخلِّيها من المسلمين، وينقطع أسطولُ العثمانيين في تلك الناحية، مقابِلَ الدفاع عن شواطئ المغرب إذا هاجمها الأسطول العثماني الذي علِمَ بتلك المؤامرة، فانسحب ورجع إلى الجزائر، كما عزل بويحيى رايس من منصبه في باديس في أواخر هذا العام, وانصرف العثمانيون عن الحرب في غرب البحر المتوسط؛ إذ توجَّه نشاط الأسطول الحربي إلى جزيرة مالطة في الشرق."},{"id":3751,"title":"محاولة استرجاع وهران من الإسبان .","date":["العام الهجري :971","العام الميلادي :1563"],"text":"خرج حسن بن خير الدين بربروسا في هذه السنة من مدينة الجزائر نحو الغرب، يقودُ جيشًا كبيرًا مؤلفًا من خمسة عشر ألف رجل من رماة البندقية، وألف فارس من الصباحية، تحت إمرة أحمد مقرن الزواوي، واثني عشر ألف رجل من زواوة وبني عباس، أما مؤَنُ وذخيرة الجيش فقد حملها الأسطولُ العثماني إلى مدينة مستغانم التي اتخذَها قاعدة للعمليات، وفي 13 أبريل وصل حسن خير الدين بكامل قوَّته أمام مدينة وهران، وضرب حصارًا حولها، وكان الإسبان مستعدِّين لتلقي الصدمة وراء حصونِهم وقلاعهم، بعد أن توالت النجدات الإسبانية والبرتغالية على وهران؛ استجابة لنداء حاكمها، ومنذ أن صارت القواتُ العثمانية على مسافة مرحلتين وبينهما، كان البيلربك نفسه على بعد ست مراحل؛ مما اضطر حسن بن خير الدين إلى رفع الحصار قبل وصول المزيد من هذه النجدات التي اتخذت من مالطة مركزًا لتجمُّعها، وهكذا لم يستطع حسن بن خير الدين تحقيق هدفه ذلك؛ لأن فيليب الثاني كان قد وضع برنامجًا طموحًا للأسطول الإسباني، والبناء البحري في ترسانات إيطاليا وقطالونيا، كما وردت لخزانة إسبانيا إعانةٌ من البابوية، واجتمعت سلطة قشتالة التشريعية في جلسة غير عادية، وأقرَّت بوجوب إمداد إسبانيا بمعوناتٍ مالية، لتساندَها في حربها مع العثمانيين؛ ممَّا كانت ثمرة تلك المجهودات وإعادة التنظيم لهيكل إسبانيا وهزيمة العثمانيين في وهران."},{"id":3752,"title":"وفاة أمير البحر طرغد باشا العثماني  .","date":["العام الهجري :972","الشهر القمري : ذي القعدة","العام الميلادي :1565"],"text":"هو القائد أمير البحر طرغد باشا العثماني، يسمى عند النصارى درغوث، وعند العرب طرغول. من أشهر قادة البحر العثمانيين، خلَفَ خيرَ الدين في قيادة الأسطول العثماني في شمال إفريقيا، ولِدَ طرغد عام 1485م، في قرية تابعة للواء منتشة موغلة. التحق بالبحرية العثمانية كجنديٍّ بحري عاديٍّ في سن مبكرة جدًّا، ثم اندفع في شبابه إلى حياة البحر بدافع حب المغامرات، فاشتغل كملَّاح بسيط ثم مِدفَعي، ثم ذاع صيتُه، وأظهر تفوقًا ومقدرة عالية في الأعمال العسكرية البحرية، فوجَّه غزواته ناحية البحار الشرقية للبحر المتوسط ضِدَّ السفن البندقية, وسرعان ما انضمَّ إلى الأخوين عروج وخير الدين بربروسا, فخاض معارك بحرية ناجحة ضد النصارى الإسبان في البحر المتوسط. حتى أصبح الذراع الأيمن لخير الدين بربروسا أميرِ الأسطول العثماني، إلى أن خلَفَه في قيادة الأسطول بعد وفاته, وقد قام بغارةٍ كبيرة على شواطئ إسبانيا، تمكَّن خلالها من إنقاذ آلاف من الموركسيين المسلمين الغرباء في الأندلس. حاز طرغد شهرةً عظيمة في الحروب البحرية وخافت بأسَه جميعُ دول الإفرنج المعادية للدولة العثمانية، وحَفِظَ اسم البحرية العثمانية من السقوطِ بعد موت رئيسِها ومؤسِّسها خير الدين بربروسا في البحر المتوسط, وقد شارك طرغد في تعزيز الحماية العثمانية للجزائر وطرابلس الغرب من خطر الإسبان الذين يطمحون في استرجاعها والسيطرة عليها. توفي طرغد أثناء غزو جزيرة مالطة، وكان عمره حين توفي يناهز الثمانين عامًا، ودُفِن في طرابلس الليبية."},{"id":3753,"title":"وفاة شيخ الإسلام شهاب الدين ابن حجر الهيتمي .","date":["العام الهجري :973","العام الميلادي :1565"],"text":"هو شيخ الإسلام شهاب الدين أبو العباس أحمد بن محمد بن علي بن حجر الهيتمي السعدي الأنصاري، ولد سنة 909 في محلة أبي الهيتم في إقليم الغربية بمصر، وإليه نسبته, ويقال هي محلة ابن الهيثم بالمثلثة فغيَّرتها العامة، تلقى علومَه بالأزهر فبلغ فيها مرتبة شيخ الإسلام عندهم، كان فقيهًا على الشافعي مذهبًا، الأشعريِّ عقيدةً، والمتصوف مسلكًا, وتعتبر ترجيحاته في المذهب معتبرة، وأقواله في المذهب معتبرة، بل يعتبرونه في مقام النووي في تحرير المذهب، وهو عندهم خاتمة المحرِّرين في المذهب الشافعي، وإليه المنتهى في الترجيح، له مصنفات عديدة، منها: تحفة المحتاج لشرح المنهاج، وهو في الفقه الشافعي، وله شرح على الأربعين النووية، والإعلام بقواطع الإسلام، والزواجر عن اقتراف الكبائر، والصواعق المحرقة في الرد على أهل البدع والزندقة، والفتاوى الكبرى الفقهية، وغيرها من الكتب، وكان يشنِّع على علماء أهل السنة المخالفين له في آرائه، خصوصًا شيخ الإسلام ابن تيمية وتلميذه ابن القيم, لا سيما على شيخ الإسلام ابن تيمية؛ فقد اعترض عليه في عدد من القضايا المتعلقة بأصول الاعتقاد, فسبَّه سبًّا شديدًا كما في الفتاوى الحديثية\" قال الإمام الشوكاني: \"انتقل من مصر إلى مكة المشرفة، وسبب انتقاله أنه اختصر الروض للمقري، وشرع في شرحه، فأخذه بعضُ الحساد وفتَّتَه وأعدمه، فعظم عليه الأمر واشتد حزنه، وانتقل إلى مكة وصنف بها الكتب المفيدة، منها: الإمداد وفتح الجواد، شرحان على الإرشاد، الأول بسيط، والثاني مختصر، وتحفة المحتاج شرح المنهاج، والصواعق المحرقة، وشرح الهمزية، وشرح العباب، وكان زاهدًا متقللًا على طريقة السلف، آمرًا بالمعروف ناهيًا عن المنكر، واستمر على ذلك حتى مات في مكة\" عن 65 عامًا."},{"id":3754,"title":"وفاة الصوفي عبد الوهاب بن ذوقا الشعراني صاحب الطبقات .","date":["العام الهجري :973","العام الميلادي :1565"],"text":"هو أبو المواهب عبد الوهاب بن أحمد بن علي الحنفي، نسبة إلى محمد بن الحنفية، ولِدَ في قلقشندة بمصر، ونشأ في ساقية أبي شعرة، وينسب الشعراني إلى قرية أبي شعرة المصري الشافعي الصوفي، والشعراني صوفي شاذلي أسَّس الطريقة الشعراوية، وكان معظمُ نشاطه في التصوف، اشتهر بتفاخره؛ حيث كان يدَّعي الاتصالَ بالله والملائكة والرسل، وأنه قادر على الإتيان بالمعجزات والتعرف على أسرار العالم!! له تصانيف أشهرُها طبقاته المسمى: لواقح الأنوار في طبقات الأخيار، وهو تراجم للصوفية، فيه كثير من القصص الخرافية التي يزعم أنها كرامات لأصحابها، بل في بعضها كفر، فأنى يكون كرامة؟! وله أدب القضاء، وله إرشاد الطالبين إلى مراثي العلماء العاملين، وغيرها، توفي في القاهرة عن 75 عامًا."},{"id":3755,"title":"محاولة العثمانيين فتح جزيرة مالطة .","date":["العام الهجري :973","الشهر القمري : ربيع الأول","العام الميلادي :1565"],"text":"كان السلطان العثماني سليمان القانوني عازمًا على فتح جزيرة مالطة التي كانت أكبر مَعقِل للنصارى الأوروبيين في وسط البحر المتوسط، والتي سبق أن استقَرَّ فيها فرسان القديس يوحنا، فأرسل السلطانُ العثماني أسطولًا آخر بقيادة بيالي باشا نفسه، كما طلب من درغوث رايس حاكمِ طرابلس وجربة، وحسن خير الدين أن يتوجَّها على رأس أسطوليهما الإسلاميين للمشاركة في عملية مالطة وإخضاعها؛ استعدادًا لمنازلة بقية المعاقل الإسلامية بعد ذلك، فسار حسن بن خير الدين على رأس عمارة تشمل 25 سفينة وثلاثة آلاف رجل، ووصل الأسطول الإسلامي أمام مالطة يوم 18 مايو، وفرض الحصار عليها، واستمر الحصار ضيقًا شديدًا إلى أن جهَّزت المسيحية رجالها وأساطيلها ووصل المدد تحت قيادة نائب ملك صقلية برفقة أسطول تعداده 28 سفينة حربية، تحمل عددًا كبيرًا من المقاتلين، ونشبت المعركة بين الطرفين، وتمكَّن الأسطول الإسلامي من الانسحاب في 18 ربيع الأول من هذه السنة."},{"id":3756,"title":"وفاة السلطان سليمان القانوني وتولي ابنه سليم الثاني الخلافة .","date":["العام الهجري :974","الشهر القمري : صفر","العام الميلادي :1566"],"text":"هو السلطان سليمان بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني، عاشر سلاطين بني عثمان، وثاني من حمل لقب أمير المؤمنين، ولد في غرة شعبان سنة 900هـ في طرابزون, وهو من أشهر سلاطين آل عثمان؛ حيث تميَّز عصره بالقوة والنفوذ، كان الغرب يلقِّبه بسليمان العظيم، وفي الشرق يلقب بسليمان القانوني, وبلغت الدولة العثمانية في مدته أعلى درجات الكمال. وكانت باكورةُ أعماله بعد توزيع النقود على الانكشارية تعيين مربِّيه قاسم باشا مستشارًا خاصًّا، وإبلاغ توليته على عرش الخلافة العظمى إلى كافة الولاة وأشراف مكة والمدينة بخطابات مفعمة بالنصائح والآيات القرآنية المبيِّنة فضل العدل والقسط في الأحكام، ووخامة عاقبة الظلم، وكان يستهِلُّ خطاباته بالآية الشريفة (إنه من سليمان وإنه بسم الله الرحمن الرحيم) تولى السلطنة عام 926هـ وأضاف للدولة العثمانية الكثيرَ من الولايات والأراضي الواسعة التي شملت عددًا من عواصم الحضارات والدول، كأثينا وصوفيا وبغداد ودمشق وإسطنبول وبودابست وبلغراد والقاهرة وبوخارست وتبريز, حيث قاد القانوني الجيوشَ العثمانية لغزو معاقل وحصون الأوروبيين في أغلب أراضي المجر قبل أن يتوقَّف عند أسوار فيينا, كما ضمَّ أغلب مناطق البلاد العربية أثناء صراعه مع الصفويين ومناطق من شمال فريقيا حتى الجزائر، وسيطرت أساطيلُه على بحار المنطقة من البحر المتوسط إلى البحر الأحمر حتى الخليج العربي. تلقَّب بالقانوني؛ لأنَّه جمع الشرائع المؤسَّسية على أصل إسلامي، ورتبها في مجموعة ظلَّت بموجبها الشريعة الوحيدة المعمول بها، توفي في أثناء حصاره إحدى القلاع في النمسا في العشرين من صفر من هذا العام، بعد أن دامت مدة حكمه قرابة ثمانٍ وأربعين سنة، وتولى العرش بعده ابنه سليم وبدأ عصر الضعف في الدولة العثمانية."},{"id":3757,"title":"صلح العثمانيين مع النمسا .","date":["العام الهجري :976","العام الميلادي :1568"],"text":"بعد أن تسَلَّم سليم الثاني زمامَ الخلافة العثمانية بدأ الضعفُ يدبُّ فيها، إلا أنه لم يظهر الضعف عليه بسبب قوة وزيره محمد الصقلي، وفي هذه السنة عقدت الدولة العثمانية معاهدةَ صلح مع النمسا، اعترفت فيه بأملاك النمسا في المجر على أن تدفع النمسا مقابل ذلك الجزية السنوية المقرَّرة للدولة العثمانية، واعتراف النمسا أيضًا بتبعية أمراء ترانسلفانيا والأفلاق والبغدان للدولة العثمانية."},{"id":3758,"title":"ثورة مسلمي غرناطة الموريسكيون .","date":["العام الهجري :976","العام الميلادي :1568"],"text":"ثار المسلمون في ليلة عيد ميلاد النصارى على الإسبان، واعتصموا في جبال البشرات لصدور أوامر ملكية تحرم عليهم التحدث بالعربية، وتمنعهم من ممارسة عبادتهم وتقاليدهم، وكانت هذه الثورة بقيادة محمد بن أمية، يُذكَر أن السلطان السعدي الغالب بالله بذل الوعود المعسولة لرسل الثوَّار البورشارات، ووعدهم بالنصر وتقديم كل ما يحتاجونه من عتاد وسلاح ورجال، لكن استمرَّ الغالب بالله محافظًا على روابطه الوديَّة مع فيليب الثاني، وعمل على خِذلان أهل الأندلس! تسارعت الأحداث في إسبانيا، وبلغ عدد المجاهدين في أوائل سنة 976 أكثر من مائة وخمسين ألفًا، وصادف تلك الثورة صعوباتٌ كبيرة بالنسبة للحكومة الإسبانية؛ إذ كانت غالبية الجيش متقدِّمة مع دوق البابا في الأراضي المنخفضة وأثبتت الدوريات البحرية أنها غير قادرة على حرمان الثوار المسلمين من الاتصال بالعثمانيين في الجزائر، فاستنجد المسلمون بالعثمانيين، فجمع قلج علي جيشًا عظيمًا قِوامُه أربعة عشر ألف رجل من رماة البنادق، وستين ألفًا من المجاهدين العثمانيين من مختلف أرجاء البلاد، وأرسلهم إلى مدينتي مستغانم ومازغران؛ استعدادًا للهجوم على وهران، ثم النزول في بلاد الأندلس، وكان يرافق ذلك الجيشَ عددٌ كبيرٌ من المدافع، وألف وأربعمائة بعير محمَّلة بالبارود الخاص بالمدافع والبنادق، ولكن وبسبب سوء تصرف أحد رجال الثورة الأندلسيين إذ انكشف أمره فداهمه الإسبان، وضبطوا ما كان يخفيه من سلاح بعد أن نجح قلج علي في إنزال الأسلحة والعتاد والمتطوعين على الساحل الإسباني، لم تقع الثورة في الموعد المحدَّد لها، لقد قام قلج علي في شعبان سنة 976 ببعث أسطول الجزائر لتأييد الثائرين في محاولتهم الأولى، وحاول إنزال الجند العثماني في الأماكن المتفق عليها، لكن الإسبان كانوا قد عرفوا ذلك بعد اكتشاف المخطَّط، فصدوا قلج علي عن النزول، وكانت الثورة في عنفوانها، وزوابع الشتاء قوية في البحر؛ فالأسطول الجزائري صار يقاوم الأعاصير من أجل الوصول إلى أماكن أخرى من الساحل يُنزل بها المدد المطلوب، إلا أن قوة الزوابع أغرقت 32 سفينة جزائرية تحمل الرجال والسلاح، وتمكَّنت ست سفن من إنزال شحنتِها فوق سواحل الأندلس، وكان فيها المدافع والبارود والمجاهدين، وكان القائد المجاهد قلج علي قد عزم على الذهاب بنفسه ليتولى قيادة الجهاد هناك، لكن ما شاع عن تجمع الأسطول الصليبي للقيام بمعركة حاسمة مع المسلمين وأمْر السلطان العثماني له بالاستعداد للمشاركة في هذه المعركة- جعله مضطرًّا للبقاء في الجزائر منتظرًا لأوامر إستانبول، وفي غمرة الثورة الأندلسية اتُّهم قائد الثورة ابن أمية بالتقاعس عن الجهاد، فهاجمه المتآمرون فقتلوه في منزله واختير مولاي عبد الله بن محمد بن عبو بدلًا منه، وبعث قلج علي تعزيزات له ونجح القائد الجديد في حملاته الأولى ضد النصارى الإسبان، وطوَّق جيشُه مدينة أرجيه، انزعجت الحكومة الإسبانية لهذا التطورات، وعينت دون جوان النمساوي على قيادة الأسطول الإسباني (وهو ابن غير شرعي للإمبراطور شارل) فباشر قمع الثورة في سنواتها 977-987 وأتى من الفظائع ما بخلت بأمثاله كتُبُ الوقائع، فذبح النساء والأطفال أمام عينيه، وأحرق المساكنَ ودمَّر البلاد، وكان شعاره لا هوادة، وانتهى الأمر بإذعان مسلمي الأندلس، لكنه إذعان مؤقت؛ إذ لم يلبث مولاي عبد الله أن عاد الكَرَّة، فاحتال الإسبان عليه حتى قتلوه غيلةً ونصبوا رأسه فوق أحد أبواب غرناطة زمنًا طويلًا."},{"id":3759,"title":"مزيد من اضطهاد الموريسكيين في غرناطة .","date":["العام الهجري :977","العام الميلادي :1569"],"text":"بعد أن قُمِعت ثورة الموريسكيين في غرناطة وانتهت، أصدر الملك الإسباني فيليب الثاني مرسومًا بطرد الأندلسيين الموريسكيين من مملكة غرناطة، وتوزيعهم في الأقاليم الأندلسية بعد مصادرة أملاكهم، وإجبارهم على التنصر، وإحالة من يأبى على محاكم التفتيش."},{"id":3760,"title":"إخضاع ثورة الزيدية والإسماعيلية ضد العثمانيين في اليمن .","date":["العام الهجري :977","العام الميلادي :1569"],"text":"انتفض زعماءُ اليمن من الزيدية والإسماعيلية على الحُكم العثماني، وطردوا الحامية العثمانية عام 975، فقاد سنان باشا جيشًا استولى على عدن، ثم في هذه السنة عُقِدت اتفاقية بين الدولة العثمانية وبين الأئمة الزيدية، اعترف الزيديةُ بموجِبها بالسيادة العثمانية، ومرابطة القوات العثمانية في جميع القطاعات والمدن التي كانت ترابِطُ فيها قبل اندلاع الانتفاضة، واعترفت الدولة العثمانية بالإمام المطهَّر بن شرف الدين زعيمًا دينيًّا للزيدية، أما صَنعاء فلم تدخل تحت السيطرة العثمانية إلا بعد حروب شديدة واستسلام زعمائها الزيديين."},{"id":3761,"title":"استيلاء علي باشا صاحب الجزائر على تونس .","date":["العام الهجري :977","العام الميلادي :1569"],"text":"عندما غزا علي باشا- صاحِبُ الجزائر- تونسَ في هذه السنة، واستولى عليها وطرد منها حاكمها أحمد بن الحسن بن محمد الحفصي- ذهب أحمد إلى طاغية قشتالة مستغيثًا به، شأنُه شأن أبيه من قَبلِه، فأمَدَّه الطاغية بأسطول عظيم واشترط عليه أداء مال فالتزمه، ولما وصل الأسطول إلى ظاهر تونس اطَّلع قائده السلطان أحمد الحفصي على كتاب من الطاغية مضمونُه المشاركة في الحُكم، فأنكر أحمد ذلك وأنِفَ منه وذهب إلى صقلية فبقي بها إلى أن مات وحُمِل إلى تونس، وكان هنالك أخوه محمد بن الحسن فرضي بالمقاسمة ودخل بالنصارى معه إلى تونس سنة 981."},{"id":3762,"title":"وفاة السلطان بدر أبي طويرق الكثيري سلطان حضرموت .","date":["العام الهجري :977","العام الميلادي :1569"],"text":"هو السلطان بدر بن عبد الله بن جعفر، أبو طويرق الكثيري سلطان حضرموت. ولد سنة 902 في مدينة سيؤون وتولى سلطنتها وتوفي فيها، تولاها صغيرًا بعد وفاة أبيه. نشأ موفَّقًا في سياسته، طيب السيرة، وافر العقل، جوادًا، يعتبر أوَّلَ من عمل لتوحيد مناطق حضرموت؛ حيث شملت أراضي سلطنته حضرموتَ من أبْينَ ومأرب غربًا إلى ظفار شرقًا, ثم استعان بالترك، وكاتَبَ السلطان سليمان القانوني، فجاءته سنة 926 قوةٌ منهم، أضاف إليها بعض الزيود من اليمن، ورجالًا من يافع ومن الموالي الأفارقة، فتألف جيشه من هؤلاء جميعا, وصدَّ غارات البرتغال مرارًا. وأطفأ كثيرًا من الفتن الداخلية في بلاده. وطالت مدتُه إلى أن حجر عليه ابنٌ له اسمه عبد الله، فأقام إلى أن مات في هذا العام."},{"id":3763,"title":"صدور المرسوم الثاني بترحيل جميع سكان غرناطة المسلمين .","date":["العام الهجري :978","العام الميلادي :1570"],"text":"أعلن الكاردينال \"خيمينيث\" أن المعاهدة التي تم توقيعُها مع حكام غرناطة قبل مائة سنة والتي عقدت عام 879 لم تعُدْ صالحة أو موجودة، وأعطى أوامرَه بتنصير جميع المسلمين في غرناطة دون الأخذ برأيهم، أو حتى تتاح لهم فرصةُ التعرف إلى الدين الجديد الذي يساقون إليه، ومن يرفُض منهم عليه أن يختار أحد أمرين: 1- إما أن يغادر غرناطة إلى إفريقيا دون أن يحمل معه أي شيء من أمواله، ودون راحلةٍ يركبها هو أو أحد أفراد أسرته من النساء والأطفال، وتُصادَر أمواله. 2- وإما أن يُعدَمَ علنًا في ساحات غرناطة باعتباره رافضًا للنصرانية, فكان من الطبيعي أن يختار عدد كبير من أهالي غرناطة الهجرةَ بدينهم وعقائدهم، فخرج قسمٌ منهم تاركين أموالهم سيرًا على الأقدام، غيرَ عابئين بمشاقِّ الطرقات، ومجاهِلِ وأخطار السفر إلى إفريقيا من دون مال أو راحلة، في مشهد يشبه هجرة الصحابةِ رضي الله عنهم إلى الحبشة! وبعد خروجِهم من غرناطة كانت تنتظرُهم عصابات الرعاع الإسبانية والجنود الإسبان، فهاجموهم وقتلوا معظمَهم، وعندما سمع الآخرون في غرناطة بذلك آثروا البقاء بعد أن أدركوا أنَّ خروجهم من إسبانيا يعني قتْلَهم، وبالتالي سيقوا في قوافِلَ للتنصير والتعميد كُرهًا! ومن كان يكتشفُه الإسبان أنه قد تهرَّب من التعميد تتمُّ مصادرة أمواله وقتله علنًا! وقد فرَّ عدد كبير من المسلمين الذين رفضوا التعميدَ إلى الجبال المحيطة في غرناطة محتمين في مغاورها وشعابها الوعرة، وأقاموا فيها لفترات، وأنشؤوا قرى عربية مسلمة، وكان الملكُ الإسباني يُشرفُ بنفسه على الحملات العسكرية الكبيرة التي كان يوجِّهها إلى الجبال؛ حيث كانت تلك القرى تُهدَمُ ويُساق أهلُها إلى الحرق أو التمثيل بهم وهم أحياء، في الساحات العامة في غرناطة- رحمهم الله رحمة واسعة، وجعلهم في عِداد الشهداء."},{"id":3764,"title":"فتح العثمانيين جزيرة قبرص للمرة الثالثة .","date":["العام الهجري :979","الشهر القمري : ربيع الآخر","العام الميلادي :1571"],"text":"كانت إيطاليا وإسبانيا تقدران أهمية جزيرة قبرص، وشاع في أوروبا تكوُّنُ حِلف ضِدَّ السلطان، ولكن لم يُعمَلْ شَيءٌ في حينه لإنقاذ قبرص من العثمانيين الذين نزلوها بقوة كاسحة، نفذت إلى الجزيرة بدون صعوبة، ووقفت مدينة فامرجستا الحصينة أمام العثمانيين بقيادة باحليون وبراجادنيو الذين واجهوا القوة العثمانية التي بلغ عددُ مقاتليها مائة ألف, واستعمل خلالها العثمانيون جميعَ وسائل الحصار المعروفة، مِن فَرٍّ وكَرٍّ، وزرع للألغام، ولم ينتج أي تأثير على الحامية، ولو وصلت قوة النصرانية للنجدة، لصار العثمانيون في خطرٍ، إلا أنَّ المجاعة قامت بعملها، واستسلمت المدينةُ في ربيع الثاني من هذه السنة، ونَقَلت الدولةُ العثمانية بعد فتحِها لقبرص عددًا كبيرًا من سكان الأناضول الذين لا يزال أحفادُهم مقيمين في الجزيرة حتى الآن، ورغم ترحيبِ القبارصة الأرثوذكس بالحكم العثماني الذي أنقذهم من الاضطهاد الكاثوليكي الذي مارسته البندقية لعدة قرون، إلَّا أن احتلال العثمانيين أثار الدولة الكاثوليكية، ثم عرضت البندقيةُ الصلحَ مع الدولة العثمانية، فجرت بين الطرفين معاهدة تتخلى بموجِبِها البندقيةُ عن قبرص لصالح العثمانيين، وتحتفظ البندقية بجزيرة كريت وجزر الأرخبيل اليوناني، مع دفع غرامة مالية حربية خوفًا من تجديد القتال."},{"id":3765,"title":"الأساطيل الأوروبية تهزم الأسطول العثماني في موقعة ليبانتو .","date":["العام الهجري :979","الشهر القمري : جمادى الأولى","العام الميلادي :1571"],"text":"ارتعدت فرائِصُ الأمم الأوروبية النصرانيةِ من الخطر الإسلاميِّ العظيم الذي هدَّد القارة الأوروبية؛ من جرَّاءِ تدفُّق الجيوش العثمانية برًّا وبحرًا, وعندما احتلَّ الأسطول العثماني بقيادة علي باشا قبرص بقرارٍ من السلطان سليم الثاني, أخذ البابا بيوس الخامس يسعى من جديدٍ لجمع شمل البلاد الأوروبية المختلفة، وتوحيد قواها برًّا وبحرًا في تحالف صليبي تحت راية البابوية، اختير لقيادة قوة هذا التحالف (دون خوان) النمساوي، وهو أخٌ غير شقيق للملك فيليب الثاني، سار (دون خوان) إلى البحر الأدرياتيك، حتى وصل إلى الجزء الضيق من خليج كورنث بالقرب من باتراس، وليس ببعيد عن ليبانتو اليونانية، والذي أعطى اسمها للمعركة، ونظَّم علي باشا قواتِه فوضع سفُنَه على نسق واحد من الشمال إلى الجنوب، بحيث كانت ميمنتُها تستند إلى مرفأ ليبانتو، ومسيرتُها في عُرض البحر، وقد قسَّمها علي باشا إلى جناحين وقلب, فكان هو في القلب, وشيروكو في الجناح الأيمن، وبقي الجناح الأيسر بقيادة قلج علي، ومقابل ذلك نظَّمَ دون خوان قواتِه، فوضع سفنه على نسق يقابل النسق الإسلامي، ووضع جناحه الأيمن بقيادة دوريا مقابل قلج علي، وأسند قيادة جناحه الأيسر إلى بربريجو مقابل شيروكو، وجعل (دون) نفسَه لقيادة القلب، وترك أسطولًا احتياطيًّا بقيادة سانت كروز. احتدمت المعركة في 17 جمادي الأولى من هذه السنة, أحاط الأسطول الإسلامي بالأسطول الأوروبي وأوغل العثمانيون بين سفن العدو، ودارت معركة قاسية أظهر فيها الفريقان بطولةً كبيرة وشجاعة نادرة، وشاءت إرادة الله هزيمة المسلمين، ففقدوا ثلاثين ألف مقاتل، وقيل عشرين ألفًا، وخسروا 200 سفينة حربية، منها 93 غرقت، والباقي غنمه العدو وتقاسمته الأساطيل النصرانية المتحدة، وأُسِرَ لهم عشرة آلاف رجل! واستطاع قلج علي إنقاذ سفنه، واستطاع كذلك المحافظة على بعض السفن التي غَنِمَها، ومن بينها السفينة التي تحمل علم البابا، رجع بها إستانبول التي استقبلته استقبال الفاتحين، رغم الشعور بمرارة الهزيمة, وكان لهذه الهزيمة أثرُها الكبير في تراجع الهيمنة العثمانية على غرب البحر المتوسط، ونهاية التمدد العثماني في شرق ووسط أوروبا, ومن أسباب هذه الهزيمة الكارثية على الدولة العثمانية قرارُ سليم الثاني بفتح قبرص، فلم يكن صائبًا؛ لأن قبرص لم تكن مزعجةً للدولة العثمانية، بينما ترتب على فتحها قيامُ هذا التحالف الصليبي الذي أدى إلى هزيمة الدولة في هذه المعركة, فضلًا عن أن قائد الأسطول العثماني علي باشا لم يكن على مستوى قيادة معركة بهذا الحجم، الذي شكله التحالف النصراني, وفي المقابل احتفلت القارة الأوربية بنصر ليبانتو؛ فلأول مرة منذ قرون تحلُّ الهزيمة بالعثمانيين!"},{"id":3766,"title":"وفاة القائد البحري العثماني حسن باشا بن خير الدين بربروسا .","date":["العام الهجري :979","الشهر القمري : شوال","العام الميلادي :1572"],"text":"هو القائد البحري العثماني حسن باشا ابن القائد البحري الشهير خير الدين بربروسا، وُلد سنة 925, ويعدُّ من القادة المعدودين في الدولة العثمانية الذين حقَّقوا انتصارات باهرة على الإسبان في شمال إفريقيا، وقد حكم الجزائرَ حوالي 15 عامًا، تخللتها حروبٌ طاحنة. أراد حسن باشا أن يطهِّرَ وهران من الوجود الإسباني، فأخذ يستعدُّ في مدينة الجزائر لجمع قوى جديدةٍ منظَّمة منقادة إلى جانب الجيشِ العثماني، فجنَّد عشرةَ آلاف رجل من زواوة، كما أنشأ قوة أخرى ووضع على رأسِها أحدَ أعوان والده القدامى، وفي الوقت نفسه حاول الحصولَ على تأييد القوة المحلية، فتزوج من ابنة سلطان كوكو ابن القاضي، توفي في إستانبول ودفن فيها, وكان عمره حين توفي يناهز 72 عامًا."},{"id":3767,"title":"عقد الدولة العثمانية معاهدة إستانبول مع البندقية .","date":["العام الهجري :980","الشهر القمري : ذي القعدة","العام الميلادي :1573"],"text":"عقدت الدولةُ العثمانية معاهدةَ إستانبول مع البندقية, فالدولة العثمانية لم يُقعِدْها هزيمة معركة ليبانتو القاسية سنة 979هـ ولم تضعُفْ هِمَّةُ الصدر الأعظم محمد باشا صقللي، فانتهز فرصة الشتاء وعدم إمكانية استمرار الحرب لتجهيز أسطول جديد، وبذَلَ النَّفس والنفيس في تجهيزِه وتسليحه، حتى إذا أقبل صيف سنة 1572م كان قد تمَّ بناء 250 سفينة، وأعلم الصدرُ الأعظم البنادقةَ باستعداده للجولة الثانية، ففضَّلت البندقية أن تجنحَ للسلام، ووقَّعت مع الدولة العثمانية معاهدةَ إستانبول هذه السنة, والتي تتكوَّن من سبعة بنود، منها: أن تسدِّد البندقية غرامات مالية لتركيا، وأن تبقى جزيرةُ قبرص في حوزة الدولة العثمانية, فتفرَّغَ على إثرها العثمانيون لمحاربة إسبانيا التي عادت لاحتلال تونس، وكذلك هزموا أمير البغدان الذي تمرَّد على الدولة طلبًا للاستقلال."},{"id":3768,"title":"وقوع فتنة عظيمة بمراكش .","date":["العام الهجري :980","الشهر القمري : ذي الحجة","العام الميلادي :1573"],"text":"كان الفقيهُ أبو عبد الله محمد الأندلسي نزيلُ مراكش قد استهوى بما يظهر عليه من زهدٍ وصلاحٍ كثيرًا من العامة، فتبعوه، وكانت تصدرُ عنه مقالات قبيحةٌ من الطعن على أئمة المذاهب رحمهم الله تعالى، ويتفوه بمقالات شنيعة في الدين، فأمر السلطانُ الغالب بالله بقتلِه، فاستغاث بالعامَّةِ مِن أتباعه، واعصوصبوا عليه ووقعت فتنةٌ عظيمة بمراكش بسَبَبِه إلى أن قُتِلَ وصُلِب على باب داره برياض الزيتون بمراكش، وكان ذلك أواسِطَ ذي الحجة من هذه السنة."},{"id":3769,"title":"قيام النصارى بمكيدة البارود بجامع المنصور في مراكش .","date":["العام الهجري :981","العام الميلادي :1573"],"text":"كان بقصبة مراكش جماعةٌ من أسارى النصارى من لدُن أيامِ أبي العباس الأعرج وأخيه أبي عبد الله الشيخ، فرأوا الجمعَ الغفير من أعيان المسلمين وأهلِ الدولة يحضرون كلَّ جمعة للصلاة مع السلطان بجامعِ المنصور من القصبة، فحدَّثَتهم أنفسُهم الشيطانية بأن يصنعوا مكيدةً يُهلكون بها السلطانَ ومن معه، فحفروا في خُفيةٍ تحت الجامع حفرةً مَلؤُوها من البارود ووضعوا فيها فتيلًا تسري فيه النارُ على مهلٍ كي ينقلبَ الجامِعُ بأهله وقتَ الصلاة فتسبب ذلك في سقوط القبَّة الواسعة من الجامع، وانشقَّ مناره شقًّا كبيرًا، وكان ذلك مبلغَ ضررِهم، وكفى الله المسلمين شَرَّ تلك المكيدة، ولم يتمكن لهم الحالُ على وَفقِ ما أرادوا."},{"id":3770,"title":"السلطان العثماني ينصب هنري شقيق ملك فرنسا ملكا على بولونيا .","date":["العام الهجري :981","الشهر القمري : محرم","العام الميلادي :1573"],"text":"نصبَ السلطانُ العثمانيُّ هنري شقيقَ ملك فرنسا شارل التاسع ملكًا على بولونيا التي كانت قد دخلت في تبعية الدولة العثمانية من سنة 1573م حتى 1592م, وكانت من الدول الملكيَّة الكبرى في أوروبا."},{"id":3771,"title":"استيلاء الإسبان على تونس .","date":["العام الهجري :981","الشهر القمري : رجب","العام الميلادي :1573"],"text":"كان فيليب الثاني قد تشجَّع لاحتلال تونس؛ بسبب لجوء السلطان الحفصي أبي العباس الثاني- الذي حكم تونس سنة 942- إليه، وطلب منه المساعدة في إخماد الثوراتِ فاشترط فيليب إعطاءَهم امتيازاتٍ كبيرة تتيح لهم سكنَ جميع أنحاء تونس، ويتنازلُ لهم عن عناية وبنزرت وحلق الواد, فرفض أبو العباس الشروطَ، ولكنَّ أخاه محمد بن الحسين قَبِلَها بعد ذلك, فخرج (دون خوان) أخو الملك من جزيرة صقلية في رجب 981, على رأس أسطول مكون من 138 سفينة تحمِلُ خمسة وعشرين ألف مقاتل، ونزل بقلعة حلق الواد التي كانت تحتلُّها إسبانيا، ثم باغَتَ دون خوان تونسَ واحتلَّها وخرج أهلُها إلى وادي تونس فارين بدينِهم من شرِّ الإسبان، كما انسحب الحاكِمُ العثماني إلى القيروان، فلما دخل الإسبان تونس نهبوها وأخربوا جامع الزيتونة فيها، ونهَبوا الكتُبَ النادرة فيها وطرحوا أكثَرَها في الشوارع لتُداس تحت أقدام الجنود!"},{"id":3772,"title":"وفاة السلطان أبي محمد السعدي أمير السعديين وتولي ابنه .","date":["العام الهجري :981","الشهر القمري : رمضان","العام الميلادي :1574"],"text":"هو السلطان أبو محمد عبد الله الغالب بالله، ابن السلطان محمد الشيخ السعدي أمير السعديين في المغرب، ولِدَ بتارودانت سنة 933، وانتقل إلى فاس، فبويع له فيها يومَ ورد النبأ من تارودانت بأنَّ الترك اغتالوا أباه آخر سنة 964, وأتته بيعةُ مراكش في أول سنة 965 واستوثق له الأمر, وبعد أربعة أشهر من ولايته أقبل من تلمسان جيشٌ من الترك بقيادة حسن بن خير الدين بربروسا، فقاتله الغالب باللَّه بالقربِ من فاس وهزمه, وأرسل جيشًا سنة 969 لانتزاع البريجة من أيدي البرتغاليين، لكنه لم يتمكَّن من فتحها, وبنى مارستانًا بمراكش وجامعًا, وعُنِي بترقية الزراعة والصناعة, وكان الغالب بالله قد بذل وعودًا لدعم الثوَّار البورشارات من مسلمي الأندلس، لكنَّه خذلهم. بعد وفاة الغالب بالله قام بعده ابنه أبو عبد الله محمد الثاني المتوكل على الله خلفًا لأبيه، الذي كان يضمِرُ الشر لعميه عبد الملك أبي مروان وأحمد المنصور، فخرجا من المغرب واتَّجها إلى السلطان العثماني يستنجدان به، تابع المتوكِّلُ خطة والده في التقرب من الدول الأوروبية ومسالمتها ضِدَّ العثمانيين؛ حيث لم يعُدْ لديه شكٌّ في أنهم سينجدون عمَّيه بقوات عسكرية، فعقد اتفاقًا مع إنجلترا، التي كانت ترغب في تجارتها مع المغرب للفوائد التي تعود على التجَّار الإنجليز من وراء ذلك، زيادة على أنها تدرِكُ الأهمية العظمى التي للمغرب، خصوصًا وقد كانت إنجلترا في حالة حربٍ ضد إسبانيا, وكان توقيع المتوكِّل للاتفاقية التجارية مع الإنجليز يعدُّ العملَ الوحيد الذي قام به خلال حكمه القصير."},{"id":3773,"title":"خلع ملك السعديين محمد الثاني وتولي عمه عبد الملك .","date":["العام الهجري :982","العام الميلادي :1574"],"text":"لَمَّا هرب عبد الملك بن محمد المهدي أبو مروان وأحمد المنصور عمَّا المتوكل على الله محمد الثاني زعيم السعديين، بعد توليه الحكم في المغرب بسبب عدائه لهما- استنجدا بالدولة العثمانية في الجزائر، فوجدت الدولةُ العثمانية في انشغال مَلِك إسبانيا فيليب الثاني بأحداث أوروبا الغربية- حيث ثورة الأراضي المنخفضة- فرصةً مناسِبةً للتدخل في المغرب، فأمدُّوا عبد الملك بجيشٍ قوامه خمسة آلاف مقاتل مسلَّحين بأحسن الأسلحة، ودخل عبدالملك فاس بعد أن أحرز انتصارًا كبيرًا على ابن أخيه المتوكِّل على الله، وعاد الجيش أدراجه إلى الجزائر، وقام عبد الملك بإصلاحات في دولته، من أهمِّها أمَرَ بتجديد السفن، وبصُنع المراكب الجديدة، فانتعشت بذلك الصناعة، كما اهتمَّ بالتجارة البحرية، وكانت الأموال التي غَنِمَها من حروبه على سواحل المغرب سببًا في انتعاش ونمو الميزان الاقتصادي للدولة، أسَّس جيشًا نظاميًّا متطورًا واستفاد من خبرة الجندية العثمانية وتشبه بهم في التسليح والرُّتَب، كما استطاع أن يبنيَ علاقات متينة مع العثمانيين، وجعل منهم حُلَفاء وأصدقاء وإخوة مخلصين للمسلمين في المغرب، وفرض احترامَه على أهل عصره، حتى الأوروبيين، احترموه وأجلَّوه. اهتمَّ عبد الملك بتقوية مؤسسات الدولة ودواوينها وأجهزتها، واستطاع أن يشكِّلَ جهازًا شوريًّا للدولة أصبح على معرفة بأمور الدولة الداخلية، وأحوال السكان عامة، وعلى دراية بالسياسة الدولية وخاصةً الدول التي لها علاقةٌ بالسياسة المغربية، وكان أخوه أبو العباس أحمد المنصور بالله- الملقب في كتب التاريخ بالذهبي- ساعِدَه الأيمن في كل شؤون الدولة."},{"id":3774,"title":"استعادة تونس وتحويلها لولاية عثمانية .","date":["العام الهجري :982","الشهر القمري : ربيع الأول","العام الميلادي :1574"],"text":"لما دخل الإسبان إلى تونس قاموا بإرجاع أحمد الحفصي، لكنهم اشترطوا عليه مقابِلَ ذلك أن يمنحَهم أراضيَ من تونس، فرفض ذلك فخلعوه وولَّوا أخاه محمدًا مكانه، وكان قد وافق على طلب الإسبان، فلجأ أحمد إلى صقلية ومات في باليرمو، أمَّا أخوه محمد فأدخل الإسبان إلى البلاد فشاركوه السلطةَ وكثُرَ الفساد وهرب أكثرُ الناس إلى الجبال، ولكنْ لم يلبث الأمرُ فيها أكثر من ثمانية أشهر، حتى أبحر الأسطولُ العثماني بقيادة سنان باشا وقلج علي في 23 محرم من هذه السنة, فخرج من المضائقِ ونشر أشرعتهَ في البحر الأبيض، فقاموا بضرب ساحلِ كالابريا، مسينا، واستطاع العثمانيون أن يستولوا على سفينة أوروبية، ومن هناك قطعوا عرض البحر في خمسةِ أيام، في هذا الوقت وصل الحاكمُ العثماني في تونس حيدر باشا، كما وصلت قوةٌ من الجزائريين بقيادة رمضان باشا، وقوةُ طرابلس بقيادة مصطفى باشا، كما وصل ثمةَ متطوعين من مصر، بدأ القتال في ربيع أول من هذه السنة, ونجح العثمانيون في الاستيلاء على حلق الواد، بعد أن حوصِرَ الإسبان حصارًا محكمًا، وقامت قوات أخرى بمحاصرة مدينة تونس، ففَرَّ الإسبان الموجودون فيها ومعهم الملك الحفصي محمد بن الحسن إلى البستيون التي بالغ الإسبان في تحصينها وجعلوه من أمنع الحصون في الشمال الإفريقي، توجه العثمانيون بعد تجمُّع قواتهم إلى حصار البستيون، وضيَّق العثمانيون الخناقَ على أهلها من كل ناحية, فلجأ الحفصيون إلى صقليةَ حيث ظلوا يوالون الدسائسَ والمؤامرات والتضرعات لملوك إسبانيا سعيًا لاسترداد مُلكهم، واتخذهم الإسبان آلاتٍ طيِّعةً تخدمُ بها مآربَهم السياسية حسَبَما تمليه الظروفُ عليهم، وقضى سقوط تونس بيد العثمانيين على الآمال الإسبانية في إفريقيا، وضَعُفت سيطرتها تدريجيًّا حتى اقتصرت على بعض الموانئ، مثل مليلة ووهران والمرسى الكبير، وتبدد حلمُ الإسبان نحو إقامة دولة إسبانية في شمال إفريقيا وضاع بين الرمال."},{"id":3775,"title":"وفاة السلطان سليم الثاني بن سليمان القانوني .","date":["العام الهجري :982","الشهر القمري : شعبان","العام الميلادي :1574"],"text":"هو السلطان سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح. ولِدَ سليم الثاني في 6 رجب سنة 930 وهو ابن روكسلان الروسية. تولَّى المُلك بعد موت أبيه سليمان القانوني, ولم يكن السلطان سليم متصفًا بما يؤهِّله للقيام بحفظ فتوحات أبيه، فضلًا عن إضافة شيء إليها! وكان لوجود الوزير الطويل محمد باشا صقللي المدرَّب على الأعمال الحربية والسياسية دور كبير في حفظ الدولة، فحُسنُ سياسته وعِظَم اسم الدولة ومهابتها في قلوب أعدائها حَفِظَتْها -بعد فضل الله- من السقوط مرةً واحدة. وفي عهد سليم تكبَّدت الدولة هزيمةً ساحقة أمام التحالف الأوربي الصليبي في معركة ليبانتو سنة 979 فقدت بعدها الدولةُ هيبتها العسكرية في البحر المتوسط. توفِّيَ في السابع والعشرين من شهر شعبان، بعد أن دام في الحكم ثمانية أعوام، ثمَّ تولى ابنه مراد الثالث الخلافة، ثم أمر بقتل إخوته الخمسةِ؛ خوفًا من نزاعِه على الملك."},{"id":3776,"title":"خضوع بولونيا تحت الولاية العثمانية .","date":["العام الهجري :983","العام الميلادي :1575"],"text":"ترك هنري ملك بولونيا منصِبَه وعاد إلى فرنسا، فأوصى الخليفةُ مراد الثالث أعيانَ بولونيا بانتخاب أمير ترانسلفانيا ملكًا عليهم، ففعلوا ذلك وأصبحت بولونيا بذلك تحت حماية العثمانيين، واعترفت النمسا بذلك في معاهدة الصلحِ التي أبرمتها مع الدولة العثمانية في العام التالي، وذلك حين هجم التتارُ على الحدود البولونية، فاستنجدت بالدولة العثمانية فأعلن حمايتَها بموجبِ معاهدةٍ رسميةٍ."},{"id":3777,"title":"الدولة العثمانية تجدد امتيازات الدول الأجنبية .","date":["العام الهجري :984","العام الميلادي :1576"],"text":"جدَّد الخليفةُ مراد الثالث للدُّول الأوربية امتيازاتِها، وهي فرنسا والبندقية، وزاد عليها أن أصبح السفيرُ الفرنسي يأتي في مقدِّمة سفراء الدول الأجنبية الذين كثُروا في إستانبول، وكانت سفُنُ الدول الأوربية تدخل الموانئ العثمانية تحت ظِلِّ العلم الفرنسي باستثناء البندقية، ثم جاءت بعدئذ إنكلترا التي حصلت على امتيازات لتجَّارها أيضًا، وطِبقًا للمعاهدات السابقة فقد قامت فرنسا بإرسال البَعثات الدينية النصرانية إلى كافة أرجاء البلاد العثمانية التي يسكُنُها نصارى، وخاصةً بلاد الشام، وقامت بزرع محبَّة فرنسا في نفوس نصارى الشام؛ ممَّا كان له أثر يُذكَرُ في ضعف الدولة العثمانية؛ إذ امتدَّ النفوذ الفرنسي بين النصارى، وبالتالي ازداد العصيان وتشجَّعوا على الثورات، فكان من أهم نتائج ذلك التدخُّلِ الاحتفاظُ بجنسية ولغة الأقليات النصرانية، حتى إذا ضَعُفت الدولة العثمانية ثارت تلك الشعوب مطالِبةً بالاستقلالِ بدعم وتأييد من دول أوروبا النصرانية!"},{"id":3778,"title":"وفاة الشاه طهماسب الصفوي وقيام ابنه إسماعيل الثاني .","date":["العام الهجري :984","العام الميلادي :1576"],"text":"هو الشاه طهماسب بن إسماعيل الصفوي. تولَّى السلطة على الصفويين بعد أبيه، وهو الابن الأكبر لإسماعيل شاه، ثم ثار عليه أخوه إخلاص ميرزا مدَّعيًا حقه في العرش، فتمكن من أسْرِه وقتْلِه، ثم توفِّيَ طهماسب في هذه السنة مسمومًا بعد أن دام في الملك أربعة وخمسين عامًا، فخلفه ابنُه إسماعيل الثاني الذي كان محبوسًا منذ عام 965 بسبب استقلاله العسكري؛ مما أثار شكوك أبيه وخوفه من الثوران عليه وإطاحته من المُلك، فلما مات أبوه أُخرِجَ من السجن واعتلى عرشَ إيران."},{"id":3779,"title":"استيلاء أبي مروان عبد الملك ابن الشيخ السعدي على مراكش .","date":["العام الهجري :984","الشهر القمري : ربيع الآخر","العام الميلادي :1576"],"text":"بعد انتهاءِ أبي مروان عبد الملك ابن الشيخ السعدي من ضَمِّ فاس, تقدَّم إلى البلاد المراكشية قاصدًا حرب ابن أخيه محمد المتوكل على الله وتشريده عنها، ولما سَمعَ ابنُ أخيه بخروجه إليه وقصْده إياه، تهيأ لملاقاته وسار إلى منازلته، فالتقى الجمعان بموضعٍ يسمى خندق الريحان، على مقربة من وادي شراط من أحواز سلا، فكانت الهزيمة أيضًا على المتوكل على الله، وتبعه عمُّه أبو العباس أحمد المنصور خليفةُ أخيه أبي مروان يومئذ، فلما سمع المتوكل باتباعِه بعد بلوغِه إلى مراكش فرَّ عنها إلى جبل درن، وأسلم له مراكش، فدخلها أحمد نائبًا عن أخيه وأخذ له البيعةَ على أهلها، ثم لحق به السلطانُ أبو مروان فدخلها يوم الاثنين تاسع عشر ربيع الثاني من هذه السنة، وأقام بها أيامًا ثم خرج في طلب ابن أخيه، فعَمِيَت عليه أنباؤه! فعاد أبو مروان إلى مراكش وأقام بها."},{"id":3780,"title":"وفاة الشاه إسماعيل الثاني بن طهماسب وقيام أخيه محمد خدابنده .","date":["العام الهجري :985","الشهر القمري : رمضان","العام الميلادي :1577"],"text":"هو الشاه إسماعيل الثاني بن طهماسب بن إسماعيل بن حيدر الصفوي، ثالث حكام الدولة الصفوية، ملك بعد أبيه سنة 984 وكان محبوسًا بقلعة ألموت منذ عشرين سنة؛ بسب استقلاله العسكري، فلما بويع بالحُكمِ قام بقتلِ جميع أخوته ما عدا محمد خدابنده، كما قتل جميع أولاده ما عدا الأكبر حسينًا، وأخاه عباسًا الذي نجا بأعجوبة, وكان إسماعيل الثاني شيعيًّا ثم صار سنيًّا، وقتل غالبَ الروافض وكان متجبرًا متعظِّمًا، فاحتجب عن الخلق وفوَّض الأمر إلى وكيله, وكان يخافُه أهل بلاده لشهامته وشجاعته، فلما ملك صار أجبَنَ الخلق وعجَزَ عن ضبط المملكة, وكان أخوه محمد خدابنده بخراسان لم يسلِّم لأخيه إسماعيل بالطاعة، وكذلك أكثر القبائل, أثار الشاه إسماعيل الثاني غضَبَ الشيعة الرافضة بما أصدره من قوانين تمنعُ سب الخلفاء الراشدين الثلاثة على المنابر، وربَّما كان تصرفه هذا هو انتقامًا من سجنه كل هذه السنين، ولكِنَّ أيامه لم تطُلْ أكثر من سنة؛ حيث توفي مسمومًا بقزوين في رمضان- على ما قيل- في منزل غلام كان يتعشَّقُه، وقيل: هجم عليه خواصُّ مُلكه فقتلوه؛ لأنه كان قد قتل منهم إلى ثلاثين ألفًا؛ لكونهم سببًا في حبسه فأبغضوه, وقد جاوز الخمسين.. فخَلَفه أخوه محمد خدابنده."},{"id":3781,"title":"غزو الأشراف لنجد .","date":["العام الهجري :986","العام الميلادي :1578"],"text":"غزا الأشراف نجدًا بقيادة الشريف حسن بن أبي نمي، وهاجموا بلدة معكال التي أصبحت جزءًا من مدينة الرياض الحالية, وبقي مدة فيها ثم عاد بعد ثلاث سنوات، وغزا الخرج والعارض، واعترضه أثناء عودته جماعةٌ من بني خالد فهزمهم."},{"id":3782,"title":"معركة وادي المخازن بين السعديين والعثمانيون والبرتغاليين .","date":["العام الهجري :986","الشهر القمري : جمادى الآخرة","العام الميلادي :1578"],"text":"كان محمد المتوكل على الله بعد هزيمته من عمِّه عبد الملك قد اتصل بمَلِك البرتغال سبستيان، واتَّفق معه على أن يُعينَه على طرد عمِّه من حكم المغرب، وأن يتنازلَ له مقابل ذلك عن جميع شواطئ المغرب، فقَبِلَ سبستيان ذلك العرض المغربي، انتقل المتوكِّل إلى سبتة، وأقام بها أربعة شهور، ومنها اتَّجه إلى طنجة في انتظار سبستيان على رأس القوات العسكرية، وفي أثناء استعدادات الدول الأوروبية- وخاصة البرتغال- للوثوب على المغرب، وإخضاعه بالكامل، حيث استطاع سبستيان أن يحشد من النصارى عشرات الألوف من الإسبان والبرتغاليين والطليان والألمان، وجهَّز هذه الألوف بكافة الأسلحة الممكِنة في زمنه، وجهَّز ألف مركب لتحمِلَ هؤلاء الجنود نحو المغرب، وأقلُّ ما قيل في عددهم ثمانون ألف مقاتل! بينما كان المغاربة بقيادة السلطان أبي مروان عبد الملك السعدي وتَعداد جيشه أربعون ألف مجاهد يملكون تفوقًا في الخيل، ومدافِعُهم أربعة وثلاثون مِدفعًا فقط، وكانت معنوياتهم مرتفعةً جدًّا, وقد أرسل العثمانيون لهم مُدرَّبين وأسلحة متنوعة، مشفوعة بفيلق عسكري, فقامت معركة بين الطرفين صباح الاثنين 30 جمادى الآخرة من هذه السنة تسمى معركة وادي المخازن، أو ما يعرف بمعركة الملوك الثلاثة، والتي تُسمَّى في كتب التاريخ معركة القصر الكبير، استمرت ما يزيد على الأربع ساعات، كتب الله فيها النصر للإسلام والمسلمين، وقد قُتِلَ في المعركة مَلِكُ السعديين عبد الملك أبو مروان، والملك المخلوع ابن أخيه محمد الثاني المتوكل على الله، والملك سبستيان ملك البرتغال، وقد وصَفَ بعض مؤرخي البرتغال نتائجَ المعركة بقوله: كان مخبوءًا لنا في مستقبل الأعصار العصرُ الذي لو وصفتُه لقلتُ: هو العصرُ النحسُ البالِغُ النحوسةِ، الذي انتهت فيه مدَّةُ الصولة والظفر والنجاح، وانقَضَت فيه أيامُ العناية من البرتغال، وانطفأ مصباحُهم بين الأجناس، وزال رونقُهم، وذهبت النخوةُ والقوة منهم، وخلفها الفشلُ الذريع، وانقطع الرجاء واضمحلَّ إبَّان الغنى والربح، وذلك هو العصر الذي هلك فيه سبستيان في القصر الكبير في بلاد المغرب, وكان من أهم أسباب هذه المعارك رغبةُ البرتغاليين أن يمحو عن أنفسهم العار والخزي الذي لحقهم بسبب ضربات المغاربة الموفَّقة، والتي جعلتهم ينسحبون من آسفي وأزمور وآصيلا وغيرها في زمن يوحنا الثالث (1521-1557م)، كما أراد مَلِكُ البرتغال الجديد سبستيان بن يوحنا أن يخوض حربًا مقدَّسة ضِدَّ المسلمين حتى يعلوَ شأنه بين ملوك أوروبا، وزاد من غروره ما حقَّقه البرتغاليون من اكتشافات جغرافية جديدة أراد أن يستفيد منها من أجل تطويق العالم الإسلامي، يدفعُه في ذلك حِقدُه على الإسلام وأهلِه عمومًا، وعلى المغرب خصوصًا، فجمع بين الحقدِ الصليبي والعقليَّة الاستعمارية التي ترى أنَّ يدها مُطلقةٌ في كل أرض مسلمة تعجِزُ عن حماية نفسِها من أي خطر خارجي."},{"id":3783,"title":"وفاة ملك السعديين عبد الملك بن السلطان محمد الشيخ السعدي .","date":["العام الهجري :986","الشهر القمري : جمادى الآخرة","العام الميلادي :1578"],"text":"هو السلطان أبو مروان عبد الملك ابن السلطان محمد الشيخ السعدي ملك السعديين، تولى حكم المغرب بعد أن انتزعَه من ابن أخيه محمد الثاني، الذي أعلن من بداية حكمِه العداءَ لأعمامه أبي مروان وأبي العباس، فاستعانا بالعثمانيين، فقَدَّموا لهما الدعم حيث تمكن عبد الملك من حكم المغربِ وأخوه أبو العباس ساعِدُه الأيمن. كان أبو مروان خلافَ أخيه الغالب بالله وابنه محمد الثاني في التعاون مع الإسبان والبرتغال ضِدَّ الدولة العثمانية؛ فقد دخل عبد الملك في حلف مع العثمانيين الذين قدَّموا له الدعم العسكري في حربه مع الإسبان. توفي في أرض المعركة؛ معركةِ وادي المخازن، فخلفه أخوه المنصور أحمد أبو العباس المعروف بالذهبي، واستمَرَّ أحمد المنصور على منهج أخيه في بناء المؤسسَّات، واقتناء ما وصلت إليه الكشوفاتُ العلمية، وتطويرِ الإدارةِ والقضاء والجيشِ، وترتيبِ الأقاليم وتنظيمها، وكان أحمد المنصور يتابِعُ وزراءه وكبار موظفيه ويحاسِبُهم على عدم المحافظة على أوقات العمل الرسمية، أو التأخير في الردِّ على المراسلات الإدارية والسياسية، وأحدث حروفًا لرموز خاصة بكتابة المراسلات السرية، حتى لا يعرِفَ فحواها إذا وقعت في يد عدوٍّ، وهذا يدل على اهتمامِه الشخصي بجهاز الأمن والاستخبارات التي تحمي به الدولة من الأخطار الداخلية والخارجية."},{"id":3784,"title":"مبايعة السلطان المنصور أحمد بن محمد السعدي بحكم المغرب .","date":["العام الهجري :986","الشهر القمري : جمادى الآخرة","العام الميلادي :1578"],"text":"بعد انتصار المسلمين على النصارى في معركةِ وادي المخازن التي توفِّيَ أثناءها أبو مروان عبد الملك السعدي, تمَّت بيعةُ المنصور أحمد بن محمد الشيخ السعدي المعروف بالذهبي، بعد أن اجتمع عليه مَن حضر هناك من أهل الحَلِّ والعقدِ، ثم لَمَّا قفل المنصور من غزوته تلك، ودخل حضرةَ فاس يوم الخميس عاشر جمادى الآخرة من هذه السنة جُدِّدت له البيعةُ بها ووافق عليه من لم يحضُر يوم وادي المخازن، ثم بعث إلى مراكش وغيرها من حواضر المغرب وبواديه فأذعن الكلُّ للطاعة وسارعوا إلى الدخول فيما دخلت فيه الجماعة."},{"id":3785,"title":"معركة قويون كجيدي وانتصار العثمانيين فيها على الصفويين  .","date":["العام الهجري :986","الشهر القمري : رجب","العام الميلادي :1578"],"text":"انتصر العثمانيون على الصفويين في معركة قويون كجيدي، والتي قُتِلَ فيها من الصفويين خمسة آلاف جندي، وهذا ما مهَّد السبيل لسيطرة العثمانيين على شيروان (أذربيجان حاليًّا)."},{"id":3786,"title":"معركة شماهي وانتصار العثمانيين فيها على الصفويين .","date":["العام الهجري :986","الشهر القمري : رمضان","العام الميلادي :1578"],"text":"انتصارُ العثمانيين على الصفويين في معركة شماهي، وقع ذلك في القفقاس، وقد خسر الصفويون في هذه المعركة 15 ألف قتيل، وجاءت هذه المعركة في إطار حروبٍ طاحنة بين الجانبين؛ للسيطرة على زعامة العالمِ الإسلاميِّ."},{"id":3787,"title":"غلاء عظيم بالمغرب .","date":["العام الهجري :987","العام الميلادي :1579"],"text":"وقع غلاءٌ عظيم بالمغرب، حتى عُرِف ذلك العام بعام البقول، وقيل إنه لما انتهب الناسُ غنيمة وادي المخازن، كان الناس يتوقَّعون مغبَّتها لاختلاط الأموال بالحرامِ، فظهر أثر ذلك من غلاءٍ وغيره، وكان يقال بأن البركةَ رُفِعت من الأموال من يومئذ."},{"id":3788,"title":"مرضُ المنصور أبي العباس أحمد السعدي  .","date":["العام الهجري :987","الشهر القمري : جمادى الأولى","العام الميلادي :1579"],"text":"مَرِضَ المنصور أبو العباس أحمد السعدي مرضًا مَخوفًا وطال به حتى كادت الأمور تختلُّ، ثم تداركه اللهُ على يد الحكيم الماهر أبي عبد الله محمد الطبيب، وكان يوم خروجه يومًا مشهودًا."},{"id":3789,"title":"رفع الصفويين حصارهم عن العثمانيين في تفليس .","date":["العام الهجري :987","الشهر القمري : جمادى الآخرة","العام الميلادي :1579"],"text":"حاصر 15 ألف جندي صفوي ما يقرُبُ من 1800 جندي عثماني في تفليس، وقد استمرَّ هذا الحصار 124 يومًا، ولم يرفع الصفويون الحصار إلَّا بعد سماعهم أصوات الموسيقى العسكرية العثمانية التي جاءت لنجدة تفليس."},{"id":3790,"title":"الدولة العثمانية تؤسس أميرالية الخزر .","date":["العام الهجري :987","الشهر القمري : رجب","العام الميلادي :1579"],"text":"أسَّست الدولة العثمانية أميرالية الخزر، وهي قيادة بحرية في داغستان, وكان أسطولها الرئيسي في ميناء باكو في أذربيجان حاليًّا، وكان أول أمير لها هو محمد بك، وقد انتهت هذه الأميرالية بسبب انتقال داغستان وشيروان أذربيجان إلى حوزة الصفويين."},{"id":3791,"title":"وفاة الصدر الأعظم صوقوللو محمد باشا رئيس وزراء الدولة العثمانية .","date":["العام الهجري :987","الشهر القمري : شعبان","العام الميلادي :1579"],"text":"هو صوقوللو محمد باشا: سياسي عثماني، أشهَرُ من تولى منصِبَ الصدر الأعظم في الدولة العثمانية، أصلُه من البوسنة، كانت عائلته صربيةً نصرانية، ولد سنة 912 في سراييفو، دخل في خدمة الدولة العثمانية عن طريق نظامِ الدوشيرمة، والذي من خلاله يُؤخَذُ أولاد السكَّان النصارى من أُسَرِهم في سن مبكِّر من الطفولة ويُربَّون في معسكرات خاصة بهم، ويتعلمون هناك اللغة والعادات والتقاليد التركية، وحب الشهادة والدين الإسلامي، خدَمَ لدى ثلاث سلاطين صدر أعظم ورئيس وزراء الدولة العثمانية، وهم: سليم الأول، وسليم الثاني، ومراد الثالث, وتولى منصب قائد البحرية العثمانية في عهد سليمان الأول، وأصيب بطعنة في قلبه نتيجة مؤامرات ضِدَّه في عهد السلطان مراد الثالث، وبعد فترة توفِّيَ ودفن في مقبرة بمنطقة أيوب سلطان، وكان قد ظلَّ في الصدارة- أي رئاسة الوزراء- العثمانية مدة 14 عامًا، وهي أطول فترة قضاها صدر أعظم في الصدارة!"},{"id":3792,"title":"مبايعة المأمون ابن المنصور أبي العباس أحمد السعدي بولاية العهد .","date":["العام الهجري :987","الشهر القمري : شعبان","العام الميلادي :1579"],"text":"لما شفيَ المنصور أحمد السعدي من مرضه الذي ألمَّ به, وعاد إلى حاله من الصحة؛ أجمع رأي أعيان الدولة السعدية واتَّفقت كلمة كبرائها على أن يطلبوا منه تعيينَ من يلي الأمرَ بعده، ويكون وليَّ عهده، وكان المنصور مهيبًا لا يقدِرُ أحد على مواجهته بمثل هذا، فاتفقوا على أن يكون البادئ لذلك القائِدَ المؤمن بن الغازي العمري؛ لِما له من الإدلال على المنصور بطول الخدمة وسالف التربية، فقال له ابن الغازي: يا مولانا، الله تعالى حَفِظَ البلاد بإبلالك من هذا المرض، وقد بقي الناس في أيام سقمك في حيرةٍ عظيمةٍ، ودخلهم من الدهَشِ ما لا يخفى عليك، فلو عيَّنت لنا من أبنائك من تجتمعُ كلمة الإسلام عليه، ويشار بالخلافةِ إليه من بعدُ؛ لكان أولى وأليق بسياسة المُلك, وإنَّ ابنك أبا عبد الله محمد المأمون حقيقٌ بذلك, فاستحسن المنصور ذلك وأعجبه ما أشار عليه به، فقال له: سوف أستخير الله في ذلك، فإن يكن من عند الله يُمضِه, ثمَّ لبث المنصور بعد هذه الإشارة أيامًا يستخير ربه في ذلك ويستشير من يعلمُ أهليَّته للمشورة من أهل العلم والصلاح، فلما انقضت أيام الاستخارة وتواطأت الآراءُ على حسن تلك الإشارة، جمع المنصور أعيان حاضرة مراكش وأعيان مدينة فاس، وغيرهم من أشياخ القبائل بوجوه الناس من أهل الحواضر والبوادي، وأوصى بالعهد لولده أبي عبد الله محمد المأمون، وذلك يوم الاثنين مُنسلَخَ شعبان من هذه السنة."},{"id":3793,"title":"ثورة داود بن عبد المؤمن بن محمد الشيخ السعدي على عمه المنصور .","date":["العام الهجري :988","العام الميلادي :1580"],"text":"لما وقعت البيعةُ للمأمون عبد الله بن المنصور أحمد السعدي العام الماضي وتكاملَ أمرُها، ثار الرئيس أبو سليمان داود بن عبد المؤمن ابن السلطان محمد الشيخ، وهو ابن أخي المنصور، وفرَّ إلى جبل سكسيوة وشقَّ عصا الطاعة ودعا إلى نفسه، فانثالت عليه أوشابٌ من البربر وغيرهم، ونجَمَ أمرُه وأثَّرت في أذن الرعية جعجعتُه، فبعث إليه المنصور قائدَه الزعيم أبا عبد الله محمد بن إبراهيم بن بجة، فناوشه القتال بجبل سكسيوة، فهزمه وفرَّ إلى جبل هوزالة، فتحزبوا عليه وقَوِيَت بهم شوكته، وأخذ يشنُّ لهم الغارات على أهل درعة إلى أن ضاقوا به ذرعًا، فشكَوا أمره إلى المنصور، فبعث إليه قائده الذي ذُكِرَ فلم يزَلْ في مقابلته ومقاتلته إلى أن شرَّده عن جبل هوزالة، ففرَّ داود منه إلى الصحراء واستقرَّ به الرحيل بها عند عرب الودايا من بني معقل، فلم يزل عندهم إلى أن هلك، وكُفِيَ المنصورُ أمرَه."},{"id":3794,"title":"والي مصر حسن باشا يأمر بتغيير لباس اليهود والنصارى .","date":["العام الهجري :988","الشهر القمري : صفر","العام الميلادي :1580"],"text":"أمر والي مصر حسن باشا الخادم بتغيير لباسِ اليهود والنصارى، فبدل العمائِمَ الصُّفرَ للنصارى، أصبحت البرانيطَ السود، وبدَّل العمائم الزُّرق لليهود، أصبحت الطراطيرَ السود."},{"id":3795,"title":"العثمانيون يستولون على شروان من بلاد الصفويين والكرج سكان جورجيا وغيرها .","date":["العام الهجري :989","العام الميلادي :1581"],"text":"بعد أن تولى الشاه محمد خدابنده واختلف عليه الناسُ وحدثت عدَّةُ ثورات وتزعزعت الأوضاع الداخلية، انتهز العثمانيون هذه الفرصة فأرسلوا جيشًا احتلَّ الكرج ودخل عاصمتَها تفليس، ثم دخلوا بعد انقضاء الشتاء إلى شوران أذربيجان الشمالية، ثم تابعوا مسيرَهم بقيادة عثمان باشا على بلاد داغستان، ثمَّ سار إلى بلاد القرم عبر جبال القوقاز لتأديبِ خان القرم، الذي رفض إرسال مَدَد للعثمانيين لمحاربة الصفويين، وقد أنهكه التعبُ لبعد الشُّقَّة ولغارات الروس عليه، وأخيرًا تمكَّن خان القرم من حصارِه، فمنَّى عثمان باشا أخا الخان بالحُكم، فترك أخاه وانضمَّ للعثمانيين بعد أن قتل أخاه بالسُّم، فدخل عثمان باشا إلى كافا عاصمة القرم ثم رجع إلى إستانبول."},{"id":3796,"title":"محاولة العثمانيين أخذ المغرب وجعلها ولاية عثمانية .","date":["العام الهجري :989","العام الميلادي :1581"],"text":"بدأت القوات الإسبانية في اكتساح الأراضي البرتغالية، ولم يستطِع الأمير البرتغالي دون أنطونيو مقاومةَ تلك القوات الإسبانية، التي ضمَّت أراضيه لسنة 988 (1580م)، عند ذلك اقترح السلطان العثماني مراد الثالث على السلطان أحمد المنصور السعدي عقْدَ تحالف عسكري ضِدَّ الإسبان، على أساس إمداده بأسطول حربي وقوات عسكرية، فبعث برسالتين في رجب 988 (سبتمبر 1580م) يعرِضُ عليه فيهما إرسال إمدادات عسكرية لفاس يستفتحُ بها بلاد الأندلس، لكنَّ المنصور لم يتجاوب مع السلطان مراد الثالث. كان قلج علي بعد استقرار الدولة العثمانية في تونس بدأت أنظارُه تتطلَّع إلى المغرب، وأخذ يعمل في توحيد الوجهةِ السياسية لبلاد المغرب الإسلامي؛ لضَمِّه إلى الدولة العثمانية، خاصةً بعد تذبذب موقفِ السلطان أحمد المنصور السعدي الأخير من الدولة العثمانية، فصدرت الأوامِرُ إلى قلج علي قائد الأسطول العثماني بالتوجُّه إلى المغرب لضَمِّه للدولة العثمانية، فوصل قلج علي إلى الجزائر في جمادي الثانية من هذه السنة، بينما كان المنصور يرابِطُ بقواته عند نهر تانسيفت، وكانت القواتُ المغربية قد استعدَّت لمواجهة التدخل العثماني؛ إذ جهَّز المنصور جنودَه وتقدَّم بها حتى حدودِ بلاده، كما سَدَّ مدخل مملكته، وحصَّن الثغور، وإلى جانب تلك الاستعدادات وجَّه المنصور سفارةً خاصة لإسطنبول، وذلك بعد أن توصَّل إلى شبه اتفاق عسكري مع الملك الإسباني الذي انتهى من مشاكلِه بدخوله للعاصمة البرتغالية لشبونة في 27 جمادى الآخرة من هذه السنة, على أساس تقديم المساعدة العسكرية للمغرب، لمواجهة التدخل العثماني، مقابِلَ التنازل عن مدينة العرائش وامتيازات أخرى، وأمام تطور الأحداث لم يجِد السلطان العثماني بدًّا من قبول الأمر الواقع والتراجع عن غزو المغرب، بأن أمَرَ قلج علي، وجعفر باشا نائب قلج علي في الجزائر، بالتخلي عن العمل بالمغربِ والانتقال إلى الشرق؛ حيث اضطربت الأمور بالحجاز، فتخلى قلج علي عن هدفِه الطموح في استرداد الأندلس، بعد توحيد الجبهة لبلاد المغرب الإسلامي!"},{"id":3797,"title":"فتح العثمانيين مدينة إيريفان الإيرانية  .","date":["العام الهجري :990","العام الميلادي :1582"],"text":"احتلَّ العثمانيون مدينة إيريفان الإيرانية بقيادة السردار فرحات باشا، وبنى بها حصن إيريفان مكان حصن أرمني قديم على ضفاف نهر هردزان، وبقي العثمانيون في المدينة حتى عام 1603م حين استعادها الصفويون مرةً أخرى إثر الحروبِ العثمانية الصفوية الأولى."},{"id":3798,"title":"استيلاء المنصور أحمد السعدي على بلاد الصحراء تيكورارين وتوات .","date":["العام الهجري :990","العام الميلادي :1582"],"text":"لما استقرَّ المنصور أحمد السعدي بمراكش، وأمن من هجوم العثمانيين على المغرب، طَمِحت نفسُه إلى التغلب على بلاد تيكورارين وتوات من أرض الصحراء وما انضاف إلى ذلك من القرى والمداشر- المزارع- إذ كان أهل تلك البلاد قد انكفَّت عنهم أيدي الملوك ولم تَسُسْهم الدول منذ أزمان، ولا قادهم سلطانٌ قاهر إلى ما يراد منهم، فسنح للمنصور أن يجمع بهم الكلمةَ ويرُدَّهم إلى أمر الله، فبعث إليهم القائِدَ أبا عبد الله محمد بن بركة والقائِدَ أبا العباس أحمد بن الحداد العمري المعقلي في جيش كثيف، فقطعوا إليهم القفرَ من مراكش وانتهوا إليهم على سبعين مرحلة منها، فتقدموا إليهم أولًا بالدعاء للطاعة والإعذار والإنذار فامتنعوا، فنازلوهم وقاتلوهم وطالت الحربُ بينهم أيامًا، ثم كان الظهور لجيش المنصور فأوقعوا بهم وأثخنوا فيهم إلى أن أذعنوا للطاعة وصاروا في حزب الجماعة، وأُنهي خبر الفتح إلى المنصور فسُرَّ بذلك سرورًا عظيمًا."},{"id":3799,"title":"العثمانيون يهاجمون شواطئ إسبانيا .","date":["العام الهجري :990","العام الميلادي :1582"],"text":"جهَّز الوالي العثماني في الجزائر أسطولَه في هذه السنة لمحاربة إسبانيا فوق أرضِها، فنزل المجاهدون المسلمون في برشلونة، فأعملوا فيها تدميرًا ثم عبَروا مضيقَ جبل طارق وهاجموا جزر الكناري التي تحتلُّها إسبانيا، فدمَّروا المراكز العسكرية وغَنِموا ما فيها ولم يكن الأسطول العثماني يذهب للأندلس لمجرد التنكيل بالإسبانيين ولتدمير منشآتهم، بل كان بالدرجة الأولى لإنقاذ المسلمين من نكبتهم، وتعرَّض المجاهدون أثناء ذلك لمعاركَ قاسية وهزائم أحيانًا، وفي 992, أبحر حسن فنزيانو بأسطوله على ثغرِ بلنسية، وحمل أعدادًا كبيرة من مسلمي الأندلس؛ إذ أنقذهم من اضطهاد الإسبان، كما استطاع في السنة التالية إنقاذَ جميع سكان كالوسا؛ إذ حملهم إلى الجزائر، وفي السنة التي بعدها توغَّل مراد رايس في المحيط الأطلسي فأغار على جزر الكناري، وغَنِمَ منها غنائمَ كثيرة بما فيهم زوجة حاكم تلك الجزر، وبقي حسن فنزيانو على رأس الحكومة العثمانية بالجزائر إلى أن استدعاه السلطان في إسطنبول ليتولى منصب إمارة البحر \" قبودان دوريا \" وذلك بعد وفاة قلج علي سنة 995."},{"id":3800,"title":"معركة \"مشعلة لر\" وانتصار العثمانيين على الصفويين فيها .","date":["العام الهجري :991","الشهر القمري : ربيع الآخر","العام الميلادي :1583"],"text":"انتصر العثمانيون على الصفويين في معركة \"مشعلة لر\" الطاحنة, وقد جاء هذا الانتصارُ بعد ثلاثة أيام من القتال، أثناء نزاع الفريقين للسيطرة على شيروان (أذربيجان حاليًّا)، وقد خَسِر الصفويون في هذه المعركة حوالي 11 ألف قتيل."},{"id":3801,"title":"معركة \"ديزفول\" وانتصار العثمانيين على الصفويين فيها .","date":["العام الهجري :991","الشهر القمري : شوال","العام الميلادي :1583"],"text":"انتصر العثمانيون على الصفويين في معركة ديزفول, وقد جاءت هذه الحربُ بعد سيطرة العثمانيين على سواحِلِ خليج البصرة الشمالية."},{"id":3802,"title":"تنازل الصفويين عن بعض بلادهم لصالح العثمانيين .","date":["العام الهجري :993","العام الميلادي :1584"],"text":"بعد أن دخل العثمانيون بعض بلاد الصفويين سنة 991, ورجع عثمان باشا إلى إستانبول، عاد في هذه السنة إلى غزو الصفويين وانتصر على قائدِهم حمزة ميرزا، ودخل تبريز عاصمَتَهم ثم جرى الصلح بين الطرفين، وتنازل الصفويون للعثمانيين عن بلاد الكرج وشروان ولورستان الواقعة جنوب أذربيجان."},{"id":3803,"title":"ثورة الحاج قرقوش ببلاد غمارة ومقتله .","date":["العام الهجري :993","العام الميلادي :1584"],"text":"ثار رجل يقال له الحاج قرقوش بجبال غمارة وبلاد الهبط، وتسمَّى بأمير المؤمنين، وكان في ابتداء أمره حائكًا، وظهر عليه الزهد والصلاح، واعتقدته العامةُ، ثم استحال أمرُه فأُخِذَ وقُتل وحُمِل رأسه إلى مراكش، وانقطعت مادةُ فساده."},{"id":3804,"title":"فتح العثمانيين مدينة تبريز الإيرانية .","date":["العام الهجري :993","الشهر القمري : شعبان","العام الميلادي :1585"],"text":"فتح العثمانيون مدينة تبريز الإيرانية، وقد كانت هذه المدينة عاصمةَ الدولة الصفوية، وأسَّس العثمانيون إيالة تبريز التي استمرَّت حوالي 18 عامًا."},{"id":3805,"title":"العثمانيون يسيطرون على مقديشيو ويبعدون الخطر البرتغالي .","date":["العام الهجري :994","العام الميلادي :1585"],"text":"استطاع الأسطولُ العثماني أن يجتاز القرنَ الإفريقيَّ ويستولي على مقديشيو وغيرها من المحطات الواقعة على شواطئ الصومال؛ بحيث لم يبقَ في أيدي البرتغال سوى ملندى وموضعين آخرين، وبذلك سيطر العثمانيون على الساحل الإفريقي الشرقي، وقطعوا خطَّ المواصلات حول إفريقيَّةَ عن المستعمرات البرتغالية في الهند."},{"id":3806,"title":"خلع الشاه محمد خدابنده وتولي عباس الأول مكانه .","date":["العام الهجري :995","العام الميلادي :1586"],"text":"بعد أن تولى محمد خدابنده مُلكَ الصفويين وبقي إلى هذا العام؛ حيث خلعه عباسُ بن طهماسب المعروف بعباس الكبير، وعمره كان سبعة عشر عامًا، فسعى عباس إلى إقامة صلح مع العثمانيين، تنازل بمقتضاه عن تلك الأماكن التي أصبحت بيَدِ العثمانيين عام 993 كما تعهَّد بعدم سبِّ الخلفاء الراشدين أبي بكر وعمر وعثمان رضي الله عنهم، في أرض مملكته، وبعث بابن عمٍّ له يدعى حيدر ميزرا رهينةً إلى إستانبول؛ لضمان تنفيذ ما اتفقا عليه."},{"id":3807,"title":"معركة كارفو وانتصار الجيش البولوني على الجيش الألماني  .","date":["العام الهجري :996","الشهر القمري : رمضان","العام الميلادي :1588"],"text":"هزم الجيش البولوني المعزَّز بوحدات الصاعقة التركية نظيرَه الجيش الألماني في معركة كارفو، وأُسِرَ الأرشيدق الألماني سيجموند، ويرجع سبب هذه المعركة إلى رغبة الألمان في السيطرة على العرش البولوني الذي كان تابعًا للدولة العثمانية حتى عام 1592م."},{"id":3808,"title":"العثمانيون ينتصرون على الصفويين .","date":["العام الهجري :996","الشهر القمري : ذي القعدة","العام الميلادي :1588"],"text":"انتصر العثمانيون بقيادة جعفر باشا حاكم شيروان (أذربيجان حاليًّا) على الصفويين بقيادة زياد أوغلو محمد خان، وقتلوا نصفَ الجيش الصفوي، وقد مهَّد هذا الانتصار الطريقَ لعقد معاهدة إستانبول عام 998 بين الجانبين."},{"id":3809,"title":"معاهدة إستانبول بين الدولة العثمانية والدولة الصفوية في إيران .","date":["العام الهجري :998","الشهر القمري : جمادى الأولى","العام الميلادي :1590"],"text":"عَقَدت الدولة العثمانية معاهدةَ إستانبول مع الدولة الصفوية في إيران، وكانت هذه المعاهدة قد أنهت الحربَ الشرسة بين الدولتين التي استمرت 12 عامًا، واعترفت إيران في هذه المعاهدة باحترام حرية المذهبِ السنيِّ، ووافقت على عَدَمِ سَبِّ الصحابة، وعلى مبادلة الأسرى بين الجانبين."},{"id":3810,"title":"إحباط العثمانيين أول مساعي اليهود للاستيطان في فلسطين .","date":["العام الهجري :999","العام الميلادي :1590"],"text":"ظنَّ اليهودُ أنَّ الفرصةَ سانحة لهم لتحقيقِ حُلمٍ راودهم طويلًا، فنزحوا في هجراتٍ متقطعة ومتقاربة إلى سيناء لاستيطانِها، وكانت خطَّتُهم تقوم في المراحل الأولى على تركيز إقامتِهم في مدينة الطور، وكان اختيارُهم لهذه المدينة اختيارًا هادفًا؛ فهذه المدينة- وهي تقع على الشاطئ الشرقي لخليج السويس- لها ميناء يصلح لرسو السفن التجارية، وكانت تأتيها سفن من جدَّة، وينبع، وسواكن، والعقبة، والقلزم، كما كانت المدينة ترتبط برًّا بخطِّ قوافل مع القاهرة والفرما، وبذلك كان يسهل على اليهود إيجاد اتصالات خارجية، فلا يصبحون في عزلةٍ عن العالم، بل تستطيع السفن أن ترسوَ في ميناء الطور تحمِلُ أفواجًا من اليهود الجُدُد، وقد تزعَّم حركةَ التهجير رجلٌ يهودي اسمه إبراهام، استوطن الطورَ مع أولاده وسائر أفراد أسرته، ولما أقام اليهودُ بالطور تعرَّضوا بالأذى لرهبان دير سانت كاترين؛ ممَّا دفعهم إلى إرسال شكاوى مكتوبة إلى سلاطين الدولة العثمانية وولاتها، يشتكون من إيذاء اليهود لهم مذكِّرين بعهد العثمانيين لحمايتِهم، ومنْع اليهود استيطان سيناء، ومحذِّرين من نزوح اليهود إلى سيناء، وخاصة مدينة الطور، في جماعات كثيرة بقصد إيقاعِ الفتن، ولما كانت الدولةُ الإسلامية مسؤولة بحكم الشرع عن حماية أهلِ الذمَّة، فقد سارع على الفور المسؤولون العثمانيون إلى إصدار ثلاثة فرمانات ديوانية في عهد السلطان مراد الثالث، فأمروا بإخراج إبراهام اليهودي وزوجتِه وأولاده وسائر اليهود من سيناء، ومنعهم في قابل الأيام منعًا باتًّا من العودة إليها بما فيها مدينة الطور والإقامة بها أو السكنى."},{"id":3811,"title":"الدولة السعدية تجتاح السودان الغربي .","date":["العام الهجري :999","العام الميلادي :1590"],"text":"قام الملك أبو العباس أحمد المنصور بن محمد المهدي- سلطانُ دولة السعديين بالمغرب- باجتياح السودان الغربي، الذي أخضع فيه سلطانَ سنغاي وأدخله في طاعته، فكانت هذه العملية في السودان الغربي أول الحقوق التي انتدبت إليها الحكومة المغربية للتحدُّث عن سيادتها على موريتانيا والسنغال والنيجر."},{"id":3812,"title":"غزو السعديين السودان وفتحها .","date":["العام الهجري :999","الشهر القمري : جمادى الأولى","العام الميلادي :1591"],"text":"عزم السلطانُ أحمد المنصور السعدي على غزو السودان، فاشتغل بتجهيز آلة الحرب وما يحتاج إليه الجيشُ من آلة السفر ومهمَّاته، وأمر القوَّادَ أن يقوِّموا حِصَصَ القبائل وما يحتاجون إليه من إبلٍ وخيل وبغال، وأنَّ من أتى بجملٍ ضعيف يعاقَبُ، واشتغل هو بتقويم آلةِ الحرب من المدافِعِ والعجلات التي تحمِلُها، والبارود والرصاص والكور، وتقويم الخشب واللوح والحديد للغلائط، والسفن والفلك والمجاذيف والقلوع والبراميل والروايا لحمل الماء، وألَّف النجارون ذلك في البر إلى أن تألَّف، ثم خلعوه وشدوه أحمالًا، واستمر الحالُ إلى أن استوفى المنصورُ أمر الغزو في ثلاث سنين، ثم أمر بإخراج المضارب والمباني لوادي تانسيفت، فخرجت الأحمالُ والأثقال من مراكش في اليوم السادس عشر من ذي الحجة سنة 998 ونزلت العساكرُ وضَربت أبنيتَها خيلًا ورَجِلًا، وجملتها عشرون ألفًا، ومعهم من المعلمين البحرية والطبجية ألفان، فالمجموع اثنان وعشرون ألفًا، وعقد المنصور على ذلك الجيش لمولاه الباشا جؤذر، وشدَّ أزره بجماعةٍ من أعيان الدولة، فاختار منهم من يعلَمُ نجدته ويعرِفُ كفايته، وتخيَّر من الإبل كلَّ بازل وكوماء، ومن الخيل كلَّ عتيق وجرداء، ثم نهضوا في زيٍّ عظيم وهيئة لم يُرَ مِثلُها، وذلك في محرَّم من هذه السنة، وكتب المنصور إلى قاضي تنبكتو الفقيه العلامة أبي حفص عمر ابن الشيخ محمود بن عمراء قيت الصنهاجي يأمُره بحضِّ الناس على الطاعة ولزوم الجماعة. ولما نهضوا من تانسيفت جعلوا طريقَهم على ثنية الكلاوي، ثم على درعة، ودخلوا القفرَ والفيافي فقطعوها في مائةِ مرحلة، ولم يَضِعْ لهم عِقالُ بعير ولا نقص منهم أحدٌ، فنزلوا على مدينة تنبكتو ثغر السودان، فأراحوا بها أيامًا، ثم صاروا قاصدين دار إسحاق سكية، ولما سمع بقدومهم احتشدت أمَمُ السودان وقبائلُها وقبائل الملثمين المهادنين لهم، وخرج من مدينة كاغو يجر الشوك والمدَرَ يقال: إنه جمع مائة ألف مقاتل وأربعة آلاف مقاتل. وقيل: لم يقنَعْ بالجيوش التي جمع حتى أضاف إليها أشياخَ السَّحَرة وأهلَ النَّفث في العُقَد وأرباب العزائم والسيمياء؛ ظنًّا منه أن ذلك يغنيه شيئًا وهيهات! ولما تقارب الجمعان عبَّأ الباشا جؤذر عساكِرَه وتقدَّم للحرب فدارت بهم عساكِرُ السودان من كل جهة، وعقلوا أرجلَهم مع الإبِلِ وصبروا مع الضحى إلى العصر، وكانت سلاحهم إنما هي الحرشان الصغار والرِّماح والسيوف، ولم تكن عندهم هذه المدافعُ، فلم تُغنِ حرشانُهم ورماحُهم مع البارود شيئًا، ولما كان آخرُ النهار هبَّت ريح النصر وانهزم السودان، فولَّوا الأدبار وحقَّ عليهم البوار وحكَمَت في رقابهم سيوفُ جؤذر وجندُه، حتى كان السودان ينادون: نحن مسلمون، نحن إخوانُكم في الدين، والسيوفُ عاملة فيهم وجُندُ جؤذر يقتلون ويَسلبون في كلِّ وجهٍ، وفرَّ إسحاق في شرذمة من قومِه ولم يدخل قلعةَ مُلكِه، وتقدم جؤذر فدخلها واحتوى على ما فيها من الأموالِ والمتاعِ، وكان ذلك في منتصف جمادى الأولى من هذه السنة."},{"id":3813,"title":"زوال الدولة المهدوية .","date":["العام الهجري :999","الشهر القمري : رجب","العام الميلادي :1591"],"text":"زالت الدولةُ المهدوية بأحمد نكر من بلاد الدكن، وقُتل الوزير جمال خان وجيء برأسِه إلى أحمد نكر، وطِيفَ به فيها، ثم علِّق أيامًا وتسلطن رهان شاه."},{"id":3814,"title":"معاهدة بين الدولة العثمانية وبولونيا .","date":["العام الهجري :999","الشهر القمري : ذي القعدة","العام الميلادي :1591"],"text":"عقدت الدولةُ العثمانية معاهدةً مع بولونيا، ونصَّت هذه المعاهدة على تبعيَّةِ بولونيا (لتوانيا) للدولةِ العثمانية، وأن تُسدِّدَ بولونيا ربع مليون ليرة ذهبية سنويًّا إلى إستانبول، وأن تتبع بولونيا سياسةً خارجية متوافقةً مع السياسة الخارجيَّة العثمانية."},{"id":3815,"title":"انتشر الإسلام في وسط إفريقيا عبر مدينة تمبكتو في مالي .","date":["العام الهجري :1000","العام الميلادي :1591"],"text":"كانت الصحراء الكبرى من إفريقيا تحت نفوذ إمبراطورية سنغاي أو صنغاي الإسلامية التي تقع في الساحل الغربي من إفريقيا, وكان ملوكُها من الأسقيين وكبيرُهم الأول هو محمد الكبير الذي يعتبر هو أوَّلَ من نظَّم أمور المملكة، فنظَّم البلادَ والوظائِفَ، وأشرف على الشؤون القَبَلية، وفتح البلادَ ووسَّعها، وكان للدولةِ تنظيمُها الإداري وجيشُها النظامي وقضاتُها أصحابُ السُّلطات الشرعية, وفي عهدِهم تعتبرُ مدينة تمبكتو مركزًا هامًّا للدعوة الإسلامية في مالي وما حولها, فضلًا عن أنَّها كانت تمثِّلُ مركز الحضارة والعلمِ معًا، حيث خرَّجَت مئات العلماء، وكذلك العاصمة غاو، وإن كانت أقلَّ سكانًا، وكان الإسلامُ ينتشر فيها ويزدهِرُ بازدهار الدولة وانتشارِها."}]
